  FILTER(xsd:integer(?diversificationScore) < 25)

  ?scenarioRebalancing wm:scenario "Bear Market" .

  ?investmentGoal wm:progressPct ?progressPct .
  FILTER(xsd:decimal(?progressPct) < 100.0)
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?investor
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?riskTolerance ;
            wm:hasPortfolioHealth ?portfolioHealth ;
            wm:hasInvestmentGoal ?investmentGoal .

  ?riskTolerance rdfs:label "Aggressive" .

  ?portfolioHealth wm:diversificationScore ?divScore .
  FILTER (?divScore < 25)

  ?investmentGoal wm:progressPct ?progressPct .
  FILTER (?progressPct < 100)

  OPTIONAL { ?investor wm:hasScenarioRebalancing ?scenarioRebalancing . }
  FILTER (
    EXISTS {
      ?scenarioRebalancing wm:scenario "Approaching Goal"
    } ||
    !BOUND(?scenarioRebalancing)
  )
}

