PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?segment ?totalCashFlowAmount
WHERE {
  ?investor wm:investorId "INV-002" ;
            wm:hasSegment ?segmentObj ;
            wm:hasCashFlow ?cashFlow .
  ?segmentObj rdfs:label ?segment .
  ?cashFlow wm:amount ?amount .
  BIND(xsd:decimal(?amount) AS ?amt)
  BIND(SUM(?amt) AS ?totalCashFlowAmount)
}

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investmentGoal (COUNT(?rebalancingAction) AS ?rebalancingActionCount)
WHERE {
  ?investor wm:investorId "INV-003" ;
            wm:hasInvestmentGoal ?goal ;
            wm:hasRebalancingAction ?rebalancingAction .

  ?goal wm:investmentGoal ?investmentGoal .
}
GROUP BY ?investmentGoal

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance ?cashFlowType (COUNT(DISTINCT ?investor) AS ?distinctInvestorCount)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?rt .
  ?rt rdfs:label ?riskTolerance .

  ?cashFlow a wm:CashFlow ;
            wm:cashFlowOfInvestor ?investor ;
            wm:hasCashFlowType ?cft .
  ?cft rdfs:label ?cashFlowType .
}
GROUP BY ?riskTolerance ?cashFlowType
ORDER BY ?riskTolerance ?cashFlowType

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?category (AVG(?returnsPct) AS ?avgReturnsPct)
WHERE {
  ?investor wm:investorId "INV-004" ;
            wm:category ?category ;
            wm:hasHolding ?holding .
  ?holding wm:cost ?cost ;
           wm:currentValue ?currentValue ;
           wm:returnsPct ?returnsPct .
  FILTER (?cost > 0 && ?currentValue >= 0)
}
GROUP BY ?category

