  ?investor wm:hasCategory ?category ;
            wm:hasCashFlow ?cashFlow ;
            wm:hasPortfolioHealth ?health .
  ?cashFlow wm:hasCashFlowType ?cashFlowType .
  ?health wm:riskScore ?riskScore .
  FILTER (?riskScore > 50)
}
GROUP BY ?category ?cashFlowType
ORDER BY ?category ?cashFlowType

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?category ?action (COUNT(DISTINCT ?investorId) AS ?distinctInvestorCount)
WHERE {
  ?holding wm:heldByInvestor ?investor .
  ?investor wm:investorId ?investorId ;
            wm:hasCategory ?categoryObj ;
            wm:hasRebalancingAction ?rebalancingAction ;
            wm:hasPortfolioHealth ?portfolioHealth .

  ?categoryObj rdfs:label ?category .
  ?rebalancingAction wm:action ?action ;
                     wm:rebalancingActionOfInvestor ?investor .
  ?portfolioHealth wm:riskScore ?riskScore ;
                   wm:healthOfInvestor ?investor .

  FILTER (?riskScore > 50)
}
GROUP BY ?category ?action
ORDER BY ?category ?action

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance (COUNT(DISTINCT ?investor) AS ?distinctInvestorCount)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?rt ;
            wm:hasHolding ?holding ;
            wm:hasCashFlow ?cashFlow .

  ?rt rdfs:label ?riskTolerance .

  ?holding wm:hasInvestmentType ?invType ;
           wm:heldByInvestor ?investor .

  ?invType rdfs:label "Equity" .

  ?cashFlow wm:hasCashFlowType ?cfType ;
            wm:cashFlowOfInvestor ?investor .

  ?cfType rdfs:label "SIP" .

  ?health wm:healthOfInvestor ?investor ;
          wm:riskScore ?riskScore .

  FILTER (?riskScore > 25)
}
GROUP BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?holdingsPerInvestor), 2) AS ?avg_holdings_per_investor)
  (ROUND(AVG(?netCashFlow), 2) AS ?avg_net_cash_flow)
  (ROUND(AVG(?riskScore), 2) AS ?avg_risk_score)
WHERE {
  {
    SELECT 
      ?investor 
      (COUNT(?holding) AS ?holdingsPerInvestor)
    WHERE {
      ?investor a wm:Investor .
      OPTIONAL { ?holding wm:heldByInvestor ?investor . }
    }
    GROUP BY ?investor
  }
  {
    SELECT 
      ?investor 
      (SUM(xsd:decimal(?cashFlowAmount)) AS ?netCashFlow)
    WHERE {
      ?investor a wm:Investor .
      OPTIONAL {
        ?cashFlow wm:cashFlowOfInvestor ?investor ;
                  wm:amount ?cashFlowAmount .
      }
    }
    GROUP BY ?investor
  }
  {
    SELECT 
      ?investor 
      ?riskScore
    WHERE {
      ?investor a wm:Investor ;
                wm:hasPortfolioHealth ?health .
      ?health wm:riskScore ?riskScore .
    }
  }
  ?investor wm:hasRiskTolerance ?rt .
  ?rt rdfs:label ?riskTolerance .
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance (COUNT(DISTINCT ?investor) AS ?distinctInvestorCount)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?riskTolerance ;
            wm:hasHolding ?holding ;
            wm:hasCashFlow ?cashFlow .

  ?holding a wm:PortfolioHolding ;
           wm:investmentName "Gold" .

  ?cashFlow a wm:CashFlow ;
            wm:hasCashFlowType ?cashFlowType .

  ?cashFlowType rdfs:label "Deposit" .

  ?investor wm:hasPortfolioHealth ?portfolioHealth .
  ?portfolioHealth wm:riskScore ?riskScore .
  FILTER (?riskScore > 25)
}
GROUP BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?holdingsPerInvestor), 2) AS ?avg_holdings_per_investor)
  (ROUND(AVG(?rebalancingActionsPerInvestor), 2) AS ?avg_rebalancing_actions_per_investor)
  (ROUND(AVG(?riskScore), 2) AS ?avg_risk_score)
  (COUNT(?investor) AS ?n_investors)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?rt .
  ?rt rdfs:label ?riskTolerance .

  # Count holdings per investor
  OPTIONAL {
    SELECT ?investor (COUNT(?holding) AS ?holdingsCount)
    WHERE {
      ?holding wm:heldByInvestor ?investor .
    }
    GROUP BY ?investor
  }
  BIND(COALESCE(?holdingsCount, 0) AS ?holdingsPerInvestor)

  # Count rebalancing actions per investor
  OPTIONAL {
    SELECT ?investor (COUNT(?action) AS ?actionsCount)
    WHERE {
      ?action wm:rebalancingActionOfInvestor ?investor .
    }
    GROUP BY ?investor
  }
  BIND(COALESCE(?actionsCount, 0) AS ?rebalancingActionsPerInvestor)

  # Get risk score
  OPTIONAL {
    ?health wm:healthOfInvestor ?investor ;
            wm:riskScore ?riskScoreStr .
    BIND(xsd:float(?riskScoreStr) AS ?riskScore)
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance (COUNT(DISTINCT ?investor) AS ?distinctInvestorCount)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?rt ;
            wm:hasHolding ?holding ;
            wm:hasRebalancingAction ?rebalancingAction .

  ?rt rdfs:label ?riskTolerance .

  ?holding wm:hasInvestmentType ?invType ;
           wm:investmentType "ETF" .

  ?rebalancingAction wm:action "Buy" ;
                     wm:amount ?amount .

  ?health wm:healthOfInvestor ?investor ;
          wm:riskScore ?riskScore .

  FILTER(xsd:integer(?riskScore) > 25)
}
GROUP BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?netCashFlow)) AS ?avg_net_cash_flow_per_investor)
  (ROUND(AVG(?goalProgress), 2) AS ?avg_goal_progress_per_investor)
  (ROUND(AVG(?riskScore), 2) AS ?avg_risk_score_per_investor)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?rt .
  ?rt rdfs:label ?riskTolerance .

  # Net cash flow per investor
  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(?cfAmount)) AS ?netCashFlow)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:cashFlowOfInvestor ?investor ;
          wm:amount ?cfAmount .
    }
    GROUP BY ?investor
  }

  # Average goal progress per investor
  OPTIONAL {
    SELECT ?investor (AVG(xsd:decimal(?progressPct)) AS ?goalProgress)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?investor ;
            wm:progressPct ?progressPct .
    }
    GROUP BY ?investor
  }

  # Risk score per investor
  OPTIONAL {
    SELECT ?investor (xsd:decimal(?riskScore) AS ?riskScore)
    WHERE {
      ?ph a wm:PortfolioHealth ;
          wm:healthOfInvestor ?investor ;
          wm:riskScore ?riskScore .
    }
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance (COUNT(DISTINCT ?investor) AS ?distinctInvestorCount)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?riskTolerance ;
            wm:hasHolding ?holding ;
            wm:hasScenarioRebalancing ?scenario .

  ?holding a wm:PortfolioHolding ;
           wm:hasInvestmentType ?investmentType .

  ?investmentType rdfs:label "Mutual Fund" .

  ?scenario a wm:ScenarioRebalancing ;
            wm:scenario "Bull Market" .

  ?health a wm:PortfolioHealth ;
          wm:healthOfInvestor ?investor ;
          wm:riskScore ?riskScore .

  FILTER (?riskScore > 25)
}
GROUP BY ?riskTolerance

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance (COUNT(DISTINCT ?investor) AS ?investorCount)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?riskTolerance ;
            wm:hasPortfolioHealth ?health ;
            wm:hasHolding ?holding ;
            wm:hasInvestmentGoal ?goal .

  ?health wm:riskScore ?riskScore .
  FILTER (?riskScore > 25)

  ?holding wm:hasSector ?sector .
  ?sector rdfs:label "Real Estate" .

  ?goal wm:hasInvestmentGoalType ?goalType .
  ?goalType rdfs:label "Growth" .

}
GROUP BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?totalSectorInvestment)) AS ?avg_sector_investment)
  (ROUND(AVG(?avgHoldingReturn), 2) AS ?avg_holding_return)
  (ROUND(AVG(?riskScore), 2) AS ?avg_risk_score)
WHERE {
  {
    SELECT 
      ?investor 
      (SUM(xsd:decimal(?sa_totalInvestment)) AS ?totalSectorInvestment)
    WHERE {
      ?sa a wm:SectorAllocation ;
          wm:allocationOfInvestor ?investor ;
          wm:totalInvestment ?sa_totalInvestment .
    }
    GROUP BY ?investor
  }

  {
    SELECT 
      ?investor 
      (AVG(xsd:decimal(?ph_returnsPct)) AS ?avgHoldingReturn)
    WHERE {
      ?ph a wm:PortfolioHolding ;
          wm:heldByInvestor ?investor ;
          wm:cost ?ph_cost ;
          wm:currentValue ?ph_currentValue ;
          wm:returnsPct ?ph_returnsPct .
      FILTER (?ph_cost != "" && ?ph_currentValue != "")
    }
    GROUP BY ?investor
  }

  {
    SELECT 
      ?investor 
      (xsd:decimal(?ph_riskScore) AS ?riskScore)
    WHERE {
      ?ph a wm:PortfolioHealth ;
          wm:healthOfInvestor ?investor ;
          wm:riskScore ?ph_riskScore .
    }
  }

  ?investor wm:hasRiskTolerance ?rt .
  ?rt rdfs:label ?riskTolerance .
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?timeHorizonLabel AS ?time_horizon,
  ROUND(AVG(?holdingsPerInvestor), 2) AS ?avg_holdings_per_investor,
  ROUND(AVG(?netCashFlowPerInvestor), 2) AS ?avg_net_cashflow_per_investor,
  ROUND(AVG(?riskScore), 2) AS ?avg_risk_score
WHERE {
  {
    SELECT 
      ?investorId,
      ?timeHorizonLabel,
      (COUNT(?holding) AS ?holdingsPerInvestor),
      (SUM(xsd:decimal(?cashFlowAmount)) AS ?netCashFlowPerInvestor),
      (AVG(xsd:decimal(?riskScoreVal)) AS ?riskScore)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasTimeHorizon ?timeHorizon .
      ?timeHorizon rdfs:label ?timeHorizonLabel .

      OPTIONAL {
        ?holding a wm:PortfolioHolding ;
                 wm:heldByInvestor ?investor .
      }

      OPTIONAL {
        ?cashFlow a wm:CashFlow ;
                  wm:cashFlowOfInvestor ?investor ;
                  wm:amount ?cashFlowAmount .
      }

      OPTIONAL {
        ?health a wm:PortfolioHealth ;
                wm:healthOfInvestor ?investor ;
                wm:riskScore ?riskScoreVal .
      }
    }
    GROUP BY ?investorId ?timeHorizonLabel
  }
}
GROUP BY ?timeHorizonLabel
ORDER BY ?timeHorizonLabel

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?timeHorizonLabel AS ?time_horizon,
  ROUND(AVG(?holdingsPerInvestor), 2) AS ?avg_holdings_per_investor,
  ROUND(AVG(?rebalancingActionsPerInvestor), 2) AS ?avg_rebalancing_actions_per_investor,
  ROUND(AVG(?riskScore), 2) AS ?avg_risk_score
WHERE {
  ?investor wm:hasTimeHorizon ?timeHorizon .
  ?timeHorizon rdfs:label ?timeHorizonLabel .

  OPTIONAL {
    ?investor wm:hasHolding ?holding .
  }

  OPTIONAL {
    ?investor wm:hasRebalancingAction ?rebalancingAction .
  }

  OPTIONAL {
    ?investor wm:hasPortfolioHealth ?portfolioHealth .
    ?portfolioHealth wm:riskScore ?riskScore .
  }

  BIND(IF(BOUND(?holding), 1, 0) AS ?holdingExists)
  BIND(IF(BOUND(?rebalancingAction), 1, 0) AS ?rebalancingActionExists)
}
GROUP BY ?timeHorizonLabel
ORDER BY ?timeHorizonLabel

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance (COUNT(DISTINCT ?investor) AS ?distinctInvestorCount)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?riskTolerance ;
            wm:hasHolding ?holding ;
            wm:hasCashFlow ?cashFlow .

  ?holding a wm:PortfolioHolding ;
           wm:hasInvestmentType ?invType .

  ?invType rdfs:label "Corporate Bond" .

  ?cashFlow a wm:CashFlow ;
            wm:hasCashFlowType ?cfType .

  ?cfType rdfs:label "Withdrawal" .

  ?health a wm:PortfolioHealth ;
          wm:healthOfInvestor ?investor ;
          wm:riskScore ?riskScore .

  FILTER (?riskScore > 25)
}
GROUP BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?timeHorizonLabel AS ?time_horizon,
  ROUND(AVG(?netCashFlowPerInvestor), 2) AS ?avg_net_cash_flow_per_investor,
  ROUND(AVG(?avgGoalProgressPerInvestor), 2) AS ?avg_goal_progress_per_investor,
  ROUND(AVG(?riskScore), 2) AS ?avg_risk_score
WHERE {
  ?investor wm:hasTimeHorizon ?timeHorizon .
  ?timeHorizon rdfs:label ?timeHorizonLabel .

  OPTIONAL {
    ?cashFlow wm:cashFlowOfInvestor ?investor ;
              wm:amount ?amount ;
              wm:type ?type .
    BIND(IF(?type IN ("SIP", "Lump Sum", "Deposit"), -1 * xsd:decimal(?amount), xsd:decimal(?amount)) AS ?signedAmount)
  }

  OPTIONAL {
    ?goal wm:belongsToInvestor ?investor ;
          wm:progressPct ?progressPct .
  }

  OPTIONAL {
    ?health wm:healthOfInvestor ?investor ;
            wm:riskScore ?riskScoreRaw .
    BIND(xsd:decimal(?riskScoreRaw) AS ?riskScore)
  }

  {
    SELECT ?investor (SUM(?signedAmount) AS ?netCashFlowPerInvestor)
    WHERE {
      ?cashFlow wm:cashFlowOfInvestor ?investor ;
                wm:amount ?amount ;
                wm:type ?type .
      BIND(IF(?type IN ("SIP", "Lump Sum", "Deposit"), -1 * xsd:decimal(?amount), xsd:decimal(?amount)) AS ?signedAmount)
    }
    GROUP BY ?investor
  }

  {
    SELECT ?investor (AVG(xsd:decimal(?progressPct)) AS ?avgGoalProgressPerInvestor)
    WHERE {
      ?goal wm:belongsToInvestor ?investor ;
            wm:progressPct ?progressPct .
    }
    GROUP BY ?investor
  }
}
GROUP BY ?timeHorizonLabel
ORDER BY ?timeHorizonLabel

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?timeHorizonLabel AS ?time_horizon,
  ROUND(AVG(?totalSectorInvestmentPerInvestor), 2) AS ?avg_total_sector_investment,
  ROUND(AVG(?avgReturnPerInvestor), 2) AS ?avg_holding_return,
  ROUND(AVG(?riskScore), 2) AS ?avg_risk_score
WHERE {
  {
    SELECT 
      ?investorId,
      ?timeHorizonLabel,
      SUM(?sectorInvestment) AS ?totalSectorInvestmentPerInvestor,
      AVG(?returnsPct) AS ?avgReturnPerInvestor,
      SAMPLE(?riskScoreVal) AS ?riskScore
    WHERE {
      ?investor wm:hasTimeHorizon ?timeHorizon .
      ?timeHorizon rdfs:label ?timeHorizonLabel .

      OPTIONAL {
        ?sectorAlloc wm:allocationOfInvestor ?investor ;
                     wm:totalInvestment ?sectorInvestmentStr .
        BIND(xsd:decimal(?sectorInvestmentStr) AS ?sectorInvestment)
      }

      OPTIONAL {
        ?holding wm:heldByInvestor ?investor ;
                 wm:returnsPct ?returnsPctStr ;
                 wm:cost ?costStr ;
                 wm:currentValue ?currentValueStr .
        FILTER (?costStr != "" && ?currentValueStr != "")
        BIND(xsd:decimal(?returnsPctStr) AS ?returnsPct)
      }

      OPTIONAL {
        ?portfolioHealth wm:healthOfInvestor ?investor ;
                         wm:riskScore ?riskScoreStr .
        BIND(xsd:decimal(?riskScoreStr) AS ?riskScoreVal)
      }

      BIND(?investor AS ?investorId)
    }
    GROUP BY ?investorId ?timeHorizonLabel
  }
}
GROUP BY ?timeHorizonLabel
ORDER BY ?timeHorizonLabel

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?timeHorizon (COUNT(DISTINCT ?investor) AS ?distinctInvestors)
WHERE {
  ?investor wm:hasTimeHorizon ?timeHorizon ;
            wm:hasHolding ?holding ;
            wm:hasRebalancingAction ?rebalancingAction ;
            wm:hasPortfolioHealth ?portfolioHealth .

  ?holding wm:hasInvestmentType ?investmentType .
  ?investmentType rdfs:label "ETF" .

  ?rebalancingAction wm:action "Buy" .

  ?portfolioHealth wm:riskScore ?riskScore .
  FILTER (?riskScore > 25)
}
GROUP BY ?timeHorizon
ORDER BY ?timeHorizon

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?segment
  (ROUND(AVG(?holdingsPerInvestor), 2) AS ?avg_holdings_per_investor)
  (ROUND(AVG(?netCashFlow), 2) AS ?avg_net_cash_flow)
  (ROUND(AVG(?riskScore), 2) AS ?avg_risk_score)
WHERE {
  {
    SELECT 
      ?investor 
      (COUNT(?holding) AS ?holdingsPerInvestor)
    WHERE {
      ?investor a wm:Investor .
      OPTIONAL { ?holding wm:heldByInvestor ?investor . }
    }
    GROUP BY ?investor
  }
  {
    SELECT 
      ?investor 
      (SUM(xsd:decimal(?amount)) AS ?netCashFlow)
    WHERE {
      ?cashFlow wm:cashFlowOfInvestor ?investor ;
                wm:amount ?amount .
      BIND(IF(?cashFlowType = "Redemption" || ?cashFlowType = "Withdrawal", 
              xsd:decimal(?amount), 
              -xsd:decimal(?amount)) AS ?signedAmount)
    }
    GROUP BY ?investor
  }
  {
    SELECT 
      ?investor 
      ?riskScore
    WHERE {
      ?health wm:healthOfInvestor ?investor ;
              wm:riskScore ?riskScore .
    }
  }
  ?investor wm:hasSegment ?segmentObj .
  ?segmentObj rdfs:label ?segment .
}
GROUP BY ?segment
ORDER BY ?segment

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?segment
  (ROUND(AVG(?holdingsPerInvestor), 2) AS ?avgHoldingsPerInvestor)
  (ROUND(AVG(?rebalancingActionsPerInvestor), 2) AS ?avgRebalancingActionsPerInvestor)
  (ROUND(AVG(?riskScore), 2) AS ?avgRiskScore)
WHERE {
  {
    SELECT 
      ?investorId
      ?segment
      (COUNT(?holding) AS ?holdingsPerInvestor)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasSegment ?segEntity .
      ?segEntity rdfs:label ?segment .
      OPTIONAL {
        ?holding a wm:PortfolioHolding ;
                 wm:heldByInvestor ?investor .
      }
    }
    GROUP BY ?investorId ?segment
  }
  {
    SELECT 
      ?investorId
      (COUNT(?rebalancingAction) AS ?rebalancingActionsPerInvestor)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      OPTIONAL {
        ?rebalancingAction a wm:RebalancingAction ;
                           wm:rebalancingActionOfInvestor ?investor .
      }
    }
    GROUP BY ?investorId
  }
  {
    SELECT 
      ?investorId
      (MAX(xsd:decimal(?rs)) AS ?riskScore)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      OPTIONAL {
        ?health a wm:PortfolioHealth ;
                wm:healthOfInvestor ?investor ;
                wm:riskScore ?rs .
      }
    }
    GROUP BY ?investorId
  }
}
GROUP BY ?segment
ORDER BY ?segment

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?segment
  (ROUND(AVG(?netCashFlowPerInvestor), 2) AS ?avgNetCashFlow)
  (ROUND(AVG(?goalProgressPerInvestor), 2) AS ?avgGoalProgress)
  (ROUND(AVG(?riskScore), 2) AS ?avgRiskScore)
WHERE {
  {
    SELECT 
      ?investor 
      (SUM(xsd:decimal(?cashFlowAmount)) AS ?netCashFlowPerInvestor)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?cashFlowAmount .
    }
    GROUP BY ?investor
  }

  {
    SELECT 
      ?investor 
      (AVG(xsd:decimal(?progressPct)) AS ?goalProgressPerInvestor)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?investor ;
            wm:progressPct ?progressPct .
    }
    GROUP BY ?investor
  }

  ?investorProfile a wm:Investor ;
                   wm:investorId ?investorId ;
                   wm:segment ?segment ;
                   wm:hasCashFlow ?cashFlow ;
                   wm:hasInvestmentGoal ?investmentGoal ;
                   wm:hasPortfolioHealth ?portfolioHealth .

  ?cashFlow wm:cashFlowOfInvestor ?investor .
  ?investmentGoal wm:belongsToInvestor ?investor .
  ?portfolioHealth wm:healthOfInvestor ?investor ;
                   wm:riskScore ?riskScore .

  BIND(?investorProfile AS ?investor)
}
GROUP BY ?segment
ORDER BY ?segment

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?timeHorizon (COUNT(DISTINCT ?investor) AS ?distinctInvestorCount)
WHERE {
  ?investor wm:hasTimeHorizon ?timeHorizon ;
            wm:hasHolding ?holding ;
            wm:hasCashFlow ?cashFlow ;
            wm:hasPortfolioHealth ?health .

  ?holding wm:investmentType "Corporate Bond" .
  ?cashFlow wm:type "Withdrawal" .
  ?health wm:riskScore ?riskScore .

  FILTER (?riskScore > 25)
}
GROUP BY ?timeHorizon
ORDER BY ?timeHorizon

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?segment
  (ROUND(AVG(?total_sector_investment), 2) AS ?avg_total_sector_investment)
  (ROUND(AVG(?avg_return_pct), 2) AS ?avg_holding_return_pct)
  (ROUND(AVG(?risk_score), 2) AS ?avg_risk_score)
WHERE {
  {
    SELECT 
      ?investor 
      (SUM(xsd:decimal(?sa_total_investment)) AS ?total_sector_investment)
    WHERE {
      ?sa a wm:SectorAllocation ;
          wm:allocationOfInvestor ?investor ;
          wm:totalInvestment ?sa_total_investment .
    }
    GROUP BY ?investor
  }
  {
    SELECT 
      ?investor 
      (AVG(xsd:decimal(?ph_returns_pct)) AS ?avg_return_pct)
    WHERE {
      ?ph a wm:PortfolioHolding ;
          wm:heldByInvestor ?investor ;
          wm:returnsPct ?ph_returns_pct ;
          wm:cost ?ph_cost ;
          wm:currentValue ?ph_current_value .
      FILTER (?ph_cost != "" && ?ph_current_value != "")
    }
    GROUP BY ?investor
  }
  {
    SELECT 
      ?investor 
      (xsd:decimal(?ph_risk_score) AS ?risk_score)
    WHERE {
      ?ph a wm:PortfolioHealth ;
          wm:healthOfInvestor ?investor ;
          wm:riskScore ?ph_risk_score .
    }
    GROUP BY ?investor ?ph_risk_score
  }

  ?investor wm:hasSegment ?seg .
  ?seg rdfs:label ?segment .
}
GROUP BY ?segment
ORDER BY ?segment

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?categoryLabel AS ?category,
  ROUND(AVG(?holdingsPerInvestor), 2) AS ?avg_holdings_per_investor,
  ROUND(AVG(?netCashFlow), 2) AS ?avg_net_cash_flow,
  ROUND(AVG(?riskScore), 2) AS ?avg_risk_score
WHERE {
  {
    SELECT 
      ?investorId,
      ?categoryLabel,
      COUNT(?holding) AS ?holdingsPerInvestor,
      SUM(xsd:decimal(?cashFlowAmount)) AS ?netCashFlow,
      AVG(xsd:decimal(?riskScoreVal)) AS ?riskScore
    WHERE {
      ?investor wm:investorId ?investorId ;
                wm:hasCategory ?category .
      ?category rdfs:label ?categoryLabel .

      OPTIONAL {
        ?holding wm:heldByInvestor ?investor .
      }

      OPTIONAL {
        ?cashFlow wm:cashFlowOfInvestor ?investor ;
                  wm:amount ?cashFlowAmount .
      }

      OPTIONAL {
        ?health wm:healthOfInvestor ?investor ;
                wm:riskScore ?riskScoreVal .
      }
    }
    GROUP BY ?investorId ?categoryLabel
  }
}
GROUP BY ?categoryLabel
ORDER BY ?categoryLabel

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?segment (COUNT(DISTINCT ?investor) AS ?distinct_investor_count)
WHERE {
  ?investor wm:hasSegment ?segment ;
            wm:hasRiskTolerance/wm:riskScore ?riskScore ;
            wm:hasHolding ?holding ;
            wm:hasCashFlow ?cashFlow .

  ?holding wm:hasInvestmentType ?invType .
  ?invType rdfs:label "Equity" .

  ?cashFlow wm:hasCashFlowType ?cfType ;
             wm:source "SIP" .

  ?cfType rdfs:label "SIP" .

  FILTER (?riskScore > 25)
}
GROUP BY ?segment

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT 
  ?category
  (COUNT(?holding) / COUNT(DISTINCT ?investor) AS ?avg_holdings_per_investor)
  (COUNT(?rebalancingAction) / COUNT(DISTINCT ?investor) AS ?avg_rebalancing_actions_per_investor)
  (AVG(?riskScore) AS ?avg_risk_score)
WHERE {
  ?investor a wm:Investor ;
            wm:hasCategory ?category .

  OPTIONAL {
    ?holding a wm:PortfolioHolding ;
             wm:heldByInvestor ?investor .
  }

  OPTIONAL {
    ?rebalancingAction a wm:RebalancingAction ;
                       wm:rebalancingActionOfInvestor ?investor .
  }

  OPTIONAL {
    ?portfolioHealth a wm:PortfolioHealth ;
                     wm:healthOfInvestor ?investor ;
                     wm:riskScore ?riskScore .
  }
}
GROUP BY ?category
ORDER BY ?category

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?segment (COUNT(DISTINCT ?investor) AS ?distinct_investor_count)
WHERE {
  ?investor a wm:Investor ;
            wm:hasSegment ?segment ;
            wm:hasPortfolioHealth ?health ;
            wm:hasHolding ?holding ;
            wm:hasCashFlow ?cashFlow .

  ?health wm:riskScore ?riskScore .
  FILTER (?riskScore > 25)

  ?holding wm:investmentName "Gold" .

  ?cashFlow wm:type "Deposit" .
}
GROUP BY ?segment

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?segment (COUNT(DISTINCT ?investor) AS ?distinct_investor_count)
WHERE {
  ?investor wm:hasSegment ?segment ;
            wm:hasRiskTolerance/wm:riskScore ?riskScore .
  FILTER (?riskScore > 25)

  ?holding wm:heldByInvestor ?investor ;
           wm:hasInvestmentType ?invType .
  ?invType rdfs:label "ETF" .

  ?rebalancingAction wm:rebalancingActionOfInvestor ?investor ;
                     wm:action "Buy" .
}
GROUP BY ?segment

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?segment (COUNT(DISTINCT ?investor) AS ?distinct_investor_count)
WHERE {
  ?investor a wm:Investor ;
            wm:hasHolding ?holding ;
            wm:hasScenarioRebalancing ?scenario ;
            wm:segment ?segment .

  ?holding a wm:PortfolioHolding ;
           wm:investmentType "Mutual Fund" .

  ?scenario a wm:ScenarioRebalancing ;
            wm:scenario "Bull Market" .

  ?health a wm:PortfolioHealth ;
          wm:healthOfInvestor ?investor ;
          wm:riskScore ?riskScore .

  FILTER (?riskScore > 25)
}
GROUP BY ?segment

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?segment (COUNT(DISTINCT ?investor) AS ?count)
WHERE {
  ?investor a wm:Investor ;
            wm:hasPortfolioHealth ?health ;
            wm:hasHolding ?holding ;
            wm:hasInvestmentGoal ?goal ;
            wm:hasSegment ?segment .

  ?health wm:riskScore ?riskScore .
  FILTER (?riskScore > 25)

  ?holding wm:hasSector ?sector .
  ?sector rdfs:label "Real Estate" .

  ?goal wm:hasInvestmentGoalType ?goalType .
  ?goalType rdfs:label "Growth" .
}
GROUP BY ?segment

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?category
  (ROUND(AVG(?total_sector_investment_per_investor), 2) AS ?avg_total_sector_investment)
  (ROUND(AVG(?avg_return_per_investor), 2) AS ?avg_holding_return)
  (ROUND(AVG(?risk_score), 2) AS ?avg_risk_score)
WHERE {
  {
    SELECT 
      ?category
      ?investorId
      (SUM(xsd:decimal(?allocationPct) * xsd:decimal(?totalInvestment) / 100) AS ?total_sector_investment_per_investor)
    WHERE {
      ?sectorAlloc a wm:SectorAllocation ;
                   wm:allocationOfInvestor ?investor ;
                   wm:investorId ?investorId ;
                   wm:allocationPct ?allocationPct ;
                   wm:totalInvestment ?totalInvestment .
      ?investor a wm:Investor ;
                wm:hasCategory ?catInst ;
                wm:investorId ?investorId .
      ?catInst rdfs:label ?category .
    }
    GROUP BY ?category ?investorId
  }
  {
    SELECT 
      ?category
      ?investorId
      (AVG(xsd:decimal(?returnsPct)) AS ?avg_return_per_investor)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:investorId ?investorId ;
               wm:returnsPct ?returnsPct ;
               wm:cost ?cost ;
               wm:currentValue ?currentValue ;
               wm:hasCategory ?catInst .
      FILTER (?cost != "" && ?currentValue != "")
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      ?catInst rdfs:label ?category .
    }
    GROUP BY ?category ?investorId
  }
  {
    SELECT 
      ?category
      ?investorId
      (xsd:decimal(?riskScore) AS ?risk_score)
    WHERE {
      ?health a wm:PortfolioHealth ;
              wm:healthOfInvestor ?investor ;
              wm:investorId ?investorId ;
              wm:riskScore ?riskScore .
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasCategory ?catInst .
      ?catInst rdfs:label ?category .
    }
  }
}
GROUP BY ?category
ORDER BY ?category

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?segment (COUNT(DISTINCT ?investor) AS ?distinct_investor_count)
WHERE {
  ?investor a wm:Investor ;
            wm:hasHolding ?holding ;
            wm:hasCashFlow ?cashFlow ;
            wm:hasPortfolioHealth ?health ;
            wm:hasSegment ?segment .

  ?holding a wm:PortfolioHolding ;
           wm:hasInvestmentType ?investmentType .

  ?investmentType rdfs:label "Corporate Bond" .

  ?cashFlow a wm:CashFlow ;
            wm:hasCashFlowType ?cashFlowType .

  ?cashFlowType rdfs:label "Withdrawal" .

  ?health a wm:PortfolioHealth ;
          wm:riskScore ?riskScore .

  FILTER(xsd:integer(?riskScore) > 25)
}
GROUP BY ?segment

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?category (COUNT(DISTINCT ?investor) AS ?distinct_investor_count)
WHERE {
  ?investor a wm:Investor ;
            wm:hasHolding ?holding ;
            wm:hasCashFlow ?cashFlow ;
            wm:hasPortfolioHealth ?health .

  ?holding a wm:PortfolioHolding ;
           wm:hasInvestmentType ?invType ;
           wm:hasCategory ?category .

  ?invType rdfs:label "Equity" .

  ?cashFlow a wm:CashFlow ;
            wm:hasCashFlowType ?cfType .

  ?cfType rdfs:label "SIP" .

  ?health a wm:PortfolioHealth ;
