PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?netCashFlow)) AS ?avg_net_cash_flow)
  (ROUND(AVG(?avgSignedAmount)) AS ?avg_signed_cash_flow_amount)
  (ROUND(AVG(?cashFlowCount)) AS ?avg_cash_flow_count)
  (COUNT(DISTINCT ?investorId) AS ?n_investors)
WHERE {
  {
    SELECT 
      ?investorId
      (SUM(IF(?isInflow, -?amountValue, ?amountValue)) AS ?netCashFlow)
      (AVG(IF(?isInflow, -?amountValue, ?amountValue)) AS ?avgSignedAmount)
      (COUNT(?cashFlowId) AS ?cashFlowCount)
    WHERE {
      ?cashFlow wm:cashFlowOfInvestor ?investor ;
                wm:cashFlowId ?cashFlowId ;
                wm:amount ?amountStr ;
                wm:type ?type .
      BIND(xsd:decimal(REPLACE(?amountStr, ",", "")) AS ?amountValue)
      VALUES (?type ?isInflow) {
        ("SIP" true)
        ("Lump Sum" true)
        ("Deposit" true)
        ("Redemption" false)
        ("Withdrawal" false)
      }
      ?investor wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }

  ?investorProfile wm:investorId ?investorId ;
                   wm:hasRiskTolerance ?riskToleranceObj .
  ?riskToleranceObj rdfs:label ?riskTolerance .
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?avg_rebalance_amount)) AS ?avg_rebalance_amount)
  (ROUND(AVG(?avg_shift)) AS ?avg_shift)
  (ROUND(AVG(?rebalance_count)) AS ?avg_rebalance_count)
  (COUNT(?investor) AS ?n_investors)
WHERE {
  SELECT 
    ?investor
    ?riskTolerance
    (COALESCE(AVG(?amount), 0) AS ?avg_rebalance_amount)
    (COALESCE(AVG(?shift), 0) AS ?avg_shift)
    (COUNT(?action) AS ?rebalance_count)
  WHERE {
    ?investor a wm:Investor ;
              wm:hasRiskTolerance ?rt .
    ?rt rdfs:label ?riskTolerance .

    OPTIONAL {
      ?action a wm:RebalancingAction ;
              wm:rebalancingActionOfInvestor ?investor ;
              wm:amount ?amtStr ;
              wm:currentAllocationPct ?currStr ;
              wm:targetAllocationPct ?tgtStr .

      BIND(xsd:decimal(?amtStr) AS ?amount)
      BIND(xsd:decimal(?currStr) AS ?current)
      BIND(xsd:decimal(?tgtStr) AS ?target)
      BIND((?target - ?current) AS ?shift)
    }
  }
  GROUP BY ?investor ?riskTolerance
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT 
  ?riskTolerance
  (AVG(?shift) AS ?avgShift)
  (AVG(?count) AS ?avgScenarioCount)
WHERE {
  {
    SELECT 
      ?investor 
      ?riskTolerance 
      (COALESCE(SUM(?newMinusCurrent), 0) AS ?shift)
      (COUNT(?scenarioRebalancing) AS ?count)
    WHERE {
      ?investor wm:hasRiskTolerance ?rt .
      ?rt rdfs:label ?riskTolerance .

      OPTIONAL {
        ?scenarioRebalancing wm:scenarioRebalancingOfInvestor ?investor ;
                             wm:newAllocationPct ?new ;
                             wm:currentAllocationPct ?current .
        BIND((xsd:decimal(?new) - xsd:decimal(?current)) AS ?newMinusCurrent)
      }
    }
    GROUP BY ?investor ?riskTolerance
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?riskScore)) AS ?avg_risk_score)
  (ROUND(AVG(?liquidityScore)) AS ?avg_liquidity_score)
  (ROUND(AVG(?diversificationScore)) AS ?avg_diversification_score)
  (ROUND(AVG(?goalMatchPct)) AS ?avg_goal_match_pct)
  (COUNT(DISTINCT ?investor) AS ?n_investors)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?rt .
  ?rt rdfs:label ?riskTolerance .

  OPTIONAL {
    ?health a wm:PortfolioHealth ;
            wm:healthOfInvestor ?investor ;
            wm:riskScore ?riskScore ;
            wm:liquidityScore ?liquidityScore ;
            wm:diversificationScore ?diversificationScore ;
            wm:goalMatchPct ?goalMatchPct .
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?progressPct), 2) AS ?avg_progress_pct)
  (ROUND(AVG(?shortfall), 2) AS ?avg_shortfall)
  (ROUND(AVG(?avgAnnualReturnPct), 2) AS ?avg_annual_return_pct)
  (ROUND(AVG(?stdDevAnnualReturnPct), 2) AS ?avg_volatility_pct)
  (COUNT(DISTINCT ?investorId) AS ?n_investors)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?rt ;
            wm:investorId ?investorId .

  ?rt rdfs:label ?riskTolerance .

  OPTIONAL {
    ?goal a wm:InvestmentGoal ;
          wm:belongsToInvestor ?investor ;
          wm:progressPct ?progressPct ;
          wm:shortfall ?shortfall ;
          wm:avgAnnualReturnPct ?avgAnnualReturnPct ;
          wm:stdDevAnnualReturnPct ?stdDevAnnualReturnPct .
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?timeHorizon
       (AVG(?rebalanceAmount) AS ?avgRebalanceAmount)
       (AVG(?shift) AS ?avgRebalanceShift)
       (AVG(?rebalanceCount) AS ?avgRebalanceCount)
WHERE {
  ?investor wm:hasTimeHorizon ?th .
  ?th rdfs:label ?timeHorizon .

  OPTIONAL {
    ?ra wm:rebalancingActionOfInvestor ?investor ;
        wm:amount ?rebalanceAmount ;
        wm:currentAllocationPct ?currentAlloc ;
        wm:targetAllocationPct ?targetAlloc .
    BIND(xsd:decimal(?targetAlloc - ?currentAlloc) AS ?shift)
  }

  BIND(IF(BOUND(?ra), COUNT(?ra), 0) AS ?rebalanceCount)
}
GROUP BY ?timeHorizon
ORDER BY ?timeHorizon

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?timeHorizonLabel AS ?group_value
  (ROUND(AVG(?netCashFlow)) AS ?avg_net_cash_flow)
  (ROUND(AVG(?avgSignedAmount)) AS ?avg_signed_cash_flow_amount)
  (ROUND(AVG(?cashFlowCount)) AS ?avg_cash_flow_count)
  (COUNT(DISTINCT ?investorId) AS ?n_investors)
WHERE {
  ?investor a wm:Investor ;
            wm:hasTimeHorizon ?timeHorizon ;
            wm:investorId ?investorId .

  ?timeHorizon rdfs:label ?timeHorizonLabel .

  {
    SELECT ?investorId
           (SUM(IF(?isInflow, -?amount, ?amount)) AS ?netCashFlow)
           (AVG(?signedAmount) AS ?avgSignedAmount)
           (COUNT(?cashFlowId) AS ?cashFlowCount)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:cashFlowId ?cashFlowId ;
                wm:amount ?amountStr ;
                wm:type ?type .

      BIND(xsd:decimal(?amountStr) AS ?amount)

      VALUES (?type ?isInflow) {
        ("SIP" true)
        ("Lump Sum" true)
        ("Deposit" true)
        ("Redemption" false)
        ("Withdrawal" false)
      }

      BIND(IF(?isInflow, -?amount, ?amount) AS ?signedAmount)
      BIND(MD5(CONCAT(?investorId, ?cashFlowId)) AS ?uniqueId)
    }
    GROUP BY ?investorId
  }
}
GROUP BY ?timeHorizonLabel
ORDER BY ?timeHorizonLabel

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?timeHorizon
       (COALESCE(AVG(?shift), 0) AS ?avgScenarioShift)
       (COALESCE(AVG(?count), 0) AS ?avgScenarioCount)
WHERE {
  ?investor a wm:Investor ;
            wm:hasTimeHorizon ?th ;
            wm:investorId ?investorId .

  ?th rdfs:label ?timeHorizon .

  OPTIONAL {
    ?scenarioRebalancing wm:scenarioRebalancingOfInvestor ?investor ;
                         wm:newAllocationPct ?newAlloc ;
                         wm:currentAllocationPct ?currAlloc .

    BIND((xsd:decimal(?newAlloc) - xsd:decimal(?currAlloc)) AS ?shift)
  }

  {
    SELECT ?investor (COUNT(?scenarioRebalancing) AS ?count)
    WHERE {
      ?investor a wm:Investor .
      OPTIONAL {
        ?scenarioRebalancing wm:scenarioRebalancingOfInvestor ?investor .
      }
    }
    GROUP BY ?investor
  }
}
GROUP BY ?timeHorizon
ORDER BY ?timeHorizon

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?timeHorizonLabel AS ?time_horizon,
  ROUND(AVG(?riskScore), 2) AS ?avg_risk_score,
  ROUND(AVG(?liquidityScore), 2) AS ?avg_liquidity_score,
  ROUND(AVG(?diversificationScore), 2) AS ?avg_diversification_score,
  ROUND(AVG(?goalMatchPct), 2) AS ?avg_goal_match_pct,
  COUNT(DISTINCT ?investorId) AS ?n_investors
WHERE {
  ?investor a wm:Investor ;
            wm:hasTimeHorizon ?timeHorizon ;
            wm:investorId ?investorId .

  ?timeHorizon rdfs:label ?timeHorizonLabel .

  OPTIONAL {
    ?health a wm:PortfolioHealth ;
            wm:healthOfInvestor ?investor ;
            wm:riskScore ?riskScore ;
            wm:liquidityScore ?liquidityScore ;
            wm:diversificationScore ?diversificationScore ;
            wm:goalMatchPct ?goalMatchPct .
  }
}
GROUP BY ?timeHorizonLabel
ORDER BY ?timeHorizonLabel

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?timeHorizonLabel AS ?group_value
  (ROUND(AVG(?progressPct), 2) AS ?avg_progress_pct)
  (ROUND(AVG(?shortfall), 2) AS ?avg_shortfall)
  (ROUND(AVG(?avgAnnualReturnPct), 2) AS ?avg_annual_return_pct)
  (ROUND(AVG(?stdDevAnnualReturnPct), 2) AS ?avg_volatility_pct)
  (COUNT(DISTINCT ?investorId) AS ?n_investors)
WHERE {
  ?investor a wm:Investor ;
            wm:hasInvestmentGoal ?goal ;
            wm:hasTimeHorizon ?timeHorizon ;
            wm:investorId ?investorId .

  ?goal a wm:InvestmentGoal ;
        wm:progressPct ?progressPct ;
        wm:shortfall ?shortfall ;
        wm:avgAnnualReturnPct ?avgAnnualReturnPct ;
        wm:stdDevAnnualReturnPct ?stdDevAnnualReturnPct .

  ?timeHorizon rdfs:label ?timeHorizonLabel .
}
GROUP BY ?timeHorizonLabel
ORDER BY ?timeHorizonLabel

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?netCashFlow)
WHERE {
  ?cashFlow a wm:CashFlow ;
            wm:investorId ?investorId ;
            wm:amount ?amount ;
            wm:type ?type .
  FILTER(?type IN ("SIP", "Lump Sum", "Deposit", "Redemption", "Withdrawal"))
}
GROUP BY ?investorId
ORDER BY DESC(?netCashFlow)
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId (SUM(?amount) AS ?totalRebalanceAmount)
WHERE {
  ?rebalancingAction wm:rebalancingActionOfInvestor ?investor ;
                     wm:amount ?amount .
  ?investor wm:investorId ?investorId .
}
GROUP BY ?investorId
ORDER BY DESC(?totalRebalanceAmount)
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId (COUNT(?scenarioRebalanceId) AS ?rebalancingActionCount)
WHERE {
  ?investor wm:hasScenarioRebalancing ?scenarioRebalancing .
  ?scenarioRebalancing wm:scenarioRebalanceId ?scenarioRebalanceId ;
                      wm:investorId ?investorId .
}
GROUP BY ?investorId
ORDER BY DESC(?rebalancingActionCount) ?investorId
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId (AVG(?progressPct) AS ?avgProgressPct)
WHERE {
  ?goal a wm:InvestmentGoal ;
        wm:belongsToInvestor ?investor ;
        wm:progressPct ?progressPct .
  ?investor wm:investorId ?investorId .
}
GROUP BY ?investorId
ORDER BY DESC(?avgProgressPct)
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId (SUM(?amount) AS ?totalRebalanceAmount)
WHERE {
  ?rebalancingAction wm:rebalancingActionOfInvestor ?investor ;
                     wm:amount ?amount .
  ?investor wm:investorId ?investorId .
}
GROUP BY ?investorId
ORDER BY DESC(?totalRebalanceAmount)
LIMIT 20

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?netCashFlow)
WHERE {
  ?cashFlow a wm:CashFlow ;
            wm:investorId ?investorId ;
            wm:amount ?amount ;
            wm:type ?type .
  FILTER(?type IN ("SIP", "Lump Sum", "Deposit", "Redemption", "Withdrawal"))
}
GROUP BY ?investorId
ORDER BY DESC(?netCashFlow)
LIMIT 20

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?netCashFlow)) AS ?avg_net_cash_flow)
  (ROUND(AVG(?signedCashFlowAmount)) AS ?avg_signed_cash_flow_amount)
  (ROUND(AVG(?rebalanceAmount)) AS ?avg_rebalance_amount)
  (COUNT(DISTINCT ?investor) AS ?n_investors)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?rt .
  ?rt rdfs:label ?riskTolerance .

  OPTIONAL {
    ?cashFlow wm:cashFlowOfInvestor ?investor ;
              wm:amount ?cfAmountStr ;
              wm:hasCashFlowType ?cfType .
    BIND(xsd:decimal(?cfAmountStr) AS ?cfAmount)
    ?cfType rdfs:label ?cfTypeLabel .
    BIND(IF(?cfTypeLabel IN ("SIP", "Lump Sum", "Deposit"), -?cfAmount, ?cfAmount) AS ?signedCashFlowAmount)
  }

  OPTIONAL {
    ?rebalancingAction wm:rebalancingActionOfInvestor ?investor ;
                       wm:amount ?raAmountStr .
    BIND(xsd:decimal(?raAmountStr) AS ?rebalanceAmount)
  }

  BIND(
    SUM(
      IF(?cfTypeLabel IN ("SIP", "Lump Sum", "Deposit"), -?cfAmount, ?cfAmount)
    ) AS ?netCashFlow
  )
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?netCashFlow)) AS ?avg_net_cash_flow)
  (ROUND(AVG(?signedCashFlowAmount)) AS ?avg_signed_cash_flow_amount)
  (ROUND(AVG(?scenarioShift)) AS ?avg_scenario_shift)
  (COUNT(DISTINCT ?investor) AS ?n_investors)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?rt .
  ?rt rdfs:label ?riskTolerance .

  OPTIONAL {
    ?cashFlow wm:cashFlowOfInvestor ?investor ;
              wm:amount ?amountStr ;
              wm:hasCashFlowType ?cfType .
    ?cfType rdfs:label ?cfTypeLabel .
    BIND(xsd:decimal(?amountStr) AS ?amount)
    BIND(IF(?cfTypeLabel IN ("SIP", "Lump Sum", "Deposit"), -?amount, ?amount) AS ?signedCashFlowAmount)
  }

  OPTIONAL {
    ?scenarioRebalancing wm:scenarioRebalancingOfInvestor ?investor ;
                         wm:currentAllocationPct ?currentAllocStr ;
                         wm:newAllocationPct ?newAllocStr .
    BIND(xsd:decimal(?currentAllocStr) AS ?currentAlloc)
    BIND(xsd:decimal(?newAllocStr) AS ?newAlloc)
    BIND((?newAlloc - ?currentAlloc) AS ?scenarioShift)
  }

  BIND(
    SUM(
      IF(?cfTypeLabel IN ("SIP", "Lump Sum", "Deposit"), -?amount, ?amount)
    ) AS ?netCashFlow
  )
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?netCashFlow)) AS ?avg_net_cash_flow)
  (ROUND(AVG(?avgSignedCashFlowAmount)) AS ?avg_signed_cash_flow_amount)
  (ROUND(AVG(?riskScore)) AS ?avg_risk_score)
  (COUNT(DISTINCT ?investor) AS ?n_investors)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?rt .
  ?rt rdfs:label ?riskTolerance .

  OPTIONAL {
    ?cashFlow wm:cashFlowOfInvestor ?investor ;
              wm:amount ?amountStr ;
              wm:hasCashFlowType ?cfType .
    ?cfType rdfs:label ?cfTypeLabel .
    BIND(xsd:decimal(?amountStr) AS ?amount)
    BIND(IF(?cfTypeLabel IN ("SIP", "Lump Sum", "Deposit"), -?amount, ?amount) AS ?signedAmount)
  }

  OPTIONAL {
    ?health wm:healthOfInvestor ?investor ;
            wm:riskScore ?riskScoreStr .
    BIND(xsd:decimal(?riskScoreStr) AS ?riskScore)
  }

  BIND(
    IF(BOUND(?signedAmount), ?signedAmount, 0)
    AS ?signedCashFlowAmount)
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?totalCurrentValue)) AS ?avg_total_holding_value)
  (ROUND(AVG(?avgReturnsPct), 2) AS ?avg_holding_return_pct)
  (ROUND(AVG(?avgRebalanceAmount), 2) AS ?avg_rebalance_amount)
WHERE {
  {
    SELECT 
      ?investor 
      ?riskTolerance
      (SUM(xsd:decimal(?currentValue)) AS ?totalCurrentValue)
      (AVG(IF(?cost != "0" && ?currentValue != "0", 
              ((xsd:decimal(?currentValue) - xsd:decimal(?cost)) / xsd:decimal(?cost)) * 100, 
              0)) AS ?avgReturnsPct)
    WHERE {
      ?investor a wm:Investor ;
                wm:hasRiskTolerance ?rt .
      ?rt rdfs:label ?riskTolerance .

      ?holding wm:heldByInvestor ?investor ;
               wm:currentValue ?currentValue ;
               wm:cost ?cost .
      FILTER (?currentValue >= "0" && ?cost > "0")
    }
    GROUP BY ?investor ?riskTolerance
  }

  OPTIONAL {
    SELECT 
      ?investor 
      (AVG(xsd:decimal(?amount)) AS ?avgRebalanceAmount)
    WHERE {
      ?ra wm:rebalancingActionOfInvestor ?investor ;
          wm:amount ?amount .
    }
    GROUP BY ?investor
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?netCashFlow)) AS ?avg_net_cash_flow)
  (ROUND(AVG(?avgSignedCashFlowAmount)) AS ?avg_signed_cash_flow_amount)
  (ROUND(AVG(?avgGoalProgress)) AS ?avg_goal_progress)
  (COUNT(DISTINCT ?investorId) AS ?n_investors)
WHERE {
  {
    SELECT 
      ?investorId
      (SUM(IF(?cashFlowType IN ("SIP", "Lump Sum", "Deposit"), -xsd:decimal(?amount), xsd:decimal(?amount))) AS ?netCashFlow)
    WHERE {
      ?cashFlow wm:cashFlowOfInvestor ?investor .
      ?investor wm:investorId ?investorId .
      ?cashFlow wm:amount ?amount .
      ?cashFlow wm:type ?cashFlowType .
    }
    GROUP BY ?investorId
  }

  {
    SELECT 
      ?investorId
      (AVG(xsd:decimal(?amount)) AS ?avgSignedCashFlowAmount)
    WHERE {
      ?cashFlow wm:cashFlowOfInvestor ?investor .
      ?investor wm:investorId ?investorId .
      ?cashFlow wm:amount ?amount .
      ?cashFlow wm:type ?cashFlowType .
      BIND(
        IF(?cashFlowType IN ("SIP", "Lump Sum", "Deposit"), -xsd:decimal(?amount), xsd:decimal(?amount))
        AS ?signedAmount
      )
    }
    GROUP BY ?investorId
  }

  {
    SELECT 
      ?investorId
      (AVG(xsd:decimal(?progressPct)) AS ?avgGoalProgress)
    WHERE {
      ?goal wm:belongsToInvestor ?investor .
      ?investor wm:investorId ?investorId .
      ?goal wm:progressPct ?progressPct .
    }
    GROUP BY ?investorId
  }

  ?investor wm:investorId ?investorId ;
             wm:riskTolerance ?riskTolerance .

}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?totalHoldingValue), 2) AS ?avg_total_holding_value)
  (ROUND(AVG(?avgHoldingReturn), 2) AS ?avg_holding_return)
  (ROUND(AVG(?totalSectorInvestment), 2) AS ?avg_total_sector_investment)
  (COUNT(DISTINCT ?investor) AS ?n_investors)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?rt .
  ?rt rdfs:label ?riskTolerance .

  # Subquery for total holding value per investor
  {
    SELECT ?investor (SUM(xsd:decimal(?cv)) AS ?totalHoldingValue)
    WHERE {
      ?holding wm:heldByInvestor ?investor ;
               wm:currentValue ?cv ;
               wm:cost ?cost .
      FILTER (xsd:decimal(?cv) >= 0 && xsd:decimal(?cost) > 0)
    }
    GROUP BY ?investor
  }

  # Subquery for average holding return per investor (only valid holdings)
  {
    SELECT ?investor (AVG((xsd:decimal(?currentValue) - xsd:decimal(?cost)) / xsd:decimal(?cost) * 100) AS ?avgHoldingReturn)
    WHERE {
      ?holding wm:heldByInvestor ?investor ;
               wm:currentValue ?currentValue ;
               wm:cost ?cost .
      FILTER (xsd:decimal(?cost) > 0 && xsd:decimal(?currentValue) >= 0)
    }
    GROUP BY ?investor
  }

  # Subquery for total sector investment per investor
  {
    SELECT ?investor (SUM(xsd:decimal(?totalInvestment)) AS ?totalSectorInvestment)
    WHERE {
      ?sa wm:allocationOfInvestor ?investor ;
          wm:totalInvestment ?totalInvestment .
    }
    GROUP BY ?investor
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?totalCurrentValue)) AS ?avg_total_holding_value)
  (ROUND(AVG(?avgReturnPct), 2) AS ?avg_holding_return_pct)
  (ROUND(AVG(?riskScore), 2) AS ?avg_risk_score)
  (COUNT(DISTINCT ?investor) AS ?n_investors)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?rt .
  ?rt rdfs:label ?riskTolerance .

  OPTIONAL {
    ?holding wm:heldByInvestor ?investor ;
             wm:currentValue ?cv ;
             wm:cost ?c .
    FILTER (?c > 0 && ?cv >= 0)
  }

  BIND(COALESCE(xsd:decimal(?cv), 0) AS ?currentValueNum)
  BIND(COALESCE(xsd:decimal(?c), 0) AS ?costNum)

  BIND(IF(?costNum > 0, ((?currentValueNum - ?costNum) / ?costNum) * 100, 0) AS ?returnPct)

  OPTIONAL {
    ?health wm:healthOfInvestor ?investor ;
            wm:riskScore ?rs .
    BIND(xsd:decimal(?rs) AS ?riskScore)
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?totalCurrentValue), 2) AS ?avg_total_holding_value)
  (ROUND(AVG(?avgReturnPct), 2) AS ?avg_holding_return_pct)
  (ROUND(AVG(?avgProgressPct), 2) AS ?avg_goal_progress_pct)
WHERE {
  {
    SELECT 
      ?investor 
      (SUM(xsd:decimal(?currentValue)) AS ?totalCurrentValue)
      (AVG(
        IF(
          xsd:decimal(?cost) > 0 && xsd:decimal(?currentValue) >= 0,
          ((xsd:decimal(?currentValue) - xsd:decimal(?cost)) / xsd:decimal(?cost)) * 100,
          0
        )
      ) AS ?avgReturnPct)
    WHERE {
      ?holding wm:heldByInvestor ?investor ;
               wm:cost ?cost ;
               wm:currentValue ?currentValue .
      FILTER (xsd:decimal(?cost) > 0 && xsd:decimal(?currentValue) >= 0)
    }
    GROUP BY ?investor
  }

  {
    SELECT 
      ?investor 
      (AVG(xsd:decimal(?progressPct)) AS ?avgProgressPct)
    WHERE {
      ?goal wm:belongsToInvestor ?investor ;
            wm:progressPct ?progressPct .
    }
    GROUP BY ?investor
  }

  ?investor wm:hasRiskTolerance ?rt .
  ?rt rdfs:label ?riskTolerance .
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT 
  ?riskTolerance
  (AVG(?rebalanceAmount) AS ?avgRebalanceAmount)
  (AVG(?shift) AS ?avgRebalanceShift)
  (AVG(?totalSectorInvestment) AS ?avgTotalSectorInvestment)
WHERE {
  ?investor wm:hasRiskTolerance ?rt .
  ?rt rdfs:label ?riskTolerance .

  OPTIONAL {
    ?rebalancing wm:rebalancingActionOfInvestor ?investor ;
                 wm:amount ?rebalanceAmountStr ;
                 wm:currentAllocationPct ?currentAllocationStr ;
                 wm:targetAllocationPct ?targetAllocationStr .
    BIND(xsd:decimal(?rebalanceAmountStr) AS ?rebalanceAmount)
    BIND(xsd:decimal(?currentAllocationStr) AS ?currentAllocation)
    BIND(xsd:decimal(?targetAllocationStr) AS ?targetAllocation)
    BIND((?targetAllocation - ?currentAllocation) AS ?shift)
  }

  OPTIONAL {
    ?allocation wm:allocationOfInvestor ?investor ;
                wm:totalInvestment ?totalInvestmentStr .
    BIND(xsd:decimal(?totalInvestmentStr) AS ?totalSectorInvestment)
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?totalCurrentValue)) AS ?avg_total_holding_value)
  (ROUND(AVG(?avgReturnsPct), 2) AS ?avg_holding_return)
  (ROUND(AVG(?scenarioShift), 2) AS ?avg_scenario_shift)
  (COUNT(DISTINCT ?investor) AS ?n_investors)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?rt .
  ?rt rdfs:label ?riskTolerance .

  # Total current value per investor
  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(?cv)) AS ?totalCurrentValue)
    WHERE {
      ?holding wm:heldByInvestor ?investor ;
               wm:currentValue ?cv ;
               wm:cost ?cost .
      FILTER (?cv != "" && ?cost != "")
    }
    GROUP BY ?investor
  }

  # Average return % per investor (only holdings with cost and current value)
  OPTIONAL {
    SELECT ?investor (AVG(xsd:decimal(?returnsPct)) AS ?avgReturnsPct)
    WHERE {
      ?holding wm:heldByInvestor ?investor ;
               wm:returnsPct ?returnsPct ;
               wm:currentValue ?cv ;
               wm:cost ?cost .
      FILTER (?cv != "" && ?cost != "" && ?returnsPct != "")
    }
    GROUP BY ?investor
  }

  # Scenario shift: new minus current allocation %
  OPTIONAL {
    SELECT ?investor (AVG(xsd:decimal(?newAlloc) - xsd:decimal(?currAlloc)) AS ?scenarioShift)
    WHERE {
      ?scenario wm:scenarioRebalancingOfInvestor ?investor ;
                wm:newAllocationPct ?newAlloc ;
                wm:currentAllocationPct ?currAlloc .
      FILTER (?newAlloc != "" && ?currAlloc != "")
    }
    GROUP BY ?investor
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?rebalanceAmount)) AS ?avg_rebalance_amount)
  (ROUND(AVG(?rebalanceShift)) AS ?avg_rebalance_shift)
  (ROUND(AVG(?scenarioShift)) AS ?avg_scenario_shift)
  (COUNT(DISTINCT ?investor) AS ?n_investors)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?rt .
  ?rt rdfs:label ?riskTolerance .

  OPTIONAL {
    ?ra wm:rebalancingActionOfInvestor ?investor ;
        wm:amount ?rebalanceAmount ;
        wm:currentAllocationPct ?currentAlloc ;
        wm:targetAllocationPct ?targetAlloc .
    BIND(xsd:decimal(?targetAlloc) - xsd:decimal(?currentAlloc) AS ?rebalanceShift)
  }

  OPTIONAL {
    ?sr wm:scenarioRebalancingOfInvestor ?investor ;
        wm:currentAllocationPct ?scCurrentAlloc ;
        wm:newAllocationPct ?scNewAlloc .
    BIND(xsd:decimal(?scNewAlloc) - xsd:decimal(?scCurrentAlloc) AS ?scenarioShift)
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?totalInvestment)) AS ?avg_total_sector_investment)
  (ROUND(AVG(?allocationPct), 2) AS ?avg_allocation_pct)
  (ROUND(AVG(?scenarioShift), 2) AS ?avg_scenario_shift)
WHERE {
  ?investor wm:hasRiskTolerance ?rt .
  ?rt rdfs:label ?riskTolerance .

  OPTIONAL {
    ?sectorAlloc wm:allocationOfInvestor ?investor ;
                 wm:totalInvestment ?totalInvestment ;
                 wm:allocationPct ?allocationPct .
  }

  OPTIONAL {
    ?scenarioRebalancing wm:scenarioRebalancingOfInvestor ?investor ;
                         wm:newAllocationPct ?newAllocationPct ;
                         wm:currentAllocationPct ?currentAllocationPct .
    BIND((xsd:decimal(?newAllocationPct) - xsd:decimal(?currentAllocationPct)) AS ?scenarioShift)
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?rebalanceAmount)) AS ?avg_rebalance_amount)
  (ROUND(AVG(?shift)) AS ?avg_rebalance_shift)
  (ROUND(AVG(?goalProgress)) AS ?avg_goal_progress)
  (COUNT(DISTINCT ?investor) AS ?n_investors)
WHERE {
  ?investor wm:hasRiskTolerance ?rt .
  ?rt rdfs:label ?riskTolerance .

  OPTIONAL {
    ?ra wm:rebalancingActionOfInvestor ?investor ;
        wm:amount ?rebalanceAmount ;
        wm:currentAllocationPct ?currentPct ;
        wm:targetAllocationPct ?targetPct .
    BIND(xsd:decimal(?targetPct) - xsd:decimal(?currentPct) AS ?shift)
  }

  OPTIONAL {
    ?goal wm:belongsToInvestor ?investor ;
          wm:progressPct ?goalProgress .
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?avgRebalanceAmount), 2) AS ?avg_rebalance_amount)
  (ROUND(AVG(?avgRebalanceShift), 2) AS ?avg_rebalance_shift)
  (ROUND(AVG(?riskScore), 2) AS ?avg_risk_score)
  (COUNT(DISTINCT ?investor) AS ?n_investors)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?rt .
  ?rt rdfs:label ?riskTolerance .

  OPTIONAL {
    ?ra wm:rebalancingActionOfInvestor ?investor ;
        wm:amount ?amount ;
        wm:currentAllocationPct ?currentPct ;
        wm:targetAllocationPct ?targetPct .
    BIND(xsd:decimal(?amount) AS ?rebalanceAmount)
    BIND(xsd:decimal(?targetPct) - xsd:decimal(?currentPct) AS ?rebalanceShift)
  }

  OPTIONAL {
    ?ph wm:healthOfInvestor ?investor ;
        wm:riskScore ?riskScoreRaw .
    BIND(xsd:decimal(?riskScoreRaw) AS ?riskScore)
  }

  {
    SELECT ?investor
           (AVG(?rebalanceAmount) AS ?avgRebalanceAmount)
           (AVG(?rebalanceShift) AS ?avgRebalanceShift)
    WHERE {
      ?ra wm:rebalancingActionOfInvestor ?investor ;
          wm:amount ?amount ;
          wm:currentAllocationPct ?currentPct ;
          wm:targetAllocationPct ?targetPct .
      BIND(xsd:decimal(?amount) AS ?rebalanceAmount)
      BIND(xsd:decimal(?targetPct) - xsd:decimal(?currentPct) AS ?rebalanceShift)
    }
    GROUP BY ?investor
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?totalInvestment)) AS ?avg_total_sector_investment)
  (ROUND(AVG(?allocationPct), 2) AS ?avg_allocation_percentage)
  (ROUND(AVG(?progressPct), 2) AS ?avg_goal_progress)
WHERE {
  ?investor wm:hasRiskTolerance ?rt .
  ?rt rdfs:label ?riskTolerance .

  OPTIONAL {
    ?sectorAlloc wm:allocationOfInvestor ?investor ;
                 wm:totalInvestment ?totalInvestment ;
                 wm:allocationPct ?allocationPct .
  }

  OPTIONAL {
    ?goal wm:belongsToInvestor ?investor ;
          wm:progressPct ?progressPct .
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?totalInvestment)) AS ?avg_total_sector_investment)
  (ROUND(AVG(?allocationPct), 2) AS ?avg_allocation_pct)
  (ROUND(AVG(?riskScore), 2) AS ?avg_risk_score)
  (COUNT(DISTINCT ?investorId) AS ?n_investors)
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:hasRiskTolerance ?rt .
  ?rt rdfs:label ?riskTolerance .

  OPTIONAL {
    ?sa a wm:SectorAllocation ;
        wm:allocationOfInvestor ?investor ;
        wm:totalInvestment ?totalInvestment ;
        wm:allocationPct ?allocationPct .
  }

  OPTIONAL {
    ?ph a wm:PortfolioHealth ;
        wm:healthOfInvestor ?investor ;
        wm:riskScore ?riskScore .
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?scenarioShift)) AS ?avg_scenario_shift)
  (ROUND(AVG(?scenarioCount)) AS ?avg_scenario_count)
  (ROUND(AVG(?riskScore)) AS ?avg_risk_score)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?rt ;
            wm:investorId ?investorId .

  ?rt rdfs:label ?riskTolerance .

  OPTIONAL {
    ?ph a wm:PortfolioHealth ;
        wm:healthOfInvestor ?investor ;
        wm:riskScore ?riskScore .
  }

  OPTIONAL {
    SELECT ?investor (COUNT(?sr) AS ?scenarioCount) (AVG(?shift) AS ?scenarioShift)
    WHERE {
      OPTIONAL {
        ?sr a wm:ScenarioRebalancing ;
            wm:scenarioRebalancingOfInvestor ?investor ;
            wm:currentAllocationPct ?current ;
            wm:newAllocationPct ?new .
        BIND(xsd:decimal(?new) - xsd:decimal(?current) AS ?shift)
      }
    }
    GROUP BY ?investor
  }

  BIND(COALESCE(?scenarioCount, 0) AS ?scenarioCount)
  BIND(COALESCE(?scenarioShift, 0) AS ?scenarioShift)
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?scenarioShift)) AS ?avg_scenario_shift)
  (ROUND(AVG(?scenarioCount)) AS ?avg_scenario_count)
  (ROUND(AVG(?goalProgress)) AS ?avg_goal_progress)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?rtObj ;
            wm:investorId ?investorId .

  ?rtObj rdfs:label ?riskTolerance .

  OPTIONAL {
    ?scenario a wm:ScenarioRebalancing ;
              wm:scenarioRebalancingOfInvestor ?investor ;
              wm:currentAllocationPct ?currentAlloc ;
              wm:newAllocationPct ?newAlloc .
    BIND(xsd:decimal(?newAlloc) - xsd:decimal(?currentAlloc) AS ?scenarioShift)
  }

  OPTIONAL {
    ?goal a wm:InvestmentGoal ;
          wm:belongsToInvestor ?investor ;
          wm:progressPct ?progress .
    BIND(xsd:decimal(?progress) AS ?goalProgress)
  }

  BIND(
    COALESCE(
      COUNT(DISTINCT ?scenario) FILTER (?scenario != UNDEF),
      0
    ) AS ?scenarioCount
  )
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?riskScore), 2) AS ?avg_risk_score)
  (ROUND(AVG(?liquidityScore), 2) AS ?avg_liquidity_score)
  (ROUND(AVG(?goalProgressPct), 2) AS ?avg_goal_progress)
  (COUNT(DISTINCT ?investor) AS ?n_investors)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?rt .
  ?rt rdfs:label ?riskTolerance .

  OPTIONAL {
    ?health a wm:PortfolioHealth ;
            wm:healthOfInvestor ?investor ;
            wm:riskScore ?riskScore ;
            wm:liquidityScore ?liquidityScore .
  }

  OPTIONAL {
    ?goal a wm:InvestmentGoal ;
          wm:belongsToInvestor ?investor ;
          wm:progressPct ?goalProgressPct .
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?timeHorizonLabel AS ?group_value
  (ROUND(AVG(?netCashFlow)) AS ?avg_net_cash_flow)
  (ROUND(AVG(?signedCashFlow)) AS ?avg_signed_cash_flow)
  (ROUND(AVG(?totalHoldingValue)) AS ?avg_total_holding_value)
  (COUNT(DISTINCT ?investorId) AS ?n_investors)
WHERE {
  ?investor a wm:Investor ;
            wm:hasTimeHorizon ?timeHorizon ;
            wm:investorId ?investorId .

  ?timeHorizon rdfs:label ?timeHorizonLabel .

  OPTIONAL {
    ?cashFlow wm:cashFlowOfInvestor ?investor ;
              wm:amount ?amountStr ;
              wm:type ?cfType .
    BIND(xsd:decimal(?amountStr) AS ?amount)
    BIND(IF(?cfType IN ("SIP", "Lump Sum", "Deposit"), -?amount, ?amount) AS ?signedCashFlow)
  }

  OPTIONAL {
    ?holding wm:heldByInvestor ?investor ;
             wm:currentValue ?currentValueStr .
    BIND(xsd:decimal(?currentValueStr) AS ?holdingValue)
  }

  BIND(COALESCE(SUM(?signedCashFlow), 0) AS ?netCashFlow)
  BIND(COALESCE(SUM(?holdingValue), 0) AS ?totalHoldingValue)
}
GROUP BY ?timeHorizonLabel
ORDER BY ?timeHorizonLabel

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId
           (SUM(xsd:decimal(?cashFlowAmount)) AS ?netCashFlow)
    WHERE {
      ?cashFlow wm:cashFlowOfInvestor ?investor ;
                wm:amount ?cashFlowAmount ;
                wm:type ?cashFlowType .
      ?investor wm:investorId ?investorId .
      FILTER (?cashFlowType IN ("SIP", "Lump Sum", "Deposit", "Redemption", "Withdrawal"))
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId
           (SUM(xsd:decimal(?currentValue) - xsd:decimal(?cost)) AS ?totalGain)
    WHERE {
      ?holding wm:heldByInvestor ?investor ;
               wm:cost ?cost ;
               wm:currentValue ?currentValue ;
               wm:holdingId ?holdingId .
      ?investor wm:investorId ?investorId .
      FILTER (xsd:decimal(?cost) > 0 && xsd:decimal(?currentValue) >= 0)
    }
    GROUP BY ?investorId
  }
  BIND ((?netCashFlow + ?totalGain) AS ?compositeScore)
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?investorId ?compositeScore
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:hasCashFlow ?cashFlow ;
            wm:hasSectorAllocation ?sectorAlloc .

  ?cashFlow wm:amount ?cashFlowAmount ;
            wm:type ?cashFlowType .

  ?sectorAlloc wm:totalInvestment ?totalSectorInvestment .

  {
    SELECT ?investorId
           (SUM(IF(?type = "Inflow", -xsd:decimal(?cashFlowAmount), xsd:decimal(?cashFlowAmount))) AS ?netCashFlow)
           (SUM(xsd:decimal(?totalSectorInvestment)) AS ?totalSectorInvestmentSum)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasCashFlow ?cf ;
                wm:hasSectorAllocation ?sa .

      ?cf wm:amount ?cashFlowAmount ;
          wm:type ?type .

      ?sa wm:totalInvestment ?totalSectorInvestment .
    }
    GROUP BY ?investorId
    HAVING (COUNT(?cf) > 0 && COUNT(?sa) > 0)
  }

  BIND((?netCashFlow + ?totalSectorInvestmentSum) AS ?compositeScore)
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?investorId
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:hasCashFlow ?cashFlow ;
            wm:hasRebalancingAction ?rebalancingAction .

  ?cashFlow wm:amount ?cashFlowAmount ;
            wm:type ?cashFlowType .

  ?rebalancingAction wm:amount ?rebalancingAmount .

  BIND(IF(?cashFlowType IN ("SIP", "Lump Sum", "Deposit"), -1 * xsd:decimal(?cashFlowAmount), xsd:decimal(?cashFlowAmount)) AS ?netCashFlow)
  BIND(xsd:decimal(?rebalancingAmount) AS ?rebAmt)

  {
    SELECT ?investorId (SUM(?netCashFlow) AS ?totalNetCashFlow) (SUM(?rebAmt) AS ?totalRebalAmount)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasCashFlow ?cashFlow ;
                wm:hasRebalancingAction ?rebalancingAction .

      ?cashFlow wm:amount ?cashFlowAmount ;
                wm:type ?cashFlowType .

      ?rebalancingAction wm:amount ?rebalancingAmount .

      BIND(IF(?cashFlowType IN ("SIP", "Lump Sum", "Deposit"), -1 * xsd:decimal(?cashFlowAmount), xsd:decimal(?cashFlowAmount)) AS ?netCashFlow)
      BIND(xsd:decimal(?rebalancingAmount) AS ?rebAmt)
    }
    GROUP BY ?investorId
    HAVING (SUM(?netCashFlow) >= 0 && SUM(?rebAmt) >= 0)
  }

  BIND((?totalNetCashFlow + ?totalRebalAmount) AS ?compositeScore)
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?investorId ?compositeScore
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:hasCashFlow ?cashFlow ;
            wm:hasInvestmentGoal ?goal ;
            wm:hasHolding ?holding .

  # Net Cash Flow (sum of all cash flows)
  BIND(
    SUM(COALESCE(xsd:decimal(?cashFlowAmount), 0)) AS ?netCashFlow
  ) WHERE {
    ?cashFlow wm:amount ?cashFlowAmount .
  }

  # Average Goal Shortfall
  BIND(
    AVG(COALESCE(xsd:decimal(?goalShortfall), 0)) AS ?avgShortfall
  ) WHERE {
    ?goal wm:shortfall ?goalShortfall .
  }

  # Composite Score = Net Cash Flow - Average Goal Shortfall
  BIND((?netCashFlow - ?avgShortfall) AS ?compositeScore)

}
GROUP BY ?investorId
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId
           (SUM(xsd:decimal(?holdingGain)) AS ?totalHoldingGain)
           (SUM(xsd:decimal(?rebalanceAmount)) AS ?totalRebalanceAmount)
           (SUM(xsd:decimal(?holdingGain)) + SUM(xsd:decimal(?rebalanceAmount)) AS ?compositeScore)
    WHERE {
      ?holding wm:heldByInvestor ?investor ;
               wm:cost ?cost ;
               wm:currentValue ?currentValue .
      BIND(xsd:decimal(?currentValue) - xsd:decimal(?cost) AS ?holdingGain)
      FILTER(?holdingGain != 0)

      OPTIONAL {
        ?rebalancing wm:rebalancingActionOfInvestor ?investor ;
                     wm:amount ?rebalanceAmount .
      }

      ?investor wm:investorId ?investorId .
    }
    GROUP BY ?investorId
    HAVING (SUM(xsd:decimal(?holdingGain)) > 0 && SUM(xsd:decimal(?rebalanceAmount)) >= 0)
  }
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?investorId ?compositeScore
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:hasHolding ?holding ;
            wm:hasSectorAllocation ?allocation .

  ?holding a wm:PortfolioHolding ;
           wm:cost ?cost ;
           wm:currentValue ?currentValue .

  ?allocation a wm:SectorAllocation ;
              wm:totalInvestment ?totalInvestment .

  BIND(xsd:decimal(?currentValue) - xsd:decimal(?cost) AS ?gain)
  BIND(xsd:decimal(?totalInvestment) AS ?investment)

  {
    SELECT ?investorId (SUM(?gain) AS ?totalGain) (SUM(?investment) AS ?totalSectorInvestment)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasHolding ?holding ;
                wm:hasSectorAllocation ?allocation .

      ?holding a wm:PortfolioHolding ;
               wm:cost ?cost ;
               wm:currentValue ?currentValue .

      ?allocation a wm:SectorAllocation ;
                  wm:totalInvestment ?totalInvestment .

      BIND(xsd:decimal(?currentValue) - xsd:decimal(?cost) AS ?gain)
      BIND(xsd:decimal(?totalInvestment) AS ?investment)
    }
    GROUP BY ?investorId
  }

  BIND(?totalGain + ?totalSectorInvestment AS ?compositeScore)
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
WITH (
  SELECT 
    ph.healthOfInvestor AS investor,
    SUM(CASE WHEN h.cost > 0 AND h.currentValue >= 0 THEN (h.currentValue - h.cost) ELSE 0 END) AS total_gain,
    MAX(ph.riskScore) AS risk_score
  WHERE {
    ?h a wm:PortfolioHolding ;
       wm:heldByInvestor ?investor ;
       wm:cost ?cost_raw ;
       wm:currentValue ?current_value_raw .

    BIND(xsd:decimal(?cost_raw) AS ?cost)
    BIND(xsd:decimal(?current_value_raw) AS ?current_value)

    FILTER(?cost > 0 && ?current_value >= 0)

    OPTIONAL {
      ?ph a wm:PortfolioHealth ;
          wm:healthOfInvestor ?investor ;
          wm:riskScore ?risk_score_raw .
      BIND(xsd:decimal(?risk_score_raw) AS ?risk_score)
    }
  }
  GROUP BY ?investor
  HAVING(ISNUMERIC(?total_gain) && ISNUMERIC(?risk_score))
) AS gains_and_risks

WITH (
  SELECT 
    MIN(total_gain) AS min_gain,
    MAX(total_gain) AS max_gain,
    MIN(risk_score) AS min_risk,
    MAX(risk_score) AS max_risk
  FROM gains_and_risks
) AS norm_bounds

SELECT 
  ?investor_id
  ((100 * ((xsd:decimal(?total_gain) - ?min_gain)/(?max_gain - ?min_gain)) +
     (xsd:decimal(?risk_score) - ?min_risk)/(?max_risk - ?min_risk)) / 2) AS composite_score
WHERE {
  INCLUDE gains_and_risks

  ?investor a wm:Investor ;
            wm:investorId ?investor_id .

  INCLUDE norm_bounds
}
ORDER BY DESC(composite_score) ?investor_id
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?investorId
WHERE {
  {
    SELECT ?investorId
           (SUM(xsd:decimal(?currentValue) - xsd:decimal(?cost)) AS ?totalGain)
    WHERE {
      ?holding wm:heldByInvestor ?investor .
      ?investor wm:investorId ?investorId .
      ?holding wm:cost ?cost .
      ?holding wm:currentValue ?currentValue .
      FILTER (?cost != "" && ?currentValue != "")
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId
           (AVG(xsd:decimal(?shortfall)) AS ?avgShortfall)
    WHERE {
      ?goal wm:belongsToInvestor ?investor .
      ?investor wm:investorId ?investorId .
      ?goal wm:shortfall ?shortfall .
      FILTER (?shortfall != "")
    }
    GROUP BY ?investorId
  }
}
ORDER BY DESC(?totalGain - ?avgShortfall) ?investorId
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
WITH (
  SELECT
    ph.heldByInvestor AS investor,
    SUM(xsd:decimal(ph.currentValue) - xsd:decimal(ph.cost)) AS total_gain
  WHERE {
    ?ph a wm:PortfolioHolding ;
        wm:heldByInvestor ?investor ;
        wm:cost ?cost ;
        wm:currentValue ?currentValue .
    FILTER (?cost > 0 && ?currentValue >= 0)
  }
  GROUP BY ph.heldByInvestor
) AS gain_cte,

(
  SELECT
    sr.scenarioRebalancingOfInvestor AS investor,
    SUM(xsd:decimal(sr.newAllocationPct) - xsd:decimal(sr.currentAllocationPct)) AS alloc_shift
  WHERE {
    ?sr a wm:ScenarioRebalancing ;
        wm:scenarioRebalancingOfInvestor ?investor ;
        wm:currentAllocationPct ?currentAllocationPct ;
        wm:newAllocationPct ?newAllocationPct .
  }
  GROUP BY sr.scenarioRebalancingOfInvestor
) AS shift_cte

SELECT ?investorId ((100 * (?norm_gain + ?norm_shift) / 2) AS ?composite_score)
WHERE {
  {
    SELECT
      MIN(?total_gain) AS ?min_gain,
      MAX(?total_gain) AS ?max_gain,
      MIN(?alloc_shift) AS ?min_shift,
      MAX(?alloc_shift) AS ?max_shift
    WHERE {
      ?gain_inv wm:investorId ?_ .
      ?shift_inv wm:investorId ?__ .
      BIND(COALESCE(?total_gain, 0) AS ?gain_val)
      BIND(COALESCE(?alloc_shift, 0) AS ?shift_val)
    }
    BIND(IF(?max_gain = ?min_gain, 1, ?max_gain - ?min_gain) AS ?gain_range)
    BIND(IF(?max_shift = ?min_shift, 1, ?max_shift - ?min_shift) AS ?shift_range)
  }

  ?investor wm:investorId ?investorId ;
            ^wm:heldByInvestor ?gain_holder ;
            ^wm:scenarioRebalancingOfInvestor ?shift_holder .

  OPTIONAL {
    ?gain_holder wm:cost ?cost ;
                 wm:currentValue ?currentValue .
    FILTER (?cost > 0 && ?currentValue >= 0)
  }

  OPTIONAL {
    ?shift_holder wm:currentAllocationPct ?currentAllocationPct ;
                  wm:newAllocationPct ?newAllocationPct .
  }

  BIND(COALESCE(SUM(xsd:decimal(?currentValue) - xsd:decimal(?cost)), 0) AS ?total_gain)
  BIND(COALESCE(SUM(xsd:decimal(?newAllocationPct) - xsd:decimal(?currentAllocationPct)), 0) AS ?alloc_shift)

  BIND((?total_gain - ?min_gain) / ?gain_range AS ?norm_gain)
  BIND((?alloc_shift - ?min_shift) / ?shift_range AS ?norm_shift)

  FILTER (?norm_gain != "" && ?norm_shift != "")
}
GROUP BY ?investorId ?norm_gain ?norm_shift
ORDER BY DESC(?composite_score) ?investorId
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?netCashFlow)) AS ?avg_net_cash_flow)
  (ROUND(AVG(?signedCashFlowAmount)) AS ?avg_signed_cash_flow_amount)
  (ROUND(AVG(?totalHoldingValue)) AS ?avg_total_holding_value)
  (ROUND(AVG(?rebalanceAmount)) AS ?avg_rebalance_amount)
  (COUNT(DISTINCT ?investor) AS ?n_investors)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?rt .
  ?rt rdfs:label ?riskTolerance .

  OPTIONAL {
    ?cashFlow wm:cashFlowOfInvestor ?investor ;
              wm:amount ?cfAmount ;
              wm:hasCashFlowType ?cfType .
    ?cfType rdfs:label ?cfTypeName .
    BIND(IF(?cfTypeName IN ("SIP", "Lump Sum", "Deposit"), -1 * xsd:decimal(?cfAmount), xsd:decimal(?cfAmount)) AS ?signedCashFlowAmount)
  }

  OPTIONAL {
    ?holding wm:heldByInvestor ?investor ;
             wm:currentValue ?hv .
    BIND(xsd:decimal(?hv) AS ?holdingValue)
  }

  OPTIONAL {
    ?rebalancingAction wm:rebalancingActionOfInvestor ?investor ;
                       wm:amount ?raAmount .
    BIND(xsd:decimal(?raAmount) AS ?rebalanceAmount)
  }

  BIND(COALESCE(SUM(?signedCashFlowAmount), 0) AS ?netCashFlow)
  BIND(COALESCE(SUM(?holdingValue), 0) AS ?totalHoldingValue)

}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
WITH (
  SELECT 
    investorId,
    SUM(ABS(newAllocationPct - currentAllocationPct)) AS total_scenario_shift
  FROM wm:ScenarioRebalancing
  GROUP BY investorId
) AS scenario_shifts,

(
  SELECT 
    investorId,
    SUM(amount) AS total_rebalance_amount
  FROM wm:RebalancingAction
  GROUP BY investorId
) AS rebalances

SELECT 
  ?investorId
  ((100 * ((?norm_rebalance + ?norm_shift) / 2)) AS ?composite_score)
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId .

  FILTER EXISTS { [] wm:rebalancingActionOfInvestor ?investor . }
  FILTER EXISTS { [] wm:scenarioRebalancingOfInvestor ?investor . }

  BIND(IF(?max_rebalance = ?min_rebalance, 0,
          (?total_rebalance_amount - ?min_rebalance) / (?max_rebalance - ?min_rebalance)) AS ?norm_rebalance)
  BIND(IF(?max_shift = ?min_shift, 0,
          (?total_scenario_shift - ?min_shift) / (?max_shift - ?min_shift)) AS ?norm_shift)

  {
    SELECT 
      (MAX(?total_rebalance_amount_) AS ?max_rebalance)
      (MIN(?total_rebalance_amount_) AS ?min_rebalance)
      (MAX(?total_scenario_shift_) AS ?max_shift)
      (MIN(?total_scenario_shift_) AS ?min_shift)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId_ .

      OPTIONAL {
        ?ra wm:rebalancingActionOfInvestor ?investor ;
             wm:amount ?amt .
        BIND(xsd:decimal(?amt) AS ?amount_val)
      }
      BIND(COALESCE(SUM(?amount_val), 0) AS ?total_rebalance_amount_)

      OPTIONAL {
        ?sr wm:scenarioRebalancingOfInvestor ?investor ;
              wm:newAllocationPct ?new ;
              wm:currentAllocationPct ?curr .
        BIND(xsd:decimal(?new) - xsd:decimal(?curr) AS ?diff)
      }
      BIND(COALESCE(SUM(ABS(?diff)), 0) AS ?total_scenario_shift_)
    }
    GROUP BY ()
  }
}
ORDER BY DESC(?composite_score) ?investorId
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?netCashFlow), 2) AS ?avg_net_cash_flow)
  (ROUND(AVG(?signedCashFlow), 2) AS ?avg_signed_cash_flow)
  (ROUND(AVG(?totalHoldingValue), 2) AS ?avg_total_holding_value)
  (ROUND(AVG(?scenarioShift), 2) AS ?avg_scenario_shift)
  (COUNT(DISTINCT ?investor) AS ?n_investors)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?rt .
  ?rt rdfs:label ?riskTolerance .

  OPTIONAL {
    SELECT ?investor (SUM(IF(?type IN ("SIP", "Lump Sum", "Deposit"), -xsd:decimal(?amount), xsd:decimal(?amount))) AS ?netCashFlow)
           (AVG(xsd:decimal(?amount)) AS ?signedCashFlow)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:cashFlowOfInvestor ?investor ;
          wm:amount ?amount ;
          wm:hasCashFlowType ?cft .
      ?cft rdfs:label ?type .
    }
    GROUP BY ?investor
  }

  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(?currentValue)) AS ?totalHoldingValue)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:currentValue ?currentValue .
    }
    GROUP BY ?investor
  }

  OPTIONAL {
    SELECT ?investor (AVG(xsd:decimal(?newAlloc) - xsd:decimal(?currAlloc)) AS ?scenarioShift)
    WHERE {
      ?sr a wm:ScenarioRebalancing ;
          wm:scenarioRebalancingOfInvestor ?investor ;
          wm:newAllocationPct ?newAlloc ;
          wm:currentAllocationPct ?currAlloc .
    }
    GROUP BY ?investor
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?netCashFlow)) AS ?avg_net_cash_flow)
  (ROUND(AVG(?signedCashFlowAmount)) AS ?avg_signed_cash_flow_amount)
  (ROUND(AVG(?totalHoldingValue)) AS ?avg_total_holding_value)
  (ROUND(AVG(?totalSectorInvestment)) AS ?avg_total_sector_investment)
  (COUNT(DISTINCT ?investor) AS ?n_investors)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?rt .
  ?rt rdfs:label ?riskTolerance .

  OPTIONAL {
    ?cashFlow wm:cashFlowOfInvestor ?investor ;
              wm:amount ?cfAmountStr ;
              wm:hasCashFlowType ?cfType .
    BIND(xsd:decimal(?cfAmountStr) AS ?cfAmount)
    ?cfType rdfs:label ?cfTypeLabel .
    BIND(IF(?cfTypeLabel IN ("SIP", "Lump Sum", "Deposit"), -?cfAmount, ?cfAmount) AS ?signedCashFlow)
  }

  OPTIONAL {
    ?holding wm:heldByInvestor ?investor ;
             wm:currentValue ?hvStr .
    BIND(xsd:decimal(?hvStr) AS ?holdingValue)
  }

  OPTIONAL {
    ?sectorAlloc wm:allocationOfInvestor ?investor ;
                 wm:totalInvestment ?siStr .
    BIND(xsd:decimal(?siStr) AS ?sectorInvestment)
  }

  BIND(COALESCE(?signedCashFlow, 0) AS ?signedCashFlowAmount)
  BIND(COALESCE(?holdingValue, 0) AS ?holdingVal)
  BIND(COALESCE(?sectorInvestment, 0) AS ?sectInv)

  {
    SELECT ?investor
           (SUM(?signedCashFlowAmount) AS ?netCashFlow)
           (AVG(?signedCashFlowAmount) AS ?avgSignedCashFlow)
           (SUM(?holdingVal) AS ?totalHoldingValue)
           (SUM(?sectInv) AS ?totalSectorInvestment)
    WHERE {
      ?investor a wm:Investor .

      OPTIONAL {
        ?cashFlow wm:cashFlowOfInvestor ?investor ;
                  wm:amount ?cfAmountStr ;
                  wm:hasCashFlowType ?cfType .
        BIND(xsd:decimal(?cfAmountStr) AS ?cfAmount)
        ?cfType rdfs:label ?cfTypeLabel .
        BIND(IF(?cfTypeLabel IN ("SIP", "Lump Sum", "Deposit"), -?cfAmount, ?cfAmount) AS ?signedCashFlow)
      }

      OPTIONAL {
        ?holding wm:heldByInvestor ?investor ;
                 wm:currentValue ?hvStr .
        BIND(xsd:decimal(?hvStr) AS ?holdingValue)
      }

      OPTIONAL {
        ?sectorAlloc wm:allocationOfInvestor ?investor ;
                     wm:totalInvestment ?siStr .
        BIND(xsd:decimal(?siStr) AS ?sectorInvestment)
      }

      BIND(COALESCE(?signedCashFlow, 0) AS ?signedCashFlowAmount)
      BIND(COALESCE(?holdingValue, 0) AS ?holdingVal)
      BIND(COALESCE(?sectorInvestment, 0) AS ?sectInv)
    }
    GROUP BY ?investor
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?netCashFlow)) AS ?avg_net_cash_flow)
  (ROUND(AVG(?avgCashFlowAmount)) AS ?avg_cash_flow_amount)
  (ROUND(AVG(?totalHoldingValue)) AS ?avg_total_holding_value)
  (ROUND(AVG(?goalProgress)) AS ?avg_goal_progress)
  (COUNT(DISTINCT ?investor) AS ?n_investors)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?rt .
  ?rt rdfs:label ?riskTolerance .

  OPTIONAL {
    ?cf wm:cashFlowOfInvestor ?investor ;
        wm:amount ?cfAmount .
    BIND(xsd:decimal(?cfAmount) AS ?amount)
  }
  BIND(COALESCE(SUM(IF(?amount > 0, ?amount, 0)), 0) - COALESCE(SUM(IF(?amount < 0, ABS(?amount), 0)), 0) AS ?netCashFlow)
  BIND(COALESCE(AVG(ABS(?amount)), 0) AS ?avgCashFlowAmount)

  OPTIONAL {
    ?holding wm:heldByInvestor ?investor ;
             wm:currentValue ?hv .
    BIND(xsd:decimal(?hv) AS ?holdingValue)
  }
  BIND(COALESCE(SUM(?holdingValue), 0) AS ?totalHoldingValue)

  OPTIONAL {
    ?goal wm:belongsToInvestor ?investor ;
          wm:progressPct ?gp .
    BIND(xsd:decimal(?gp) AS ?goalProgress)
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?netCashFlow)) AS ?avg_net_cash_flow)
  (ROUND(AVG(?avgCashFlowAmount)) AS ?avg_cash_flow_amount)
  (ROUND(AVG(?totalHoldingValue)) AS ?avg_total_holding_value)
  (ROUND(AVG(?riskScore)) AS ?avg_risk_score)
  (COUNT(DISTINCT ?investor) AS ?n_investors)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?rt .
  ?rt rdfs:label ?riskTolerance .

  OPTIONAL {
    ?cashFlow wm:cashFlowOfInvestor ?investor ;
              wm:amount ?cfAmount .
    BIND(xsd:decimal(?cfAmount) AS ?amount)
  }

  OPTIONAL {
    ?holding wm:heldByInvestor ?investor ;
             wm:currentValue ?hv .
    BIND(xsd:decimal(?hv) AS ?holdingValue)
  }

  OPTIONAL {
    ?health wm:healthOfInvestor ?investor ;
            wm:riskScore ?rs .
    BIND(xsd:decimal(?rs) AS ?riskScore)
  }

  BIND(COALESCE(?amount, 0) AS ?cashFlowAmt)
  BIND(COALESCE(?holdingValue, 0) AS ?value)

  {
    SELECT ?investor
           (SUM(IF(?cashFlowTypeLabel IN ("SIP", "Lump Sum", "Deposit"), -?cashFlowAmt, ?cashFlowAmt)) AS ?netCashFlow)
           (AVG(?cashFlowAmt) AS ?avgCashFlowAmount)
    WHERE {
      ?cashFlow wm:cashFlowOfInvestor ?investor ;
                wm:hasCashFlowType ?cft .
      ?cft rdfs:label ?cashFlowTypeLabel .
      ?cashFlow wm:amount ?cfAmount .
      BIND(xsd:decimal(?cfAmount) AS ?cashFlowAmt)
    }
    GROUP BY ?investor
  }

  {
    SELECT ?investor (SUM(?value) AS ?totalHoldingValue)
    WHERE {
      OPTIONAL {
        ?holding wm:heldByInvestor ?investor ;
                 wm:currentValue ?hv .
        BIND(xsd:decimal(?hv) AS ?value)
      }
      BIND(COALESCE(?value, 0) AS ?value)
    }
    GROUP BY ?investor
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?netCashFlow)) AS ?avg_net_cash_flow)
  (ROUND(AVG(?avgCashFlowAmount)) AS ?avg_cash_flow_amount)
  (ROUND(AVG(?totalRebalanceAmount)) AS ?avg_total_rebalance_amount)
  (ROUND(AVG(?totalSectorInvestment)) AS ?avg_total_sector_investment)
  (COUNT(DISTINCT ?investorId) AS ?n_investors)
WHERE {
  {
    SELECT 
      ?investorId
      (SUM(IF(?cfType IN ("SIP", "Lump Sum", "Deposit"), -xsd:decimal(?cfAmount), xsd:decimal(?cfAmount))) AS ?netCashFlow)
      (AVG(xsd:decimal(?cfAmount)) AS ?avgCashFlowAmount)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?cfAmount ;
                wm:hasCashFlowType ?cfTypeNode .
      ?cfTypeNode rdfs:label ?cfType .
      ?investor wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }

  OPTIONAL {
    SELECT 
      ?investorId
      (SUM(xsd:decimal(?raAmount)) AS ?totalRebalanceAmount)
    WHERE {
      ?ra a wm:RebalancingAction ;
          wm:rebalancingActionOfInvestor ?investor ;
          wm:amount ?raAmount .
      ?investor wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }

  OPTIONAL {
    SELECT 
      ?investorId
      (SUM(xsd:decimal(?saTotalInvestment)) AS ?totalSectorInvestment)
    WHERE {
      ?sa a wm:SectorAllocation ;
          wm:allocationOfInvestor ?investor ;
          wm:totalInvestment ?saTotalInvestment .
      ?investor wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }

  ?investorProfile a wm:Investor ;
                   wm:investorId ?investorId ;
                   wm:hasRiskTolerance ?rt .
  ?rt rdfs:label ?riskTolerance .
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?netCashFlow)) AS ?avg_net_cash_flow)
  (ROUND(AVG(?avgCashFlowAmount)) AS ?avg_cash_flow_amount)
  (ROUND(AVG(?totalRebalanceAmount)) AS ?avg_total_rebalance_amount)
  (ROUND(AVG(?allocationShift)) AS ?avg_scenario_allocation_shift)
  (COUNT(DISTINCT ?investorId) AS ?n_investors)
WHERE {
  {
    SELECT 
      ?investorId
      (SUM(IF(?cfType IN ("SIP", "Lump Sum", "Deposit"), -xsd:decimal(?amount), xsd:decimal(?amount))) AS ?netCashFlow)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?amount ;
                wm:hasCashFlowType ?cfTypeNode .
      ?cfTypeNode rdfs:label ?cfType .
      ?investor wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }

  {
    SELECT 
      ?investorId
      (AVG(xsd:decimal(?amount)) AS ?avgCashFlowAmount)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?amount .
      ?investor wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }

  {
    SELECT 
      ?investorId
      (SUM(xsd:decimal(?amount)) AS ?totalRebalanceAmount)
    WHERE {
      ?rebalancingAction a wm:RebalancingAction ;
                         wm:rebalancingActionOfInvestor ?investor ;
                         wm:amount ?amount .
      ?investor wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }

  {
    SELECT 
      ?investorId
      (AVG(xsd:decimal(?newAllocationPct) - xsd:decimal(?currentAllocationPct)) AS ?allocationShift)
    WHERE {
      ?scenarioRebalancing a wm:ScenarioRebalancing ;
                           wm:scenarioRebalancingOfInvestor ?investor ;
                           wm:newAllocationPct ?newAllocationPct ;
                           wm:currentAllocationPct ?currentAllocationPct .
      ?investor wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }

  ?investorProfile a wm:Investor ;
                   wm:investorId ?investorId ;
                   wm:hasRiskTolerance ?riskToleranceNode .
  ?riskToleranceNode rdfs:label ?riskTolerance .
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?netCashFlow)) AS ?avg_net_cash_flow)
  (ROUND(AVG(?avgCashFlowAmount)) AS ?avg_cash_flow_amount)
  (ROUND(AVG(?totalRebalanceAmount)) AS ?avg_rebalance_amount)
  (ROUND(AVG(?riskScore)) AS ?avg_risk_score)
  (COUNT(DISTINCT ?investor) AS ?n_investors)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?rt .
  ?rt rdfs:label ?riskTolerance .

  OPTIONAL {
    ?cashFlow wm:cashFlowOfInvestor ?investor ;
              wm:amount ?cfAmount .
    BIND(xsd:decimal(?cfAmount) AS ?amount)
  }
  BIND(IF(BOUND(?amount), ?amount, 0) AS ?safeAmount)

  OPTIONAL {
    ?rebalancing wm:rebalancingActionOfInvestor ?investor ;
                 wm:amount ?rbAmount .
    BIND(xsd:decimal(?rbAmount) AS ?rebAmount)
  }
  BIND(IF(BOUND(?rebAmount), ?rebAmount, 0) AS ?safeRebAmount)

  OPTIONAL {
    ?health wm:healthOfInvestor ?investor ;
            wm:riskScore ?rs .
    BIND(xsd:decimal(?rs) AS ?riskScore)
  }

  {
    SELECT ?investor
           (SUM(IF(?cfType = "Inflow", ?safeAmount, -?safeAmount)) AS ?netCashFlow)
           (AVG(?safeAmount) AS ?avgCashFlowAmount)
    WHERE {
      ?cashFlow wm:cashFlowOfInvestor ?investor ;
                wm:amount ?cfAmount ;
                wm:type ?cfType .
      BIND(xsd:decimal(?cfAmount) AS ?safeAmount)
    }
    GROUP BY ?investor
  }

  {
    SELECT ?investor (SUM(?safeRebAmount) AS ?totalRebalanceAmount)
    WHERE {
      ?rebalancing wm:rebalancingActionOfInvestor ?investor ;
                   wm:amount ?rbAmount .
      BIND(xsd:decimal(?rbAmount) AS ?safeRebAmount)
    }
    GROUP BY ?investor
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?netCashFlow)) AS ?avg_net_cash_flow)
  (ROUND(AVG(?avgCashFlowAmount)) AS ?avg_cash_flow_amount)
  (ROUND(AVG(?totalRebalanceAmount)) AS ?avg_rebalance_amount)
  (ROUND(AVG(?goalProgressPct)) AS ?avg_goal_progress)
  (COUNT(DISTINCT ?investor) AS ?n_investors)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?rt .
  ?rt rdfs:label ?riskTolerance .

  OPTIONAL {
    ?cf wm:cashFlowOfInvestor ?investor ;
        wm:amount ?cfAmount .
    BIND(xsd:decimal(?cfAmount) AS ?amount)
  }
  BIND(IF(BOUND(?amount), ?amount, 0) AS ?cashFlowVal)

  OPTIONAL {
    ?ra wm:rebalancingActionOfInvestor ?investor ;
         wm:amount ?raAmount .
    BIND(xsd:decimal(?raAmount) AS ?rebAmt)
  }
  BIND(IF(BOUND(?rebAmt), ?rebAmt, 0) AS ?rebalanceVal)

  OPTIONAL {
    ?ig wm:belongsToInvestor ?investor ;
        wm:progressPct ?progressPct .
    BIND(xsd:decimal(?progressPct) AS ?goalProg)
  }
  BIND(IF(BOUND(?goalProg), ?goalProg, 0) AS ?goalProgressPct)

  OPTIONAL {
    SELECT ?investor (SUM(?cashFlowVal) AS ?netCashFlow) (AVG(?cashFlowVal) AS ?avgCashFlowAmount)
    WHERE {
      ?cf wm:cashFlowOfInvestor ?investor ;
          wm:amount ?cfAmount .
      BIND(xsd:decimal(?cfAmount) AS ?cashFlowVal)
    }
    GROUP BY ?investor
  }

  OPTIONAL {
    SELECT ?investor (SUM(?rebalanceVal) AS ?totalRebalanceAmount)
    WHERE {
      ?ra wm:rebalancingActionOfInvestor ?investor ;
           wm:amount ?raAmount .
      BIND(xsd:decimal(?raAmount) AS ?rebalanceVal)
    }
    GROUP BY ?investor
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?netCashFlow)) AS ?avg_net_cash_flow)
  (ROUND(AVG(?avgCashFlowAmount)) AS ?avg_cash_flow_amount)
  (ROUND(AVG(?avgSectorInvestment)) AS ?avg_total_sector_investment)
  (ROUND(AVG(?riskScore)) AS ?avg_risk_score)
  (COUNT(DISTINCT ?investor) AS ?n_investors)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?rt .
  ?rt rdfs:label ?riskTolerance .

  OPTIONAL {
    ?cashFlow wm:cashFlowOfInvestor ?investor ;
              wm:amount ?amount .
    BIND(xsd:decimal(?amount) AS ?amt)
  }

  OPTIONAL {
    ?sectorAlloc wm:allocationOfInvestor ?investor ;
                 wm:totalInvestment ?totalInv .
    BIND(xsd:decimal(?totalInv) AS ?invAmt)
  }

  OPTIONAL {
    ?health wm:healthOfInvestor ?investor ;
            wm:riskScore ?rs .
    BIND(xsd:decimal(?rs) AS ?riskScore)
  }

  BIND(COALESCE(SUM(?amt), 0) AS ?totalCashFlow)
  BIND(COALESCE(AVG(?amt), 0) AS ?avgCashFlowAmount)
  BIND(COALESCE(SUM(?invAmt), 0) AS ?avgSectorInvestment)
  BIND(?totalCashFlow AS ?netCashFlow)
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

