  (ROUND(AVG(?netCashFlow)) AS ?avg_net_cash_flow)
  (ROUND(AVG(?avgCashFlowAmount)) AS ?avg_cash_flow_amount)
  (ROUND(AVG(?riskScore)) AS ?avg_risk_score)
  (ROUND(AVG(?goalProgress)) AS ?avg_goal_progress)
  (COUNT(DISTINCT ?investor) AS ?n_investors)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?rt .
  ?rt rdfs:label ?riskTolerance .

  OPTIONAL {
    ?cashFlow wm:cashFlowOfInvestor ?investor ;
              wm:amount ?amountStr .
    BIND(xsd:decimal(?amountStr) AS ?amount)
  }
  BIND(IF(BOUND(?amount), ?amount, 0) AS ?cashFlowVal)

  OPTIONAL {
    ?holding wm:heldByInvestor ?investor ;
             wm:cost ?costStr ;
             wm:currentValue ?currentValueStr .
    BIND(xsd:decimal(?costStr) AS ?cost)
    BIND(xsd:decimal(?currentValueStr) AS ?currentValue)
  }

  OPTIONAL {
    ?goal wm:belongsToInvestor ?investor ;
          wm:progressPct ?progressPctStr .
    BIND(xsd:decimal(?progressPctStr) AS ?progressPct)
  }

  OPTIONAL {
    ?health wm:healthOfInvestor ?investor ;
            wm:riskScore ?riskScoreStr .
    BIND(xsd:decimal(?riskScoreStr) AS ?riskScore)
  }

  BIND(COALESCE(SUM(?cashFlowVal), 0) AS ?totalCashFlow)
  BIND(COALESCE(AVG(?cashFlowVal), 0) AS ?avgCashFlowAmount)
  BIND(COALESCE(?totalCashFlow - COALESCE(SUM(?cost), 0) + COALESCE(SUM(?currentValue), 0), 0) AS ?netCashFlow)
  BIND(COALESCE(AVG(?progressPct), 0) AS ?goalProgress)
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?netCashFlow)) AS ?avg_net_cash_flow)
  (ROUND(AVG(?avgCashFlowAmount)) AS ?avg_cash_flow_amount)
  (ROUND(AVG(?avgAllocationShift)) AS ?avg_scenario_allocation_shift)
  (ROUND(AVG(?goalProgress)) AS ?avg_goal_progress)
  (COUNT(DISTINCT ?investor) AS ?n_investors)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?rt .
  ?rt rdfs:label ?riskTolerance .

  # Net Cash Flow per investor
  OPTIONAL {
    SELECT ?investor (SUM(IF(?isInflow, -?amount, ?amount)) AS ?netCashFlow)
    WHERE {
      ?cf wm:cashFlowOfInvestor ?investor ;
          wm:amount ?amtStr ;
          wm:hasCashFlowType ?cftype .
      BIND(xsd:decimal(?amtStr) AS ?amount)
      ?cftype rdfs:label ?typeLabel .
      BIND(IF(?typeLabel IN ("SIP", "Lump Sum", "Deposit"), true, false) AS ?isInflow)
    }
    GROUP BY ?investor
  }

  # Average Cash Flow Amount per investor
  OPTIONAL {
    SELECT ?investor (AVG(?amount) AS ?avgCashFlowAmount)
    WHERE {
      ?cf wm:cashFlowOfInvestor ?investor ;
          wm:amount ?amtStr .
      BIND(xsd:decimal(?amtStr) AS ?amount)
    }
    GROUP BY ?investor
  }

  # Average Scenario Allocation Shift per investor
  OPTIONAL {
    SELECT ?investor (AVG(?shift) AS ?avgAllocationShift)
    WHERE {
      ?sr wm:scenarioRebalancingOfInvestor ?investor ;
          wm:currentAllocationPct ?currStr ;
          wm:newAllocationPct ?newStr .
      BIND(xsd:decimal(?currStr) AS ?curr)
      BIND(xsd:decimal(?newStr) AS ?new)
      BIND(?new - ?curr AS ?shift)
    }
    GROUP BY ?investor
  }

  # Average Goal Progress per investor
  OPTIONAL {
    SELECT ?investor (AVG(?progress) AS ?goalProgress)
    WHERE {
      ?goal wm:belongsToInvestor ?investor ;
            wm:progressPct ?progStr .
      BIND(xsd:decimal(?progStr) AS ?progress)
    }
    GROUP BY ?investor
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?totalHoldingValue), 2) AS ?avg_total_holding_value)
  (ROUND(AVG(?avgHoldingReturn), 2) AS ?avg_holding_return)
  (ROUND(AVG(?totalRebalanceAmount), 2) AS ?avg_total_rebalance_amount)
  (ROUND(AVG(?totalSectorInvestment), 2) AS ?avg_total_sector_investment)
  (COUNT(DISTINCT ?investor) AS ?n_investors)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?rt .
  ?rt rdfs:label ?riskTolerance .

  OPTIONAL {
    ?holding wm:heldByInvestor ?investor ;
             wm:cost ?cost ;
             wm:currentValue ?currentValue .
    BIND(xsd:decimal(?currentValue) AS ?cv)
    BIND(xsd:decimal(?cost) AS ?c)
    FILTER (?c > 0 && ?cv >= 0)
  }

  OPTIONAL {
    ?rebalancing wm:rebalancingActionOfInvestor ?investor ;
                 wm:amount ?rebAmount .
    BIND(xsd:decimal(?rebAmount) AS ?ra)
  }

  OPTIONAL {
    ?sectorAlloc wm:allocationOfInvestor ?investor ;
                 wm:totalInvestment ?totalInv .
    BIND(xsd:decimal(?totalInv) AS ?ti)
  }

  BIND(COALESCE(?cv, 0) AS ?holdingValue)
  BIND(IF(?c > 0, ((?cv - ?c) / ?c) * 100, 0) AS ?returnPct)

  {
    SELECT ?investor
           (SUM(?holdingValue) AS ?totalHoldingValue)
           (AVG(?returnPct) AS ?avgHoldingReturn)
    WHERE {
      ?holding wm:heldByInvestor ?investor ;
               wm:cost ?cost ;
               wm:currentValue ?currentValue .
      BIND(xsd:decimal(?currentValue) AS ?cv)
      BIND(xsd:decimal(?cost) AS ?c)
      FILTER (?c > 0 && ?cv >= 0)
      BIND(COALESCE(?cv, 0) AS ?holdingValue)
      BIND(IF(?c > 0, ((?cv - ?c) / ?c) * 100, 0) AS ?returnPct)
    }
    GROUP BY ?investor
  }

  {
    SELECT ?investor (SUM(?ra) AS ?totalRebalanceAmount)
    WHERE {
      ?rebalancing wm:rebalancingActionOfInvestor ?investor ;
                   wm:amount ?rebAmount .
      BIND(xsd:decimal(?rebAmount) AS ?ra)
    }
    GROUP BY ?investor
  }

  {
    SELECT ?investor (SUM(?ti) AS ?totalSectorInvestment)
    WHERE {
      ?sectorAlloc wm:allocationOfInvestor ?investor ;
                   wm:totalInvestment ?totalInv .
      BIND(xsd:decimal(?totalInv) AS ?ti)
    }
    GROUP BY ?investor
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?totalHoldingValue), 2) AS ?avg_total_holding_value)
  (ROUND(AVG(?avgHoldingReturn), 2) AS ?avg_holding_return)
  (ROUND(AVG(?totalRebalanceAmount), 2) AS ?avg_total_rebalance_amount)
  (ROUND(AVG(?avgScenarioShift), 2) AS ?avg_scenario_allocation_shift)
  (COUNT(DISTINCT ?investor) AS ?n_investors)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?rt .
  ?rt rdfs:label ?riskTolerance .

  OPTIONAL {
    ?holding wm:heldByInvestor ?investor ;
             wm:cost ?cost ;
             wm:currentValue ?currentValue .
    BIND(xsd:decimal(?currentValue) AS ?cv)
    BIND(xsd:decimal(?cost) AS ?c)
    FILTER(?c > 0 && ?cv >= 0)
    BIND((?cv - ?c) / ?c * 100 AS ?returnPct)
  }
  BIND(COALESCE(?cv, 0) AS ?holdingValue)

  OPTIONAL {
    ?rebalancing wm:rebalancingActionOfInvestor ?investor ;
                 wm:amount ?rebAmount .
    BIND(xsd:decimal(?rebAmount) AS ?ra)
  }

  OPTIONAL {
    ?scenarioRebalancing wm:scenarioRebalancingOfInvestor ?investor ;
                         wm:currentAllocationPct ?currAlloc ;
                         wm:newAllocationPct ?newAlloc .
    BIND(xsd:decimal(?newAlloc) - xsd:decimal(?currAlloc) AS ?shift)
  }

  {
    SELECT ?investor
           (SUM(?holdingValue) AS ?totalHoldingValue)
           (AVG(?returnPct) AS ?avgHoldingReturn)
    WHERE {
      ?holding wm:heldByInvestor ?investor ;
               wm:cost ?cost ;
               wm:currentValue ?currentValue .
      BIND(xsd:decimal(?currentValue) AS ?cv)
      BIND(xsd:decimal(?cost) AS ?c)
      FILTER(?c > 0 && ?cv >= 0)
      BIND((?cv - ?c) / ?c * 100 AS ?returnPct)
      BIND(?cv AS ?holdingValue)
    }
    GROUP BY ?investor
  }

  {
    SELECT ?investor (SUM(xsd:decimal(?rebAmount)) AS ?totalRebalanceAmount)
    WHERE {
      ?rebalancing wm:rebalancingActionOfInvestor ?investor ;
                   wm:amount ?rebAmount .
    }
    GROUP BY ?investor
  }

  {
    SELECT ?investor (AVG(xsd:decimal(?newAlloc) - xsd:decimal(?currAlloc)) AS ?avgScenarioShift)
    WHERE {
      ?scenarioRebalancing wm:scenarioRebalancingOfInvestor ?investor ;
                           wm:currentAllocationPct ?currAlloc ;
                           wm:newAllocationPct ?newAlloc .
    }
    GROUP BY ?investor
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?totalCurrentValue)) AS ?avg_total_holding_value)
  (ROUND(AVG(?avgReturnPct), 2) AS ?avg_holding_return)
  (ROUND(AVG(?totalRebalanceAmount), 2) AS ?avg_rebalance_amount)
  (ROUND(AVG(?goalProgressPct), 2) AS ?avg_goal_progress)
  (COUNT(DISTINCT ?investor) AS ?n_investors)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?rt .
  ?rt rdfs:label ?riskTolerance .

  # Holding CTE equivalent: total current value and average return per investor
  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(?cv)) AS ?totalCurrentValue) (AVG(xsd:decimal(?rp)) AS ?avgReturnPct)
    WHERE {
      ?holding wm:heldByInvestor ?investor ;
               wm:currentValue ?cv ;
               wm:returnsPct ?rp ;
               wm:cost ?cost .
      FILTER (?cv != "" && ?rp != "" && ?cost != "")
    }
    GROUP BY ?investor
  }

  # Rebalancing CTE equivalent: total rebalance amount per investor
  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(?amt)) AS ?totalRebalanceAmount)
    WHERE {
      ?ra wm:rebalancingActionOfInvestor ?investor ;
          wm:amount ?amt .
      FILTER (?amt != "")
    }
    GROUP BY ?investor
  }

  # Goal CTE equivalent: average progress percent per investor
  OPTIONAL {
    SELECT ?investor (AVG(xsd:decimal(?pp)) AS ?goalProgressPct)
    WHERE {
      ?goal wm:belongsToInvestor ?investor ;
            wm:progressPct ?pp .
      FILTER (?pp != "")
    }
    GROUP BY ?investor
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?totalCurrentValue)) AS ?avg_total_holding_value)
  (ROUND(AVG(?avgReturnPct), 2) AS ?avg_holding_return_pct)
  (ROUND(AVG(?totalRebalanceAmount)) AS ?avg_rebalance_amount)
  (ROUND(AVG(?riskScore), 2) AS ?avg_risk_score)
  (COUNT(DISTINCT ?investor) AS ?n_investors)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?rt .
  ?rt rdfs:label ?riskTolerance .

  # Total current value per investor
  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(?cv)) AS ?totalCurrentValue)
    WHERE {
      ?holding wm:heldByInvestor ?investor ;
               wm:currentValue ?cv ;
               wm:cost ?cost .
      FILTER (xsd:decimal(?cv) >= 0 && xsd:decimal(?cost) > 0)
    }
    GROUP BY ?investor
  }

  # Average return % per investor (only holdings with cost and current_value)
  OPTIONAL {
    SELECT ?investor (AVG(xsd:decimal(?returnPct)) AS ?avgReturnPct)
    WHERE {
      ?holding wm:heldByInvestor ?investor ;
               wm:returnsPct ?returnPct ;
               wm:currentValue ?cv ;
               wm:cost ?cost .
      FILTER (xsd:decimal(?cv) >= 0 && xsd:decimal(?cost) > 0)
    }
    GROUP BY ?investor
  }

  # Total rebalance amount per investor
  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(?amt)) AS ?totalRebalanceAmount)
    WHERE {
      ?ra wm:rebalancingActionOfInvestor ?investor ;
          wm:amount ?amt .
    }
    GROUP BY ?investor
  }

  # Risk score per investor
  OPTIONAL {
    ?ph wm:healthOfInvestor ?investor ;
        wm:riskScore ?riskScore .
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?investorId
       (SUM(xsd:decimal(?cashFlowAmount)) AS ?netCashFlow)
       (SUM(xsd:decimal(?holdingGain)) AS ?totalHoldingGain)
       (SUM(xsd:decimal(?sectorInvestment)) AS ?totalSectorInvestment)
       ((SUM(xsd:decimal(?cashFlowAmount)) + SUM(xsd:decimal(?holdingGain)) + SUM(xsd:decimal(?sectorInvestment))) AS ?compositeScore)
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId .

  OPTIONAL {
    ?cashFlow a wm:CashFlow ;
              wm:cashFlowOfInvestor ?investor ;
              wm:amount ?cashFlowAmount .
  }

  OPTIONAL {
    ?holding a wm:PortfolioHolding ;
             wm:heldByInvestor ?investor ;
             wm:cost ?cost ;
             wm:currentValue ?currentValue .
    BIND((xsd:decimal(?currentValue) - xsd:decimal(?cost)) AS ?holdingGain)
  }

  OPTIONAL {
    ?allocation a wm:SectorAllocation ;
                wm:allocationOfInvestor ?investor ;
                wm:totalInvestment ?sectorInvestment .
  }

  FILTER(BOUND(?cashFlowAmount) && BOUND(?holdingGain) && BOUND(?sectorInvestment))
}
GROUP BY ?investorId
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?investorId
       (SUM(xsd:decimal(?cashFlowAmount)) + 
        SUM(xsd:decimal(?holdingGain)) + 
        SUM(xsd:decimal(?rebalanceAmount)) AS ?compositeScore)
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId .

  OPTIONAL {
    ?cashFlow wm:cashFlowOfInvestor ?investor ;
              wm:amount ?cashFlowAmount .
  }

  OPTIONAL {
    ?holding wm:heldByInvestor ?investor ;
             wm:cost ?cost ;
             wm:currentValue ?currentValue .
    BIND((xsd:decimal(?currentValue) - xsd:decimal(?cost)) AS ?holdingGain)
  }

  OPTIONAL {
    ?rebalance wm:rebalancingActionOfInvestor ?investor ;
               wm:amount ?rebalanceAmount .
  }

  FILTER(
    EXISTS { ?cashFlow wm:cashFlowOfInvestor ?investor } &&
    EXISTS { ?holding wm:heldByInvestor ?investor ; wm:cost ?cost ; wm:currentValue ?currentValue } &&
    EXISTS { ?rebalance wm:rebalancingActionOfInvestor ?investor }
  )
}
GROUP BY ?investorId
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?totalHoldingValue), 2) AS ?avg_total_holding_value)
  (ROUND(AVG(?avgHoldingReturn), 2) AS ?avg_holding_return)
  (ROUND(AVG(?totalSectorInvestment), 2) AS ?avg_sector_investment)
  (ROUND(AVG(?avgScenarioShift), 2) AS ?avg_scenario_shift)
  (COUNT(DISTINCT ?investor) AS ?n_investors)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?rt .
  ?rt rdfs:label ?riskTolerance .

  OPTIONAL {
    ?holding wm:heldByInvestor ?investor ;
             wm:cost ?cost ;
             wm:currentValue ?currentValue .
    BIND(xsd:decimal(?currentValue) AS ?cv)
    BIND(xsd:decimal(?cost) AS ?c)
    FILTER (?c > 0 && ?cv >= 0)
  }

  OPTIONAL {
    ?sectorAlloc wm:allocationOfInvestor ?investor ;
                 wm:totalInvestment ?totalInv .
    BIND(xsd:decimal(?totalInv) AS ?ti)
  }

  OPTIONAL {
    ?scenarioRebal wm:scenarioRebalancingOfInvestor ?investor ;
                   wm:currentAllocationPct ?currAlloc ;
                   wm:newAllocationPct ?newAlloc .
    BIND(xsd:decimal(?newAlloc) - xsd:decimal(?currAlloc) AS ?shift)
  }

  BIND(IF(BOUND(?holding), ?cv, 0) AS ?holdingValue)
  BIND(IF(BOUND(?holding) && ?c > 0, ((?cv - ?c) / ?c) * 100, 0) AS ?returnPct)

  {
    SELECT ?investor
           (SUM(?holdingValue) AS ?totalHoldingValue)
           (AVG(?returnPct) AS ?avgHoldingReturn)
    WHERE {
      ?holding wm:heldByInvestor ?investor ;
               wm:cost ?cost ;
               wm:currentValue ?currentValue .
      BIND(xsd:decimal(?currentValue) AS ?cv)
      BIND(xsd:decimal(?cost) AS ?c)
      FILTER (?c > 0 && ?cv >= 0)
      BIND(?cv AS ?holdingValue)
      BIND((?cv - ?c) / ?c * 100 AS ?returnPct)
    }
    GROUP BY ?investor
  }

  {
    SELECT ?investor (SUM(?ti) AS ?totalSectorInvestment)
    WHERE {
      ?sectorAlloc wm:allocationOfInvestor ?investor ;
                   wm:totalInvestment ?totalInv .
      BIND(xsd:decimal(?totalInv) AS ?ti)
    }
    GROUP BY ?investor
  }

  {
    SELECT ?investor (AVG(?shift) AS ?avgScenarioShift)
    WHERE {
      ?scenarioRebal wm:scenarioRebalancingOfInvestor ?investor ;
                     wm:currentAllocationPct ?currAlloc ;
                     wm:newAllocationPct ?newAlloc .
      BIND(xsd:decimal(?newAlloc) - xsd:decimal(?currAlloc) AS ?shift)
    }
    GROUP BY ?investor
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?investorId
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId .

  # Net Cash Flow
  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(?cfAmount)) AS ?netCashFlow)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:cashFlowOfInvestor ?investor ;
          wm:amount ?cfAmount .
    }
    GROUP BY ?investor
  }

  # Total Holding Gain
  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(?gain)) AS ?totalGain)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:cost ?cost ;
               wm:currentValue ?currentValue .
      BIND((xsd:decimal(?currentValue) - xsd:decimal(?cost)) AS ?gain)
      FILTER(?cost != "" && ?currentValue != "")
    }
    GROUP BY ?investor
  }

  # Average Goal Shortfall
  OPTIONAL {
    SELECT ?investor (AVG(xsd:decimal(?shortfall)) AS ?avgShortfall)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?investor ;
            wm:shortfall ?shortfall .
    }
    GROUP BY ?investor
  }

  # Ensure all components exist
  FILTER(BOUND(?netCashFlow) && BOUND(?totalGain) && BOUND(?avgShortfall))

  # Composite Score Calculation
  BIND((?netCashFlow + ?totalGain - ?avgShortfall) AS ?compositeScore)
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?investorId
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId .

  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?netCashFlow)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:cashFlowOfInvestor ?investor ;
          wm:amount ?amount ;
          wm:type ?type .
      BIND(IF(?type IN ("SIP", "Lump Sum", "Deposit"), -xsd:decimal(?amount), xsd:decimal(?amount)) AS ?signedAmount)
    }
    GROUP BY ?investorId
  }

  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?totalRebalanceAmount)
    WHERE {
      ?ra a wm:RebalancingAction ;
          wm:rebalancingActionOfInvestor ?investor ;
          wm:amount ?amount .
    }
    GROUP BY ?investorId
  }

  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?totalInvestment)) AS ?totalSectorInvestment)
    WHERE {
      ?sa a wm:SectorAllocation ;
          wm:allocationOfInvestor ?investor ;
          wm:totalInvestment ?totalInvestment .
    }
    GROUP BY ?investorId
  }

  BIND(COALESCE(?netCashFlow, 0) + COALESCE(?totalRebalanceAmount, 0) + COALESCE(?totalSectorInvestment, 0) AS ?compositeScore)
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?investorId
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:hasCashFlow ?cashFlow ;
            wm:hasRebalancingAction ?rebalancingAction ;
            wm:hasInvestmentGoal ?investmentGoal .

  ?cashFlow wm:amount ?cashFlowAmount ;
            wm:type ?cashFlowType .

  ?rebalancingAction wm:amount ?rebalancingAmount .

  ?investmentGoal wm:shortfall ?goalShortfall .

  BIND(IF(?cashFlowType IN ("SIP", "Lump Sum", "Deposit"), -xsd:decimal(?cashFlowAmount), xsd:decimal(?cashFlowAmount)) AS ?netCashFlowComponent)
  BIND(xsd:decimal(?rebalancingAmount) AS ?rebalancingComponent)
  BIND(-xsd:decimal(?goalShortfall) AS ?shortfallComponent)
}
GROUP BY ?investorId
ORDER BY DESC(SUM(?netCashFlowComponent) + SUM(?rebalancingComponent) + AVG(?shortfallComponent)) ?investorId
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId
           (100 * (?netCashFlowNorm + ?totalRebalanceAmountNorm + ?riskScoreNorm) / 3 AS ?compositeScore)
    WHERE {
      {
        SELECT ?investorId
               ((?netCashFlow - MIN(?netCashFlow) OVER()) / (MAX(?netCashFlow) OVER() - MIN(?netCashFlow) OVER()) AS ?netCashFlowNorm)
               ((?totalRebalanceAmount - MIN(?totalRebalanceAmount) OVER()) / (MAX(?totalRebalanceAmount) OVER() - MIN(?totalRebalanceAmount) OVER()) AS ?totalRebalanceAmountNorm)
               ((?riskScore - MIN(?riskScore) OVER()) / (MAX(?riskScore) OVER() - MIN(?riskScore) OVER()) AS ?riskScoreNorm)
        WHERE {
          {
            SELECT ?investorId
                   (SUM(COALESCE(?inflows, 0) - COALESCE(?outflows, 0)) AS ?netCashFlow)
            WHERE {
              OPTIONAL {
                ?cashFlow wm:cashFlowOfInvestor ?investor .
                ?investor wm:investorId ?investorId .
                ?cashFlow wm:type "Inflow" .
                ?cashFlow wm:amount ?inflowAmount .
                BIND(xsd:decimal(?inflowAmount) AS ?inflows)
              }
              OPTIONAL {
                ?cashFlow2 wm:cashFlowOfInvestor ?investor .
                ?investor wm:investorId ?investorId .
                ?cashFlow2 wm:type "Outflow" .
                ?cashFlow2 wm:amount ?outflowAmount .
                BIND(xsd:decimal(?outflowAmount) AS ?outflows)
              }
            }
            GROUP BY ?investorId
          }
          {
            SELECT ?investorId
                   (SUM(xsd:decimal(?amount)) AS ?totalRebalanceAmount)
            WHERE {
              ?rebalancingAction wm:rebalancingActionOfInvestor ?investor .
              ?investor wm:investorId ?investorId .
              ?rebalancingAction wm:amount ?amount .
            }
            GROUP BY ?investorId
          }
          {
            SELECT ?investorId
                   (xsd:decimal(?riskScoreStr) AS ?riskScore)
            WHERE {
              ?portfolioHealth wm:healthOfInvestor ?investor .
              ?investor wm:investorId ?investorId .
              ?portfolioHealth wm:riskScore ?riskScoreStr .
            }
          }
        }
        GROUP BY ?investorId ?netCashFlow ?totalRebalanceAmount ?riskScore
      }
    }
  }
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
WITH (
  SELECT 
    ?investorId,
    (?netCashFlow - MIN(?netCashFlow) OVER()) / (MAX(?netCashFlow) OVER() - MIN(?netCashFlow) OVER()) AS ?normNetCashFlow,
    (?totalSectorInvestment - MIN(?totalSectorInvestment) OVER()) / (MAX(?totalSectorInvestment) OVER() - MIN(?totalSectorInvestment) OVER()) AS ?normTotalSectorInvestment,
    (?totalAllocationShift - MIN(?totalAllocationShift) OVER()) / (MAX(?totalAllocationShift) OVER() - MIN(?totalAllocationShift) OVER()) AS ?normTotalAllocationShift
  WHERE {
    {
      SELECT 
        ?investorId
        (SUM(IF(?cfType IN ("SIP", "Lump Sum", "Deposit"), -xsd:decimal(?cfAmount), xsd:decimal(?cfAmount))) AS ?netCashFlow)
      WHERE {
        ?cashFlow wm:cashFlowOfInvestor ?investor ;
                  wm:investorId ?investorId ;
                  wm:amount ?cfAmount ;
                  wm:hasCashFlowType ?cfTypeNode .
        ?cfTypeNode rdfs:label ?cfType .
      }
      GROUP BY ?investorId
    }
    {
      SELECT 
        ?investorId
        (SUM(xsd:decimal(?totalInvestment)) AS ?totalSectorInvestment)
      WHERE {
        ?sectorAlloc wm:allocationOfInvestor ?investor ;
                     wm:investorId ?investorId ;
                     wm:totalInvestment ?totalInvestment .
      }
      GROUP BY ?investorId
    }
    {
      SELECT 
        ?investorId
        (SUM(xsd:decimal(?newAlloc) - xsd:decimal(?currentAlloc)) AS ?totalAllocationShift)
      WHERE {
        ?scenarioRebalancing wm:scenarioRebalancingOfInvestor ?investor ;
                             wm:investorId ?investorId ;
                             wm:newAllocationPct ?newAlloc ;
                             wm:currentAllocationPct ?currentAlloc .
      }
      GROUP BY ?investorId
    }
    FILTER(BOUND(?netCashFlow) && BOUND(?totalSectorInvestment) && BOUND(?totalAllocationShift))
  }
)
SELECT 
  ?investorId
  ((?normNetCashFlow + ?normTotalSectorInvestment + ?normTotalAllocationShift) / 3 * 100 AS ?compositeScore)
WHERE {
  INCLUDE %NormalizedData
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
WITH (
  SELECT 
    cf.investorId,
    SUM(CASE WHEN cf.type IN ('SIP', 'Lump Sum', 'Deposit') THEN -cf.amount 
             WHEN cf.type IN ('Redemption', 'Withdrawal') THEN cf.amount END) AS net_cash_flow,
    SUM(sa.totalInvestment) AS total_sector_investment,
    MAX(ph.riskScore) AS risk_score
  WHERE {
    ?cf a wm:CashFlow ;
        wm:investorId ?investorId ;
        wm:type ?type ;
        wm:amount ?amount .

    ?sa a wm:SectorAllocation ;
         wm:investorId ?investorId ;
         wm:totalInvestment ?totalInvestment .

    ?ph a wm:PortfolioHealth ;
        wm:investorId ?investorId ;
        wm:riskScore ?riskScore .
  }
  GROUP BY cf.investorId
) AS combined_scores

SELECT 
  ?investorId
  ((100 * ((xsd:float(?net_cash_flow) - MIN(xsd:float(?net_cash_flow)) OVER()) / 
           (MAX(xsd:float(?net_cash_flow)) OVER() - MIN(xsd:float(?net_cash_flow)) OVER())) +
    100 * ((xsd:float(?total_sector_investment) - MIN(xsd:float(?total_sector_investment)) OVER()) / 
           (MAX(xsd:float(?total_sector_investment)) OVER() - MIN(xsd:float(?total_sector_investment)) OVER())) +
    100 * ((xsd:float(?risk_score) - MIN(xsd:float(?risk_score)) OVER()) / 
           (MAX(xsd:float(?risk_score)) OVER() - MIN(xsd:float(?risk_score)) OVER()))) / 3) AS composite_score
WHERE {
  ?combined_scores wm:investorId ?investorId ;
                   wm:net_cash_flow ?net_cash_flow ;
                   wm:total_sector_investment ?total_sector_investment ;
                   wm:risk_score ?risk_score .
}
ORDER BY DESC(?composite_score) ?investorId
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId
           (100 * (?netCashFlowNorm + ?allocationShiftNorm + ?riskScoreNorm) / 3 AS ?compositeScore)
    WHERE {
      {
        SELECT ?investorId
               ((?netCashFlow - MIN(?netCashFlow) OVER()) / (MAX(?netCashFlow) OVER() - MIN(?netCashFlow) OVER()) AS ?netCashFlowNorm)
               ((?allocationShift - MIN(?allocationShift) OVER()) / (MAX(?allocationShift) OVER() - MIN(?allocationShift) OVER()) AS ?allocationShiftNorm)
               ((?riskScore - MIN(?riskScore) OVER()) / (MAX(?riskScore) OVER() - MIN(?riskScore) OVER()) AS ?riskScoreNorm)
        WHERE {
          {
            SELECT ?investorId
                   (SUM(COALESCE(?cashIn, 0) - COALESCE(?cashOut, 0)) AS ?netCashFlow)
            WHERE {
              OPTIONAL {
                ?cashFlow wm:cashFlowOfInvestor ?investor .
                ?investor wm:investorId ?investorId .
                ?cashFlow wm:type "Inflow" .
                BIND(xsd:decimal(?cashFlow/wm:amount) AS ?cashIn)
              }
              OPTIONAL {
                ?cashFlow2 wm:cashFlowOfInvestor ?investor2 .
                ?investor2 wm:investorId ?investorId .
                ?cashFlow2 wm:type "Outflow" .
                BIND(xsd:decimal(?cashFlow2/wm:amount) AS ?cashOut)
              }
            }
            GROUP BY ?investorId
          }
          {
            SELECT ?investorId
                   (SUM(xsd:decimal(?scenario/newAllocationPct) - xsd:decimal(?scenario/currentAllocationPct)) AS ?allocationShift)
            WHERE {
              ?scenario wm:scenarioRebalancingOfInvestor ?investor .
              ?investor wm:investorId ?investorId .
            }
            GROUP BY ?investorId
          }
          {
            SELECT ?investorId ?riskScore
            WHERE {
              ?health wm:healthOfInvestor ?investor .
              ?investor wm:investorId ?investorId .
              BIND(xsd:decimal(?health/wm:riskScore) AS ?riskScore)
            }
          }
        }
        GROUP BY ?investorId ?netCashFlow ?allocationShift ?riskScore
      }
    }
  }
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?investorId
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:hasCashFlow ?cashFlow ;
            wm:hasSectorAllocation ?sectorAlloc ;
            wm:hasInvestmentGoal ?goal .

  ?cashFlow wm:amount ?cashFlowAmount ;
            wm:type ?cashFlowType .

  ?sectorAlloc wm:totalInvestment ?totalSectorInvestment .

  ?goal wm:shortfall ?goalShortfall .

  BIND(IF(?cashFlowType IN ("SIP", "Lump Sum", "Deposit"), -xsd:decimal(?cashFlowAmount), xsd:decimal(?cashFlowAmount)) AS ?netCashFlow)

  {
    SELECT ?investorId
           (SUM(?netCashFlow) AS ?netCF)
           (SUM(xsd:decimal(?totalSectorInvestment)) AS ?totalSecInv)
           (AVG(xsd:decimal(?goalShortfall)) AS ?avgShortfall)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasCashFlow ?cashFlow ;
                wm:hasSectorAllocation ?sectorAlloc ;
                wm:hasInvestmentGoal ?goal .

      ?cashFlow wm:amount ?cashFlowAmount ;
                wm:type ?cashFlowType .

      ?sectorAlloc wm:totalInvestment ?totalSectorInvestment .

      ?goal wm:shortfall ?goalShortfall .

      BIND(IF(?cashFlowType IN ("SIP", "Lump Sum", "Deposit"), -xsd:decimal(?cashFlowAmount), xsd:decimal(?cashFlowAmount)) AS ?netCashFlow)
    }
    GROUP BY ?investorId
    HAVING (COUNT(?cashFlow) > 0 && COUNT(?sectorAlloc) > 0 && COUNT(?goal) > 0)
  }

  BIND((?netCF + ?totalSecInv - ?avgShortfall) AS ?compositeScore)
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId
           (100 * (?netCashFlowNorm + ?riskScoreNorm + (1 - ?avgShortfallNorm)) / 3 AS ?compositeScore)
    WHERE {
      {
        SELECT ?investorId
               ((?netCashFlow - MIN(?netCashFlow) OVER()) / (MAX(?netCashFlow) OVER() - MIN(?netCashFlow) OVER()) AS ?netCashFlowNorm)
               ((?riskScore - MIN(?riskScore) OVER()) / (MAX(?riskScore) OVER() - MIN(?riskScore) OVER()) AS ?riskScoreNorm)
               ((?avgShortfall - MIN(?avgShortfall) OVER()) / (MAX(?avgShortfall) OVER() - MIN(?avgShortfall) OVER()) AS ?avgShortfallNorm)
        WHERE {
          {
            SELECT ?investorId
                   (SUM(IF(?type_ = "Inflow", -xsd:decimal(?amount_), xsd:decimal(?amount_))) AS ?netCashFlow)
                   (xsd:decimal(?riskScore_) AS ?riskScore)
                   (AVG(xsd:decimal(?shortfall)) AS ?avgShortfall)
            WHERE {
              ?cashFlow wm:cashFlowOfInvestor ?investor .
              ?investor wm:investorId ?investorId .
              ?cashFlow wm:amount ?amount_ .
              ?cashFlow wm:type ?type_ .

              ?health wm:healthOfInvestor ?investor ;
                      wm:riskScore ?riskScore_ .

              ?goal wm:belongsToInvestor ?investor ;
                    wm:shortfall ?shortfall .
            }
            GROUP BY ?investorId ?riskScore_
            HAVING (COUNT(*) > 0)
          }
        }
      }
    }
  }
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?netCashFlow)) AS ?avg_net_cash_flow)
  (ROUND(AVG(?avgCashFlowAmount)) AS ?avg_cash_flow_amount)
  (ROUND(AVG(?totalHoldingValue)) AS ?avg_total_holding_value)
  (ROUND(AVG(?totalRebalanceAmount)) AS ?avg_total_rebalance_amount)
  (ROUND(AVG(?totalSectorInvestment)) AS ?avg_total_sector_investment)
  (COUNT(DISTINCT ?investor) AS ?n_investors)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?rt .
  ?rt rdfs:label ?riskTolerance .

  OPTIONAL {
    ?cf a wm:CashFlow ;
        wm:cashFlowOfInvestor ?investor ;
        wm:amount ?cfAmount .
  }
  BIND(COALESCE(SUM(xsd:decimal(?cfAmount)), 0) AS ?netCashFlow)
  BIND(COALESCE(AVG(xsd:decimal(?cfAmount)), 0) AS ?avgCashFlowAmount)

  OPTIONAL {
    ?ph a wm:PortfolioHolding ;
        wm:heldByInvestor ?investor ;
        wm:currentValue ?phCurrentValue .
  }
  BIND(COALESCE(SUM(xsd:decimal(?phCurrentValue)), 0) AS ?totalHoldingValue)

  OPTIONAL {
    ?ra a wm:RebalancingAction ;
        wm:rebalancingActionOfInvestor ?investor ;
        wm:amount ?raAmount .
  }
  BIND(COALESCE(SUM(xsd:decimal(?raAmount)), 0) AS ?totalRebalanceAmount)

  OPTIONAL {
    ?sa a wm:SectorAllocation ;
        wm:allocationOfInvestor ?investor ;
        wm:totalInvestment ?saTotalInvestment .
  }
  BIND(COALESCE(SUM(xsd:decimal(?saTotalInvestment)), 0) AS ?totalSectorInvestment)

}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId
           ((100 * (?normNetCashFlow + ?normAllocShift + (1 - ?normAvgShortfall)) / 3) AS ?compositeScore)
    WHERE {
      {
        SELECT ?investorId
               ((?netCashFlow - ?minNetCashFlow) / (?maxNetCashFlow - ?minNetCashFlow) AS ?normNetCashFlow)
               ((?allocShift - ?minAllocShift) / (?maxAllocShift - ?minAllocShift) AS ?normAllocShift)
               ((?avgShortfall - ?minAvgShortfall) / (?maxAvgShortfall - ?minAvgShortfall) AS ?normAvgShortfall)
        WHERE {
          {
            SELECT ?investorId
                   (SUM(xsd:decimal(?cfAmount)) AS ?netCashFlow)
            WHERE {
              ?cashFlow a wm:CashFlow ;
                        wm:cashFlowOfInvestor ?investor ;
                        wm:amount ?cfAmount ;
                        wm:type ?cfType .
              ?investor wm:investorId ?investorId .
              FILTER(?cfType IN ("SIP", "Lump Sum", "Deposit"))
            }
            GROUP BY ?investorId
          }
          {
            SELECT ?investorId
                   (SUM(xsd:decimal(?newAlloc) - xsd:decimal(?currAlloc)) AS ?allocShift)
            WHERE {
              ?scenarioRebalancing a wm:ScenarioRebalancing ;
                                   wm:scenarioRebalancingOfInvestor ?investor ;
                                   wm:currentAllocationPct ?currAlloc ;
                                   wm:newAllocationPct ?newAlloc .
              ?investor wm:investorId ?investorId .
            }
            GROUP BY ?investorId
          }
          {
            SELECT ?investorId
                   (AVG(xsd:decimal(?shortfall)) AS ?avgShortfall)
            WHERE {
              ?goal a wm:InvestmentGoal ;
                    wm:belongsToInvestor ?investor ;
                    wm:shortfall ?shortfall .
              ?investor wm:investorId ?investorId .
            }
            GROUP BY ?investorId
          }
          BIND(
            IF(?netCashFlow != ?netCashFlow, 0, ?netCashFlow) AS ?safeNetCashFlow
          )
          BIND(
            IF(?allocShift != ?allocShift, 0, ?allocShift) AS ?safeAllocShift
          )
          BIND(
            IF(?avgShortfall != ?avgShortfall, 0, ?avgShortfall) AS ?safeAvgShortfall
          )

          {
            SELECT (MIN(?safeNetCashFlow) AS ?minNetCashFlow)
                   (MAX(?safeNetCashFlow) AS ?maxNetCashFlow)
            WHERE {
              {
                SELECT ?investorId
                       (SUM(xsd:decimal(?cfAmount)) AS ?netCashFlow)
                WHERE {
                  ?cashFlow a wm:CashFlow ;
                            wm:cashFlowOfInvestor ?investor ;
                            wm:amount ?cfAmount ;
                            wm:type ?cfType .
                  ?investor wm:investorId ?investorId .
                  FILTER(?cfType IN ("SIP", "Lump Sum", "Deposit"))
                }
                GROUP BY ?investorId
              }
              BIND(
                IF(?netCashFlow != ?netCashFlow, 0, ?netCashFlow) AS ?safeNetCashFlow
              )
            }
          }

          {
            SELECT (MIN(?safeAllocShift) AS ?minAllocShift)
                   (MAX(?safeAllocShift) AS ?maxAllocShift)
            WHERE {
              {
                SELECT ?investorId
                       (SUM(xsd:decimal(?newAlloc) - xsd:decimal(?currAlloc)) AS ?allocShift)
                WHERE {
                  ?scenarioRebalancing a wm:ScenarioRebalancing ;
                                       wm:scenarioRebalancingOfInvestor ?investor ;
                                       wm:currentAllocationPct ?currAlloc ;
                                       wm:newAllocationPct ?newAlloc .
                  ?investor wm:investorId ?investorId .
                }
                GROUP BY ?investorId
              }
              BIND(
                IF(?allocShift != ?allocShift, 0, ?allocShift) AS ?safeAllocShift
              )
            }
          }

          {
            SELECT (MIN(?safeAvgShortfall) AS ?minAvgShortfall)
                   (MAX(?safeAvgShortfall) AS ?maxAvgShortfall)
            WHERE {
              {
                SELECT ?investorId
                       (AVG(xsd:decimal(?shortfall)) AS ?avgShortfall)
                WHERE {
                  ?goal a wm:InvestmentGoal ;
                        wm:belongsToInvestor ?investor ;
                        wm:shortfall ?shortfall .
                  ?investor wm:investorId ?investorId .
                }
                GROUP BY ?investorId
              }
              BIND(
                IF(?avgShortfall != ?avgShortfall, 0, ?avgShortfall) AS ?safeAvgShortfall
              )
            }
          }
        }
      }
    }
  }
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?netCashFlow)) AS ?avg_net_cash_flow)
  (ROUND(AVG(?avgCashFlowAmount)) AS ?avg_cash_flow_amount)
  (ROUND(AVG(?totalHoldingValue)) AS ?avg_total_holding_value)
  (ROUND(AVG(?totalRebalanceAmount)) AS ?avg_total_rebalance_amount)
  (ROUND(AVG(?allocationShift)) AS ?avg_scenario_allocation_shift)
  (COUNT(DISTINCT ?investorId) AS ?n_investors)
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:hasRiskTolerance ?rt .
  ?rt rdfs:label ?riskTolerance .

  OPTIONAL {
    SELECT ?investorId (SUM(IF(?isInflow, -?amount, ?amount)) AS ?netCashFlow)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:cashFlowOfInvestor ?inv ;
          wm:investorId ?investorId ;
          wm:amount ?amtStr ;
          wm:type ?type .
      BIND(xsd:decimal(?amtStr) AS ?amount)
      VALUES (?type ?isInflow) {
        ("SIP" true)
        ("Lump Sum" true)
        ("Deposit" true)
        ("Redemption" false)
        ("Withdrawal" false)
      }
    } GROUP BY ?investorId
  }

  OPTIONAL {
    SELECT ?investorId (AVG(?amount) AS ?avgCashFlowAmount)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:cashFlowOfInvestor ?inv ;
          wm:investorId ?investorId ;
          wm:amount ?amtStr .
      BIND(xsd:decimal(?amtStr) AS ?amount)
    } GROUP BY ?investorId
  }

  OPTIONAL {
    SELECT ?investorId (SUM(?value) AS ?totalHoldingValue)
    WHERE {
      ?ph a wm:PortfolioHolding ;
          wm:heldByInvestor ?inv ;
          wm:investorId ?investorId ;
          wm:currentValue ?valStr .
      BIND(xsd:decimal(?valStr) AS ?value)
    } GROUP BY ?investorId
  }

  OPTIONAL {
    SELECT ?investorId (SUM(?amt) AS ?totalRebalanceAmount)
    WHERE {
      ?ra a wm:RebalancingAction ;
          wm:rebalancingActionOfInvestor ?inv ;
          wm:investorId ?investorId ;
          wm:amount ?amtStr .
      BIND(xsd:decimal(?amtStr) AS ?amt)
    } GROUP BY ?investorId
  }

  OPTIONAL {
    SELECT ?investorId (AVG(?shift) AS ?allocationShift)
    WHERE {
      ?sr a wm:ScenarioRebalancing ;
          wm:scenarioRebalancingOfInvestor ?inv ;
          wm:investorId ?investorId ;
          wm:currentAllocationPct ?currStr ;
          wm:newAllocationPct ?newStr .
      BIND(xsd:decimal(?newStr) - xsd:decimal(?currStr) AS ?shift)
    } GROUP BY ?investorId
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?netCashFlow)) AS ?avg_net_cash_flow)
  (ROUND(AVG(?avgCashFlowAmount)) AS ?avg_cash_flow_amount)
  (ROUND(AVG(?totalHoldingValue)) AS ?avg_total_holding_value)
  (ROUND(AVG(?totalRebalanceAmount)) AS ?avg_total_rebalance_amount)
  (ROUND(AVG(?riskScore)) AS ?avg_risk_score)
  (COUNT(DISTINCT ?investor) AS ?n_investors)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?rt .
  ?rt rdfs:label ?riskTolerance .

  OPTIONAL {
    ?cashFlow wm:cashFlowOfInvestor ?investor ;
              wm:amount ?cfAmount .
    BIND(xsd:decimal(?cfAmount) AS ?amount)
  }
  BIND(IF(BOUND(?amount), ?amount, 0) AS ?safeAmount)

  OPTIONAL {
    ?holding wm:heldByInvestor ?investor ;
             wm:currentValue ?hv .
    BIND(xsd:decimal(?hv) AS ?holdingValue)
  }
  BIND(IF(BOUND(?holdingValue), ?holdingValue, 0) AS ?safeHoldingValue)

  OPTIONAL {
    ?rebalancing wm:rebalancingActionOfInvestor ?investor ;
                 wm:amount ?raAmount .
    BIND(xsd:decimal(?raAmount) AS ?rebalAmount)
  }
  BIND(IF(BOUND(?rebalAmount), ?rebalAmount, 0) AS ?safeRebalAmount)

  OPTIONAL {
    ?health wm:healthOfInvestor ?investor ;
            wm:riskScore ?rs .
    BIND(xsd:decimal(?rs) AS ?riskScoreValue)
  }
  BIND(IF(BOUND(?riskScoreValue), ?riskScoreValue, 0) AS ?safeRiskScore)

  {
    SELECT ?investor
           (SUM(IF(?cfTypeLabel IN ("SIP", "Lump Sum", "Deposit"), -?safeAmount, ?safeAmount)) AS ?netCashFlow)
           (AVG(?safeAmount) AS ?avgCashFlowAmount)
    WHERE {
      OPTIONAL {
        ?cashFlow wm:cashFlowOfInvestor ?investor ;
                  wm:amount ?cfAmount ;
                  wm:hasCashFlowType ?cfType .
        ?cfType rdfs:label ?cfTypeLabel .
        BIND(xsd:decimal(?cfAmount) AS ?safeAmount)
      }
    }
    GROUP BY ?investor
  }

  {
    SELECT ?investor (SUM(?safeHoldingValue) AS ?totalHoldingValue)
    WHERE {
      OPTIONAL {
        ?holding wm:heldByInvestor ?investor ;
                 wm:currentValue ?hv .
        BIND(xsd:decimal(?hv) AS ?safeHoldingValue)
      }
    }
    GROUP BY ?investor
  }

  {
    SELECT ?investor (SUM(?safeRebalAmount) AS ?totalRebalanceAmount)
    WHERE {
      OPTIONAL {
        ?rebalancing wm:rebalancingActionOfInvestor ?investor ;
                     wm:amount ?raAmount .
        BIND(xsd:decimal(?raAmount) AS ?safeRebalAmount)
      }
    }
    GROUP BY ?investor
  }

  {
    SELECT ?investor (AVG(?safeRiskScore) AS ?riskScore)
    WHERE {
      OPTIONAL {
        ?health wm:healthOfInvestor ?investor ;
                wm:riskScore ?rs .
        BIND(xsd:decimal(?rs) AS ?safeRiskScore)
      }
    }
    GROUP BY ?investor
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?netCashFlow)) AS ?avg_net_cash_flow)
  (ROUND(AVG(?avgCashFlowAmount)) AS ?avg_cash_flow_amount)
  (ROUND(AVG(?totalHoldingValue)) AS ?avg_total_holding_value)
  (ROUND(AVG(?totalSectorInvestment)) AS ?avg_total_sector_investment)
  (ROUND(AVG(?allocationShift)) AS ?avg_scenario_allocation_shift)
WHERE {
  {
    SELECT 
      ?investor 
      (SUM(IF(?cfType IN ("SIP", "Lump Sum", "Deposit"), -xsd:decimal(?cfAmount), xsd:decimal(?cfAmount))) AS ?netCashFlow)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?cfAmount ;
                wm:hasCashFlowType ?cfTypeNode .
      ?cfTypeNode rdfs:label ?cfType .
    }
    GROUP BY ?investor
  }

  {
    SELECT 
      ?investor 
      (AVG(xsd:decimal(?cfAmount)) AS ?avgCashFlowAmount)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?cfAmount .
    }
    GROUP BY ?investor
  }

  {
    SELECT 
      ?investor 
      (SUM(xsd:decimal(?currentValue)) AS ?totalHoldingValue)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:currentValue ?currentValue .
    }
    GROUP BY ?investor
  }

  {
    SELECT 
      ?investor 
      (SUM(xsd:decimal(?allocationPct)) AS ?totalSectorInvestment)
    WHERE {
      ?allocation a wm:SectorAllocation ;
                  wm:allocationOfInvestor ?investor ;
                  wm:allocationPct ?allocationPct .
    }
    GROUP BY ?investor
  }

  {
    SELECT 
      ?investor 
      (AVG(xsd:decimal(?newAllocationPct) - xsd:decimal(?currentAllocationPct)) AS ?allocationShift)
    WHERE {
      ?scenarioRebalancing a wm:ScenarioRebalancing ;
                           wm:scenarioRebalancingOfInvestor ?investor ;
                           wm:newAllocationPct ?newAllocationPct ;
                           wm:currentAllocationPct ?currentAllocationPct .
    }
    GROUP BY ?investor
  }

  ?investor wm:hasRiskTolerance ?rt .
  ?rt rdfs:label ?riskTolerance .
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?netCashFlow)) AS ?avg_net_cash_flow)
  (ROUND(AVG(?avgCashFlowAmount)) AS ?avg_cash_flow_amount)
  (ROUND(AVG(?totalHoldingValue)) AS ?avg_total_holding_value)
  (ROUND(AVG(?totalRebalanceAmount)) AS ?avg_total_rebalance_amount)
  (ROUND(AVG(?goalProgress)) AS ?avg_goal_progress)
  (COUNT(DISTINCT ?investorId) AS ?n_investors)
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:hasRiskTolerance ?rt .
  ?rt rdfs:label ?riskTolerance .

  OPTIONAL {
    ?cashFlow wm:cashFlowOfInvestor ?investor ;
              wm:amount ?cfAmount .
    BIND(xsd:decimal(?cfAmount) AS ?amountNum)
  }
  OPTIONAL {
    ?holding wm:heldByInvestor ?investor ;
             wm:currentValue ?hv .
    BIND(xsd:decimal(?hv) AS ?holdingValue)
  }
  OPTIONAL {
    ?rebalancing wm:rebalancingActionOfInvestor ?investor ;
                 wm:amount ?ra .
    BIND(xsd:decimal(?ra) AS ?rebalanceAmount)
  }
  OPTIONAL {
    ?goal wm:belongsToInvestor ?investor ;
          wm:progressPct ?gp .
    BIND(xsd:decimal(?gp) AS ?progressPctNum)
  }

  {
    SELECT ?investorId
           (SUM(IF(?cfTypeLabel IN ("SIP", "Lump Sum", "Deposit"), -?amountNum, ?amountNum)) AS ?netCashFlow)
    WHERE {
      ?investor wm:investorId ?investorId .
      OPTIONAL {
        ?cashFlow wm:cashFlowOfInvestor ?investor ;
                  wm:amount ?cfAmount ;
                  wm:hasCashFlowType ?cft .
        ?cft rdfs:label ?cfTypeLabel .
        BIND(xsd:decimal(?cfAmount) AS ?amountNum)
      }
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId (AVG(?amountNum) AS ?avgCashFlowAmount)
    WHERE {
      ?investor wm:investorId ?investorId .
      OPTIONAL {
        ?cashFlow wm:cashFlowOfInvestor ?investor ;
                  wm:amount ?cfAmount .
        BIND(xsd:decimal(?cfAmount) AS ?amountNum)
      }
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId (SUM(?holdingValue) AS ?totalHoldingValue)
    WHERE {
      ?investor wm:investorId ?investorId .
      OPTIONAL {
        ?holding wm:heldByInvestor ?investor ;
                 wm:currentValue ?hv .
        BIND(xsd:decimal(?hv) AS ?holdingValue)
      }
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId (SUM(?rebalanceAmount) AS ?totalRebalanceAmount)
    WHERE {
      ?investor wm:investorId ?investorId .
      OPTIONAL {
        ?rebalancing wm:rebalancingActionOfInvestor ?investor ;
                     wm:amount ?ra .
        BIND(xsd:decimal(?ra) AS ?rebalanceAmount)
      }
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId (AVG(?progressPctNum) AS ?goalProgress)
    WHERE {
      ?investor wm:investorId ?investorId .
      OPTIONAL {
        ?goal wm:belongsToInvestor ?investor ;
              wm:progressPct ?gp .
        BIND(xsd:decimal(?gp) AS ?progressPctNum)
      }
    }
    GROUP BY ?investorId
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?netCashFlow)) AS ?avg_net_cash_flow)
  (ROUND(AVG(?avgCashFlowAmount)) AS ?avg_cash_flow_amount)
  (ROUND(AVG(?totalHoldingValue)) AS ?avg_total_holding_value)
  (ROUND(AVG(?totalSectorInvestment)) AS ?avg_total_sector_investment)
  (ROUND(AVG(?riskScore)) AS ?avg_risk_score)
  (COUNT(DISTINCT ?investor) AS ?n_investors)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?rt .
  ?rt rdfs:label ?riskTolerance .

  OPTIONAL {
    ?cashFlow wm:cashFlowOfInvestor ?investor ;
              wm:amount ?cfAmount .
  }
  BIND(COALESCE(SUM(xsd:decimal(?cfAmount)), 0) AS ?netCashFlow)

  OPTIONAL {
    ?cashFlow2 wm:cashFlowOfInvestor ?investor ;
               wm:amount ?cfAmount2 .
  }
  BIND(COALESCE(AVG(xsd:decimal(?cfAmount2)), 0) AS ?avgCashFlowAmount)

  OPTIONAL {
    ?holding wm:heldByInvestor ?investor ;
             wm:currentValue ?currentValue .
  }
  BIND(COALESCE(SUM(xsd:decimal(?currentValue)), 0) AS ?totalHoldingValue)

  OPTIONAL {
    ?sectorAlloc wm:allocationOfInvestor ?investor ;
                 wm:totalInvestment ?totalInvestment .
  }
  BIND(COALESCE(SUM(xsd:decimal(?totalInvestment)), 0) AS ?totalSectorInvestment)

  OPTIONAL {
    ?health wm:healthOfInvestor ?investor ;
            wm:riskScore ?riskScoreRaw .
  }
  BIND(COALESCE(xsd:decimal(?riskScoreRaw), 0) AS ?riskScore)
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?netCashFlow)) AS ?avg_net_cash_flow)
  (ROUND(AVG(?avgCashFlowAmount)) AS ?avg_cash_flow_amount)
  (ROUND(AVG(?totalHoldingValue)) AS ?avg_total_holding_value)
  (ROUND(AVG(?totalSectorInvestment)) AS ?avg_total_sector_investment)
  (ROUND(AVG(?goalProgress)) AS ?avg_goal_progress)
  (COUNT(DISTINCT ?investor) AS ?n_investors)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?rt .
  ?rt rdfs:label ?riskTolerance .

  OPTIONAL {
    ?cf wm:cashFlowOfInvestor ?investor ;
        wm:amount ?cfAmount .
  }
  BIND(COALESCE(SUM(IF(BOUND(?cfAmount), ?cfAmount, 0)), 0) AS ?totalInflows)

  OPTIONAL {
    ?ch wm:heldByInvestor ?investor ;
         wm:currentValue ?chValue .
  }
  BIND(COALESCE(SUM(IF(BOUND(?chValue), ?chValue, 0)), 0) AS ?totalHoldingValue)

  OPTIONAL {
    ?sa wm:allocationOfInvestor ?investor ;
          wm:totalInvestment ?saTotalInv .
  }
  BIND(COALESCE(SUM(IF(BOUND(?saTotalInv), ?saTotalInv, 0)), 0) AS ?totalSectorInvestment)

  OPTIONAL {
    ?ig wm:belongsToInvestor ?investor ;
           wm:progressPct ?progressPct .
  }
  BIND(COALESCE(AVG(IF(BOUND(?progressPct), ?progressPct, 0)), 0) AS ?goalProgress)

  OPTIONAL {
    ?cf2 wm:cashFlowOfInvestor ?investor ;
          wm:amount ?cfAmt2 .
  }
  BIND(COUNT(DISTINCT ?cf2) AS ?numCashFlows)
  BIND(COALESCE(AVG(IF(BOUND(?cfAmt2), ?cfAmt2, 0)), 0) AS ?avgCashFlowAmount)

  BIND((?totalInflows - COALESCE(SUM(IF(BOUND(?cf) && ?cfAmount < 0, ABS(?cfAmount), 0)), 0)) AS ?netCashFlow)
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?netCashFlow)) AS ?avg_net_cash_flow)
  (ROUND(AVG(?avgCashFlowAmount)) AS ?avg_cash_flow_amount)
  (ROUND(AVG(?totalHoldingValue)) AS ?avg_total_holding_value)
  (ROUND(AVG(?allocationShift)) AS ?avg_scenario_allocation_shift)
  (ROUND(AVG(?goalProgress)) AS ?avg_goal_progress)
WHERE {
  {
    SELECT 
      ?investor 
      (SUM(IF(?cfType IN ("SIP", "Lump Sum", "Deposit"), -xsd:decimal(?cfAmount), xsd:decimal(?cfAmount))) AS ?netCashFlow)
    WHERE {
      ?cf a wm:CashFlow ;
         wm:cashFlowOfInvestor ?investor ;
         wm:amount ?cfAmount ;
         wm:type ?cfType .
    }
    GROUP BY ?investor
  }

  {
    SELECT 
      ?investor 
      (AVG(xsd:decimal(?cfAmount)) AS ?avgCashFlowAmount)
    WHERE {
      ?cf a wm:CashFlow ;
         wm:cashFlowOfInvestor ?investor ;
         wm:amount ?cfAmount .
    }
    GROUP BY ?investor
  }

  {
    SELECT 
      ?investor 
      (SUM(xsd:decimal(?holdingValue)) AS ?totalHoldingValue)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:currentValue ?holdingValue .
    }
    GROUP BY ?investor
  }

  {
    SELECT 
      ?investor 
      (AVG(xsd:decimal(?newAlloc) - xsd:decimal(?currAlloc)) AS ?allocationShift)
    WHERE {
      ?scenario a wm:ScenarioRebalancing ;
                wm:scenarioRebalancingOfInvestor ?investor ;
                wm:newAllocationPct ?newAlloc ;
                wm:currentAllocationPct ?currAlloc .
    }
    GROUP BY ?investor
  }

  {
    SELECT 
      ?investor 
      (AVG(xsd:decimal(?progressPct)) AS ?goalProgress)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?investor ;
            wm:progressPct ?progressPct .
    }
    GROUP BY ?investor
  }

  ?investor wm:hasRiskTolerance ?rt .
  ?rt rdfs:label ?riskTolerance .
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?netCashFlow)) AS ?avg_net_cash_flow)
  (ROUND(AVG(?avgCashFlowAmount)) AS ?avg_cash_flow_amount)
  (ROUND(AVG(?totalHoldingValue)) AS ?avg_total_holding_value)
  (ROUND(AVG(?riskScore)) AS ?avg_risk_score)
  (ROUND(AVG(?goalProgress)) AS ?avg_goal_progress)
  (COUNT(DISTINCT ?investor) AS ?n_investors)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?rt .
  ?rt rdfs:label ?riskTolerance .

  OPTIONAL {
    ?cf wm:cashFlowOfInvestor ?investor ;
        wm:amount ?cfAmount .
    BIND(xsd:decimal(?cfAmount) AS ?amount)
  }
  BIND(IF(BOUND(?amount), ?amount, 0) AS ?cashFlowVal)

  OPTIONAL {
    ?ph wm:heldByInvestor ?investor ;
        wm:currentValue ?phValue .
    BIND(xsd:decimal(?phValue) AS ?holdingValue)
  }
  BIND(IF(BOUND(?holdingValue), ?holdingValue, 0) AS ?currentHoldingValue)

  OPTIONAL {
    ?health wm:healthOfInvestor ?investor ;
            wm:riskScore ?rs .
    BIND(xsd:decimal(?rs) AS ?riskScore)
  }

  OPTIONAL {
    ?goal wm:belongsToInvestor ?investor ;
          wm:progressPct ?gp .
    BIND(xsd:decimal(?gp) AS ?goalProg)
  }
  BIND(IF(BOUND(?goalProg), ?goalProg, 0) AS ?goalProgress)

  OPTIONAL {
    SELECT ?investor (SUM(?cashFlowVal) AS ?netCashFlow) (AVG(?cashFlowVal) AS ?avgCashFlowAmount)
    WHERE {
      ?cf wm:cashFlowOfInvestor ?investor ;
          wm:amount ?cfAmount .
      BIND(xsd:decimal(?cfAmount) AS ?cashFlowVal)
    }
    GROUP BY ?investor
  }

  OPTIONAL {
    SELECT ?investor (SUM(?currentHoldingValue) AS ?totalHoldingValue)
    WHERE {
      ?ph wm:heldByInvestor ?investor ;
          wm:currentValue ?phValue .
      BIND(xsd:decimal(?phValue) AS ?currentHoldingValue)
    }
    GROUP BY ?investor
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?netCashFlow)) AS ?avg_net_cash_flow)
  (ROUND(AVG(?avgCashFlowAmount)) AS ?avg_cash_flow_amount)
  (ROUND(AVG(?totalHoldingValue)) AS ?avg_total_holding_value)
  (ROUND(AVG(?allocationShift)) AS ?avg_scenario_allocation_shift)
  (ROUND(AVG(?riskScore)) AS ?avg_risk_score)
  (COUNT(DISTINCT ?investor) AS ?n_investors)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?rt .
  ?rt rdfs:label ?riskTolerance .

  OPTIONAL {
    ?cf a wm:CashFlow ;
        wm:cashFlowOfInvestor ?investor ;
        wm:amount ?cfAmount .
  }
  BIND(COALESCE(xsd:decimal(?cfAmount), 0) AS ?cashFlowAmt)

  OPTIONAL {
    ?ph a wm:PortfolioHolding ;
        wm:heldByInvestor ?investor ;
        wm:currentValue ?phCurrentValue .
  }
  BIND(COALESCE(xsd:decimal(?phCurrentValue), 0) AS ?holdingValue)

  OPTIONAL {
    ?sa a wm:ScenarioRebalancing ;
        wm:scenarioRebalancingOfInvestor ?investor ;
        wm:currentAllocationPct ?currAlloc ;
        wm:newAllocationPct ?newAlloc .
  }
  BIND(COALESCE(xsd:decimal(?newAlloc) - xsd:decimal(?currAlloc), 0) AS ?allocShift)

  OPTIONAL {
    ?health a wm:PortfolioHealth ;
            wm:healthOfInvestor ?investor ;
            wm:riskScore ?rs .
  }
  BIND(COALESCE(xsd:decimal(?rs), 0) AS ?riskScoreVal)

  {
    SELECT ?investor
           (SUM(IF(?cfTypeLabel IN ("SIP", "Lump Sum", "Deposit"), -?cashFlowAmt, ?cashFlowAmt)) AS ?netCashFlow)
           (AVG(?cashFlowAmt) AS ?avgCashFlowAmount)
    WHERE {
      ?investor a wm:Investor .
      OPTIONAL {
        ?cf a wm:CashFlow ;
            wm:cashFlowOfInvestor ?investor ;
            wm:amount ?cfAmount ;
            wm:hasCashFlowType ?cft .
        ?cft rdfs:label ?cfTypeLabel .
      }
      BIND(COALESCE(xsd:decimal(?cfAmount), 0) AS ?cashFlowAmt)
    }
    GROUP BY ?investor
  }

  {
    SELECT ?investor (SUM(?holdingValue) AS ?totalHoldingValue)
    WHERE {
      ?investor a wm:Investor .
      OPTIONAL {
        ?ph a wm:PortfolioHolding ;
            wm:heldByInvestor ?investor ;
            wm:currentValue ?phCurrentValue .
      }
      BIND(COALESCE(xsd:decimal(?phCurrentValue), 0) AS ?holdingValue)
    }
    GROUP BY ?investor
  }

  {
    SELECT ?investor (AVG(?allocShift) AS ?allocationShift)
    WHERE {
      ?investor a wm:Investor .
      OPTIONAL {
        ?sa a wm:ScenarioRebalancing ;
            wm:scenarioRebalancingOfInvestor ?investor ;
            wm:currentAllocationPct ?currAlloc ;
            wm:newAllocationPct ?newAlloc .
      }
      BIND(COALESCE(xsd:decimal(?newAlloc) - xsd:decimal(?currAlloc), 0) AS ?allocShift)
    }
    GROUP BY ?investor
  }

  {
    SELECT ?investor (AVG(?riskScoreVal) AS ?riskScore)
    WHERE {
      ?investor a wm:Investor .
      OPTIONAL {
        ?health a wm:PortfolioHealth ;
                wm:healthOfInvestor ?investor ;
                wm:riskScore ?rs .
      }
      BIND(COALESCE(xsd:decimal(?rs), 0) AS ?riskScoreVal)
    }
    GROUP BY ?investor
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?netCashFlow)) AS ?avg_net_cash_flow)
  (ROUND(AVG(?avgCashFlowAmount)) AS ?avg_cash_flow_amount)
  (ROUND(AVG(?totalRebalanceAmount)) AS ?avg_total_rebalance_amount)
  (ROUND(AVG(?totalSectorInvestment)) AS ?avg_total_sector_investment)
  (ROUND(AVG(?allocationShift)) AS ?avg_scenario_allocation_shift)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?rt ;
            wm:investorId ?investorId .

  ?rt rdfs:label ?riskTolerance .

  OPTIONAL {
    ?cashFlow wm:cashFlowOfInvestor ?investor ;
              wm:amount ?cfAmount .
  }
  BIND(COALESCE(SUM(xsd:decimal(?cfAmount)), 0) AS ?netCashFlow)
  BIND(COALESCE(AVG(xsd:decimal(?cfAmount)), 0) AS ?avgCashFlowAmount)

  OPTIONAL {
    ?rebalancingAction wm:rebalancingActionOfInvestor ?investor ;
                       wm:amount ?rbAmount .
  }
  BIND(COALESCE(SUM(xsd:decimal(?rbAmount)), 0) AS ?totalRebalanceAmount)

  OPTIONAL {
    ?sectorAllocation wm:allocationOfInvestor ?investor ;
                      wm:totalInvestment ?siAmount .
  }
  BIND(COALESCE(SUM(xsd:decimal(?siAmount)), 0) AS ?totalSectorInvestment)

  OPTIONAL {
    ?scenarioRebalancing wm:scenarioRebalancingOfInvestor ?investor ;
                         wm:currentAllocationPct ?currentAlloc ;
                         wm:newAllocationPct ?newAlloc .
    BIND((xsd:decimal(?newAlloc) - xsd:decimal(?currentAlloc)) AS ?allocationShift)
  }

} GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?netCashFlow)) AS ?avg_net_cash_flow)
  (ROUND(AVG(?avgCashFlowAmount)) AS ?avg_cash_flow_amount)
  (ROUND(AVG(?totalRebalanceAmount)) AS ?avg_rebalance_amount)
  (ROUND(AVG(?totalSectorInvestment)) AS ?avg_sector_investment)
  (ROUND(AVG(?goalProgress)) AS ?avg_goal_progress)
  (COUNT(DISTINCT ?investor) AS ?n_investors)
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?rt .
  ?rt rdfs:label ?riskTolerance .

  OPTIONAL {
    ?cf wm:cashFlowOfInvestor ?investor ;
        wm:amount ?cfAmount .
    BIND(xsd:decimal(?cfAmount) AS ?amount)
  }
  BIND(COALESCE(SUM(IF(?amount > 0, ?amount, 0)), 0) - COALESCE(SUM(IF(?amount < 0, ABS(?amount), 0)), 0) AS ?netCashFlow)
  BIND(COALESCE(AVG(ABS(?amount)), 0) AS ?avgCashFlowAmount)

  OPTIONAL {
    ?ra wm:rebalancingActionOfInvestor ?investor ;
         wm:amount ?raAmount .
    BIND(xsd:decimal(?raAmount) AS ?rebAmt)
  }
  BIND(COALESCE(SUM(?rebAmt), 0) AS ?totalRebalanceAmount)

  OPTIONAL {
    ?sa wm:allocationOfInvestor ?investor ;
        wm:totalInvestment ?saTotalInv .
    BIND(xsd:decimal(?saTotalInv) AS ?totSecInv)
  }
  BIND(COALESCE(SUM(?totSecInv), 0) AS ?totalSectorInvestment)

  OPTIONAL {
    ?ig wm:belongsToInvestor ?investor ;
        wm:progressPct ?progressPctStr .
    BIND(xsd:decimal(?progressPctStr) AS ?goalProgress)
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?investorId
       (SUM(xsd:decimal(?cashFlowAmount)) +
        SUM(xsd:decimal(?holdingGain)) +
        SUM(xsd:decimal(?rebalanceAmount)) +
        SUM(xsd:decimal(?sectorInvestment)) AS ?compositeScore)
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId .

  OPTIONAL {
    ?cashFlow a wm:CashFlow ;
              wm:cashFlowOfInvestor ?investor ;
              wm:amount ?cashFlowAmount .
  }

  OPTIONAL {
    ?holding a wm:PortfolioHolding ;
             wm:heldByInvestor ?investor ;
             wm:cost ?cost ;
             wm:currentValue ?currentValue .
    BIND((xsd:decimal(?currentValue) - xsd:decimal(?cost)) AS ?holdingGain)
  }

  OPTIONAL {
    ?rebalance a wm:RebalancingAction ;
               wm:rebalancingActionOfInvestor ?investor ;
               wm:amount ?rebalanceAmount .
  }

  OPTIONAL {
    ?allocation a wm:SectorAllocation ;
                wm:allocationOfInvestor ?investor ;
                wm:totalInvestment ?sectorInvestment .
  }

  FILTER(
    EXISTS { ?cashFlow a wm:CashFlow }
    && EXISTS { ?holding a wm:PortfolioHolding }
    && EXISTS { ?rebalance a wm:RebalancingAction }
    && EXISTS { ?allocation a wm:SectorAllocation }
  )
}
GROUP BY ?investorId
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?netCashFlow)) AS ?avg_net_cash_flow)
  (ROUND(AVG(?avgCashFlowAmount)) AS ?avg_cash_flow_amount)
  (ROUND(AVG(?totalRebalanceAmount)) AS ?avg_total_rebalance_amount)
  (ROUND(AVG(?totalSectorInvestment)) AS ?avg_total_sector_investment)
  (ROUND(AVG(?riskScore)) AS ?avg_risk_score)
  (COUNT(DISTINCT ?investorId) AS ?n_investors)
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:riskTolerance ?riskTolerance .

  OPTIONAL {
    ?cashFlow wm:cashFlowOfInvestor ?investor ;
              wm:amount ?cfAmount .
    BIND(xsd:decimal(?cfAmount) AS ?amountValue)
  }
  BIND(IF(BOUND(?amountValue), ?amountValue, 0) AS ?safeAmount)

  OPTIONAL {
    ?holding wm:heldByInvestor ?investor ;
             wm:cost ?holdingCost .
    BIND(xsd:decimal(?holdingCost) AS ?costValue)
  }
  BIND(IF(BOUND(?costValue), ?costValue, 0) AS ?safeCost)

  OPTIONAL {
    ?rebalancing wm:rebalancingActionOfInvestor ?investor ;
                 wm:amount ?rbAmount .
    BIND(xsd:decimal(?rbAmount) AS ?rebalValue)
  }
  BIND(IF(BOUND(?rebalValue), ?rebalValue, 0) AS ?safeRebal)

  OPTIONAL {
    ?sectorAlloc wm:allocationOfInvestor ?investor ;
                 wm:totalInvestment ?secTotalInv .
    BIND(xsd:decimal(?secTotalInv) AS ?invValue)
  }
  BIND(IF(BOUND(?invValue), ?invValue, 0) AS ?safeInv)

  OPTIONAL {
    ?portfolioHealth wm:healthOfInvestor ?investor ;
                     wm:riskScore ?rsScore .
    BIND(xsd:decimal(?rsScore) AS ?scoreValue)
  }
  BIND(IF(BOUND(?scoreValue), ?scoreValue, 0) AS ?safeScore)

  {
    SELECT ?investor
           (SUM(?safeAmount) AS ?netCashFlow)
           (AVG(?safeAmount) AS ?avgCashFlowAmount)
    WHERE {
      ?cashFlow wm:cashFlowOfInvestor ?investor ;
                wm:amount ?cfAmount .
      BIND(xsd:decimal(?cfAmount) AS ?amountValue)
      BIND(IF(BOUND(?amountValue), ?amountValue, 0) AS ?safeAmount)
    }
    GROUP BY ?investor
  }

  {
    SELECT ?investor
           (SUM(?safeRebal) AS ?totalRebalanceAmount)
    WHERE {
      ?rebalancing wm:rebalancingActionOfInvestor ?investor ;
                   wm:amount ?rbAmount .
      BIND(xsd:decimal(?rbAmount) AS ?rebalValue)
      BIND(IF(BOUND(?rebalValue), ?rebalValue, 0) AS ?safeRebal)
    }
    GROUP BY ?investor
  }

  {
    SELECT ?investor
           (SUM(?safeInv) AS ?totalSectorInvestment)
    WHERE {
      ?sectorAlloc wm:allocationOfInvestor ?investor ;
                   wm:totalInvestment ?secTotalInv .
      BIND(xsd:decimal(?secTotalInv) AS ?invValue)
      BIND(IF(BOUND(?invValue), ?invValue, 0) AS ?safeInv)
    }
    GROUP BY ?investor
  }

  {
    SELECT ?investor
           (AVG(?safeScore) AS ?riskScore)
    WHERE {
      ?portfolioHealth wm:healthOfInvestor ?investor ;
                       wm:riskScore ?rsScore .
      BIND(xsd:decimal(?rsScore) AS ?scoreValue)
      BIND(IF(BOUND(?scoreValue), ?scoreValue, 0) AS ?safeScore)
    }
    GROUP BY ?investor
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId
           ((MIN(?netCashFlow) + (?netCashFlow - MIN(?netCashFlow)) / (MAX(?netCashFlow) - MIN(?netCashFlow))) AS ?normNetCashFlow)
           ((MIN(?totalGain) + (?totalGain - MIN(?totalGain)) / (MAX(?totalGain) - MIN(?totalGain))) AS ?normTotalGain)
           ((MIN(?rebalanceAmt) + (?rebalanceAmt - MIN(?rebalanceAmt)) / (MAX(?rebalanceAmt) - MIN(?rebalanceAmt))) AS ?normRebalanceAmt)
           ((MIN(?allocShift) + (?allocShift - MIN(?allocShift)) / (MAX(?allocShift) - MIN(?allocShift))) AS ?normAllocShift)
           (((?normNetCashFlow + ?normTotalGain + ?normRebalanceAmt + ?normAllocShift) / 4) * 100 AS ?compositeScore)
    WHERE {
      {
        SELECT ?investorId
               (SUM(IF(?type_iri IN (wm:SIP, wm:LumpSum, wm:Deposit), -?amount, ?amount)) AS ?netCashFlow)
        WHERE {
          [] wm:cashFlowOfInvestor ?investor_iri ;
             wm:investorId ?investorId ;
             wm:hasCashFlowType ?type_iri ;
             wm:amount ?amount_str .
          BIND(xsd:decimal(?amount_str) AS ?amount)
          VALUES (?inflow_types) {(wm:SIP) (wm:LumpSum) (wm:Deposit)}
          VALUES (?outflow_types) {(wm:Redemption) (wm:Withdrawal)}
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId
               (SUM(xsd:decimal(?currentValue) - xsd:decimal(?cost)) AS ?totalGain)
        WHERE {
          [] wm:heldByInvestor ?investor_iri ;
             wm:investorId ?investorId ;
             wm:cost ?cost ;
             wm:currentValue ?currentValue .
          FILTER(?cost != "" && ?currentValue != "")
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId
               (SUM(xsd:decimal(?amount)) AS ?rebalanceAmt)
        WHERE {
          [] wm:rebalancingActionOfInvestor ?investor_iri ;
             wm:investorId ?investorId ;
             wm:amount ?amount .
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId
               (SUM(ABS(xsd:decimal(?newAlloc) - xsd:decimal(?currAlloc))) AS ?allocShift)
        WHERE {
          [] wm:scenarioRebalancingOfInvestor ?investor_iri ;
             wm:investorId ?investorId ;
             wm:newAllocationPct ?newAlloc ;
             wm:currentAllocationPct ?currAlloc .
        }
        GROUP BY ?investorId
      }
    }
    GROUP BY ?investorId ?netCashFlow ?totalGain ?rebalanceAmt ?allocShift
  }
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?investorId
WITH {
  SELECT ?investorId
         (SUM(xsd:decimal(?cashFlowAmount)) AS ?netCashFlow)
  WHERE {
    ?cashFlow wm:cashFlowOfInvestor ?investor ;
              wm:amount ?cashFlowAmount ;
              wm:type ?type .
    ?investor wm:investorId ?investorId .
    FILTER (?type IN ("SIP", "Lump Sum", "Deposit", "Redemption", "Withdrawal"))
  }
  GROUP BY ?investorId
} AS %netCashFlow
WITH {
  SELECT ?investorId
         (SUM(xsd:decimal(?gain)) AS ?totalHoldingGain)
  WHERE {
    ?holding wm:heldByInvestor ?investor ;
             wm:cost ?cost ;
             wm:currentValue ?currentValue .
    BIND(xsd:decimal(?currentValue) - xsd:decimal(?cost) AS ?gain)
    ?investor wm:investorId ?investorId .
    FILTER (BOUND(?cost) && BOUND(?currentValue) && ?cost != "" && ?currentValue != "")
  }
  GROUP BY ?investorId
} AS %holdingGain
WITH {
  SELECT ?investorId
         (SUM(xsd:decimal(?amount)) AS ?totalRebalanceAmount)
  WHERE {
    ?rebalance wm:rebalancingActionOfInvestor ?investor ;
               wm:amount ?amount .
    ?investor wm:investorId ?investorId .
  }
  GROUP BY ?investorId
} AS %rebalanceAmount
WITH {
  SELECT ?investorId
         (AVG(xsd:decimal(?shortfall)) AS ?avgGoalShortfall)
  WHERE {
    ?goal wm:belongsToInvestor ?investor ;
          wm:shortfall ?shortfall .
    ?investor wm:investorId ?investorId .
  }
  GROUP BY ?investorId
} AS %avgShortfall
WHERE {
  INCLUDE %netCashFlow
  INCLUDE %holdingGain
  INCLUDE %rebalanceAmount
  INCLUDE %avgShortfall

  BIND((?netCashFlow + ?totalHoldingGain + ?totalRebalanceAmount - ?avgGoalShortfall) AS ?compositeScore)
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId
           (100 * (
              (?netCashFlowNorm + ?totalGainNorm + ?rebalanceAmountNorm + ?riskScoreNorm) / 4
            ) AS ?compositeScore)
    WHERE {
      {
        SELECT ?investorId
               ((?netCashFlow - MIN(?netCashFlow) OVER()) / (MAX(?netCashFlow) OVER() - MIN(?netCashFlow) OVER())) AS ?netCashFlowNorm
               ((?totalGain - MIN(?totalGain) OVER()) / (MAX(?totalGain) OVER() - MIN(?totalGain) OVER())) AS ?totalGainNorm
               ((?rebalanceAmount - MIN(?rebalanceAmount) OVER()) / (MAX(?rebalanceAmount) OVER() - MIN(?rebalanceAmount) OVER())) AS ?rebalanceAmountNorm
               ((?riskScore - MIN(?riskScore) OVER()) / (MAX(?riskScore) OVER() - MIN(?riskScore) OVER())) AS ?riskScoreNorm
        WHERE {
          {
            SELECT ?investorId
                   (SUM(COALESCE(?inflows, 0) - COALESCE(?outflows, 0)) AS ?netCashFlow)
                   (SUM(COALESCE(?gain, 0)) AS ?totalGain)
                   (SUM(COALESCE(?rebalanceAmt, 0)) AS ?rebalanceAmount)
                   (MAX(?riskScoreVal) AS ?riskScore)
            WHERE {
              ?investor a wm:Investor ;
                        wm:investorId ?investorId .

              OPTIONAL {
                ?cf wm:cashFlowOfInvestor ?investor ;
                    wm:amount ?amtStr ;
                    wm:type ?cfType .
                BIND(xsd:decimal(?amtStr) AS ?amt)
                FILTER(?amt > 0)
                BIND(IF(?cfType IN ("SIP", "Lump Sum", "Deposit"), ?amt, 0) AS ?inflowVal)
                BIND(IF(?cfType IN ("Redemption", "Withdrawal"), ?amt, 0) AS ?outflowVal)
              }

              OPTIONAL {
                ?holding wm:heldByInvestor ?investor ;
                         wm:cost ?costStr ;
                         wm:currentValue ?valueStr .
                BIND(xsd:decimal(?costStr) AS ?cost)
                BIND(xsd:decimal(?valueStr) AS ?value)
                FILTER(?cost > 0 && ?value >= 0)
                BIND((?value - ?cost) AS ?gain)
              }

              OPTIONAL {
                ?ra wm:rebalancingActionOfInvestor ?investor ;
                    wm:amount ?raAmtStr .
                BIND(xsd:decimal(?raAmtStr) AS ?rebalanceAmt)
              }

              OPTIONAL {
                ?ph wm:healthOfInvestor ?investor ;
                    wm:riskScore ?rsStr .
                BIND(xsd:decimal(?rsStr) AS ?riskScoreVal)
              }

              BIND(COALESCE(?inflowVal, 0) AS ?inflows)
              BIND(COALESCE(?outflowVal, 0) AS ?outflows)
            }
            GROUP BY ?investorId
            HAVING (
              COUNT(?inflows) > 0 &&
              COUNT(?outflows) > 0 &&
              COUNT(?gain) > 0 &&
              COUNT(?rebalanceAmt) > 0 &&
              COUNT(?riskScoreVal) > 0
            )
          }
        }
      }
    }
  }
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId
           (100 * (
              (?netCashFlowNorm + ?totalGainNorm + ?totalSectorInvestmentNorm + ?riskScoreNorm) / 4
            ) AS ?compositeScore)
    WHERE {
      {
        SELECT ?investorId
               ((?netCashFlow - MIN(?netCashFlow) OVER()) / (MAX(?netCashFlow) OVER() - MIN(?netCashFlow) OVER())) AS ?netCashFlowNorm
        WHERE {
          ?cashFlow wm:cashFlowOfInvestor ?investor .
          ?investor wm:investorId ?investorId .
          ?cashFlow wm:amount ?amountStr .
          BIND(xsd:decimal(?amountStr) AS ?amount)
          ?cashFlow wm:type ?type .
          BIND(IF(?type IN ("SIP", "Lump Sum", "Deposit"), -?amount, ?amount) AS ?signedAmount)
        }
        GROUP BY ?investorId
        LET (?netCashFlow := SUM(?signedAmount))
      }
      {
        SELECT ?investorId
               ((?totalGain - MIN(?totalGain) OVER()) / (MAX(?totalGain) OVER() - MIN(?totalGain) OVER())) AS ?totalGainNorm
        WHERE {
          ?holding wm:heldByInvestor ?investor .
          ?investor wm:investorId ?investorId .
          ?holding wm:cost ?costStr .
          ?holding wm:currentValue ?currentValueStr .
          BIND(xsd:decimal(?costStr) AS ?cost)
          BIND(xsd:decimal(?currentValueStr) AS ?currentValue)
          FILTER(?cost > 0 && ?currentValue >= 0)
        }
        GROUP BY ?investorId
        LET (?totalGain := SUM(?currentValue - ?cost))
      }
      {
        SELECT ?investorId
               ((?totalSectorInvestment - MIN(?totalSectorInvestment) OVER()) / (MAX(?totalSectorInvestment) OVER() - MIN(?totalSectorInvestment) OVER())) AS ?totalSectorInvestmentNorm
        WHERE {
          ?sectorAlloc wm:allocationOfInvestor ?investor .
          ?investor wm:investorId ?investorId .
          ?sectorAlloc wm:totalInvestment ?totalInvestmentStr .
          BIND(xsd:decimal(?totalInvestmentStr) AS ?totalSectorInvestment)
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId
               ((?riskScore - MIN(?riskScore) OVER()) / (MAX(?riskScore) OVER() - MIN(?riskScore) OVER())) AS ?riskScoreNorm
        WHERE {
          ?health wm:healthOfInvestor ?investor .
          ?investor wm:investorId ?investorId .
          ?health wm:riskScore ?riskScoreStr .
          BIND(xsd:integer(?riskScoreStr) AS ?riskScore)
        }
        GROUP BY ?investorId
      }
    }
    GROUP BY ?investorId ?netCashFlowNorm ?totalGainNorm ?totalSectorInvestmentNorm ?riskScoreNorm
  }
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?investorId
WHERE {
  {
    SELECT ?investorId
           (SUM(xsd:decimal(?cashFlowAmount)) AS ?netCashFlow)
    WHERE {
      ?cashFlow wm:cashFlowOfInvestor ?investor ;
                wm:amount ?cashFlowAmount ;
                wm:type ?cashFlowType .
      ?investor wm:investorId ?investorId .
      FILTER (?cashFlowType IN ("SIP", "Lump Sum", "Deposit", "Redemption", "Withdrawal"))
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId
           (SUM(xsd:decimal(?currentValue) - xsd:decimal(?cost)) AS ?totalHoldingGain)
    WHERE {
      ?holding wm:heldByInvestor ?investor ;
               wm:cost ?cost ;
               wm:currentValue ?currentValue ;
               wm:investmentType ?investmentType .
      ?investor wm:investorId ?investorId .
      FILTER (xsd:decimal(?cost) > 0 && xsd:decimal(?currentValue) >= 0)
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId
           (SUM(xsd:decimal(?totalInvestment)) AS ?totalSectorInvestment)
    WHERE {
      ?sectorAlloc wm:allocationOfInvestor ?investor ;
                   wm:totalInvestment ?totalInvestment .
      ?investor wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId
           (AVG(xsd:decimal(?shortfall)) AS ?avgGoalShortfall)
    WHERE {
      ?goal wm:belongsToInvestor ?investor ;
            wm:shortfall ?shortfall .
      ?investor wm:investorId ?investorId .
      FILTER (xsd:decimal(?shortfall) >= 0)
    }
    GROUP BY ?investorId
  }
}
BIND((?netCashFlow + ?totalHoldingGain + ?totalSectorInvestment - ?avgGoalShortfall) AS ?compositeScore)
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
WITH (
  SELECT 
    cf.investorId,
    SUM(CASE WHEN cf.type IN ('SIP', 'Lump Sum', 'Deposit') THEN -cf.amount 
             WHEN cf.type IN ('Redemption', 'Withdrawal') THEN cf.amount END) AS net_cash_flow
  FROM wm:CashFlow cf
  GROUP BY cf.investorId
) AS cash_flow_agg,

(
  SELECT 
    ph.investorId,
    SUM(ph.currentValue - ph.cost) AS total_gain
  FROM wm:PortfolioHolding ph
  WHERE ph.cost IS NOT NULL AND ph.currentValue IS NOT NULL
  GROUP BY ph.investorId
) AS holding_gain_agg,

(
  SELECT 
    sa.investorId,
    SUM(sa.totalInvestment) AS total_sector_investment
  FROM wm:SectorAllocation sa
  GROUP BY sa.investorId
) AS sector_investment_agg,

(
  SELECT 
    sr.investorId,
    SUM(xsd:decimal(sr.newAllocationPct) - xsd:decimal(sr.currentAllocationPct)) AS allocation_shift
  FROM wm:ScenarioRebalancing sr
  GROUP BY sr.investorId
) AS allocation_shift_agg

SELECT 
  ?investorId
  ((xsd:double(?net_cash_flow_norm) + xsd:double(?total_gain_norm) + xsd:double(?total_sector_investment_norm) + xsd:double(?allocation_shift_norm)) * 25.0 AS ?composite_score)
WHERE {
  {
    SELECT 
      MIN(?net_cash_flow) AS ?min_net_cash_flow
      MAX(?net_cash_flow) AS ?max_net_cash_flow
    WHERE {
      ?cf a wm:CashFlow .
      BIND(?cf wm:investorId ?investorId_cf)
      FILTER EXISTS { ?cf wm:amount ?_ }
      BIND(IF(?max_net_cash_flow = ?min_net_cash_flow, 1, ?max_net_cash_flow - ?min_net_cash_flow) AS ?denom_ncf)
    }
    GROUP BY ()
  }

  {
    SELECT 
      MIN(?total_gain) AS ?min_total_gain
      MAX(?total_gain) AS ?max_total_gain
    WHERE {
      ?ph a wm:PortfolioHolding .
      BIND(?ph wm:investorId ?investorId_ph)
      FILTER EXISTS { ?ph wm:cost ?_ }
      FILTER EXISTS { ?ph wm:currentValue ?_ }
      BIND(IF(?max_total_gain = ?min_total_gain, 1, ?max_total_gain - ?min_total_gain) AS ?denom_tg)
    }
    GROUP BY ()
  }

  {
    SELECT 
      MIN(?total_sector_investment) AS ?min_total_sector_investment
      MAX(?total_sector_investment) AS ?max_total_sector_investment
    WHERE {
      ?sa a wm:SectorAllocation .
      BIND(?sa wm:investorId ?investorId_sa)
      FILTER EXISTS { ?sa wm:totalInvestment ?_ }
      BIND(IF(?max_total_sector_investment = ?min_total_sector_investment, 1, ?max_total_sector_investment - ?min_total_sector_investment) AS ?denom_tsi)
    }
    GROUP BY ()
  }

  {
    SELECT 
      MIN(?allocation_shift) AS ?min_allocation_shift
      MAX(?allocation_shift) AS ?max_allocation_shift
    WHERE {
      ?sr a wm:ScenarioRebalancing .
      BIND(?sr wm:investorId ?investorId_sr)
      FILTER EXISTS { ?sr wm:newAllocationPct ?_ }
      FILTER EXISTS { ?sr wm:currentAllocationPct ?_ }
      BIND(IF(?max_allocation_shift = ?min_allocation_shift, 1, ?max_allocation_shift - ?min_allocation_shift) AS ?denom_as)
    }
    GROUP BY ()
  }

  ?ip a wm:Investor ;
      wm:investorId ?investorId .

  OPTIONAL { 
    ?cf wm:cashFlowOfInvestor ?ip ;
        wm:amount ?amount ;
        wm:type ?type .
    BIND(IF(?type IN ("SIP", "Lump Sum", "Deposit"), -?amount, ?amount) AS ?signed_amount)
    BIND(SUM(?signed_amount) AS ?net_cash_flow)
  }

  OPTIONAL { 
    ?ph wm:heldByInvestor ?ip ;
        wm:cost ?cost ;
        wm:currentValue ?currentValue .
    BIND((?currentValue - ?cost) AS ?gain)
    BIND(SUM(?gain) AS ?total_gain)
  }

  OPTIONAL { 
    ?sa wm:allocationOfInvestor ?ip ;
        wm:totalInvestment ?totalInvestment .
    BIND(SUM(?totalInvestment) AS ?total_sector_investment)
  }

  OPTIONAL { 
    ?sr wm:scenarioRebalancingOfInvestor ?ip ;
        wm:newAllocationPct ?newAlloc ;
        wm:currentAllocationPct ?currAlloc .
    BIND((xsd:decimal(?newAlloc) - xsd:decimal(?currAlloc)) AS ?shift)
    BIND(SUM(?shift) AS ?allocation_shift)
  }

  FILTER(BOUND(?net_cash_flow) && BOUND(?total_gain) && BOUND(?total_sector_investment) && BOUND(?allocation_shift))

  BIND((?net_cash_flow - ?min_net_cash_flow) / (?max_net_cash_flow - ?min_net_cash_flow) AS ?net_cash_flow_norm)
  BIND((?total_gain - ?min_total_gain) / (?max_total_gain - ?min_total_gain) AS ?total_gain_norm)
  BIND((?total_sector_investment - ?min_total_sector_investment) / (?max_total_sector_investment - ?min_total_sector_investment) AS ?total_sector_investment_norm)
  BIND((?allocation_shift - ?min_allocation_shift) / (?max_allocation_shift - ?min_allocation_shift) AS ?allocation_shift_norm)

}
ORDER BY DESC(?composite_score) ?investorId
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId
           ((?netCashFlowNorm + ?gainNorm + ?allocShiftNorm + ?riskScoreNorm) / 4 * 100 AS ?compositeScore)
    WHERE {
      {
        SELECT ?investorId
               ((?netCashFlow - MIN(?netCashFlow) OVER()) / (MAX(?netCashFlow) OVER() - MIN(?netCashFlow) OVER()) AS ?netCashFlowNorm)
               ((?totalGain - MIN(?totalGain) OVER()) / (MAX(?totalGain) OVER() - MIN(?totalGain) OVER()) AS ?gainNorm)
               ((?allocShift - MIN(?allocShift) OVER()) / (MAX(?allocShift) OVER() - MIN(?allocShift) OVER()) AS ?allocShiftNorm)
               ((?riskScore - MIN(?riskScore) OVER()) / (MAX(?riskScore) OVER() - MIN(?riskScore) OVER()) AS ?riskScoreNorm)
        WHERE {
          {
            SELECT ?investorId
                   (SUM(?cashIn - ?cashOut) AS ?netCashFlow)
            WHERE {
              ?cf wm:cashFlowOfInvestor ?inv .
              ?inv wm:investorId ?investorId .
              OPTIONAL {
                ?cf wm:type "SIP" ; wm:amount ?sipAmt .
                BIND(COALESCE(xsd:decimal(?sipAmt), 0) AS ?amtSIP)
              }
              OPTIONAL {
                ?cf wm:type "Lump Sum" ; wm:amount ?lsAmt .
                BIND(COALESCE(xsd:decimal(?lsAmt), 0) AS ?amtLS)
              }
              OPTIONAL {
                ?cf wm:type "Deposit" ; wm:amount ?depAmt .
                BIND(COALESCE(xsd:decimal(?depAmt), 0) AS ?amtDep)
              }
              OPTIONAL {
                ?cf wm:type "Redemption" ; wm:amount ?redAmt .
                BIND(COALESCE(xsd:decimal(?redAmt), 0) AS ?amtRed)
              }
              OPTIONAL {
                ?cf wm:type "Withdrawal" ; wm:amount ?wdAmt .
                BIND(COALESCE(xsd:decimal(?wdAmt), 0) AS ?amtWD)
              }

              BIND(COALESCE(?amtSIP, 0) + COALESCE(?amtLS, 0) + COALESCE(?amtDep, 0) AS ?cashIn)
              BIND(COALESCE(?amtRed, 0) + COALESCE(?amtWD, 0) AS ?cashOut)
            }
            GROUP BY ?investorId
          }

          {
            SELECT ?investorId
                   (SUM(IF(?currentVal > ?costVal, ?currentVal - ?costVal, 0)) AS ?totalGain)
            WHERE {
              ?ph wm:heldByInvestor ?inv .
              ?inv wm:investorId ?investorId .
              ?ph wm:cost ?costStr ; wm:currentValue ?curValStr .
              BIND(xsd:decimal(?costStr) AS ?costVal)
              BIND(xsd:decimal(?curValStr) AS ?currentVal)
              FILTER(?costVal > 0 && ?currentVal >= 0)
            }
            GROUP BY ?investorId
          }

          {
            SELECT ?investorId
                   (SUM(xsd:decimal(?newAlloc) - xsd:decimal(?currAlloc)) AS ?allocShift)
            WHERE {
              ?sr wm:scenarioRebalancingOfInvestor ?inv .
              ?inv wm:investorId ?investorId .
              ?sr wm:currentAllocationPct ?currAlloc ;
                  wm:newAllocationPct ?newAlloc .
            }
            GROUP BY ?investorId
          }

          {
            SELECT ?investorId ?riskScore
            WHERE {
              ?ph wm:healthOfInvestor ?inv .
              ?inv wm:investorId ?investorId .
              ?ph wm:riskScore ?riskScoreStr .
              BIND(xsd:integer(?riskScoreStr) AS ?riskScore)
            }
          }
        }
      }
    }
  }
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
WITH (
  SELECT 
    inv.investorId,
    SUM(CASE WHEN cf.type IN ('SIP', 'Lump Sum', 'Deposit') THEN -cf.amount 
             WHEN cf.type IN ('Redemption', 'Withdrawal') THEN cf.amount END) AS net_cash_flow,
    SUM(CASE WHEN ph.cost IS NOT NULL AND ph.currentValue IS NOT NULL THEN (ph.currentValue - ph.cost) ELSE 0 END) AS total_gain,
    SUM(CASE WHEN sa.allocationPct IS NOT NULL AND sra.newAllocationPct IS NOT NULL THEN ABS(xsd:decimal(sra.newAllocationPct) - xsd:decimal(sa.allocationPct)) ELSE 0 END) AS total_alloc_shift,
    AVG(CASE WHEN ig.shortfall IS NOT NULL THEN ig.shortfall ELSE 0 END) AS avg_goal_shortfall
  WHERE {
    ?inv a wm:Investor ;
         wm:investorId ?investorId .

    OPTIONAL {
      ?cf a wm:CashFlow ;
          wm:cashFlowOfInvestor ?inv ;
          wm:type ?type ;
          wm:amount ?amount .
    }

    OPTIONAL {
      ?ph a wm:PortfolioHolding ;
          wm:heldByInvestor ?inv ;
          wm:cost ?cost ;
          wm:currentValue ?currentValue .
    }

    OPTIONAL {
      ?sa a wm:SectorAllocation ;
           wm:allocationOfInvestor ?inv ;
           wm:allocationPct ?allocationPct .

      OPTIONAL {
        ?sra a wm:ScenarioRebalancing ;
              wm:scenarioRebalancingOfInvestor ?inv ;
              wm:newAllocationPct ?newAllocationPct .
      }
    }

    OPTIONAL {
      ?ig a wm:InvestmentGoal ;
          wm:belongsToInvestor ?inv ;
          wm:shortfall ?shortfall .
    }
  }
  GROUP BY ?inv ?investorId
  HAVING (
    bound(?net_cash_flow) &&
    bound(?total_gain) &&
    bound(?total_alloc_shift) &&
    bound(?avg_goal_shortfall)
  )
) AS components

SELECT 
  ?investorId
  ((xsd:decimal(?norm_net_cf) + xsd:decimal(?norm_total_gain) + xsd:decimal(?norm_total_alloc_shift) + (1 - xsd:decimal(?norm_avg_shortfall))) / 4 * 100 AS ?composite_score)
WHERE {
  {
    SELECT 
      MAX(components.net_cash_flow) AS ?max_net_cf,
      MIN(components.net_cash_flow) AS ?min_net_cf,
      MAX(components.total_gain) AS ?max_total_gain,
      MIN(components.total_gain) AS ?min_total_gain,
      MAX(components.total_alloc_shift) AS ?max_total_alloc_shift,
      MIN(components.total_alloc_shift) AS ?min_total_alloc_shift,
      MAX(components.avg_goal_shortfall) AS ?max_avg_shortfall,
      MIN(components.avg_goal_shortfall) AS ?min_avg_shortfall
    WHERE {}
  }

  INCLUDE COMPONENTS

  BIND((components.net_cash_flow - ?min_net_cf) / (?max_net_cf - ?min_net_cf) AS ?norm_net_cf)
  BIND((components.total_gain - ?min_total_gain) / (?max_total_gain - ?min_total_gain) AS ?norm_total_gain)
  BIND((components.total_alloc_shift - ?min_total_alloc_shift) / (?max_total_alloc_shift - ?min_total_alloc_shift) AS ?norm_total_alloc_shift)
  BIND((components.avg_goal_shortfall - ?min_avg_shortfall) / (?max_avg_shortfall - ?min_avg_shortfall) AS ?norm_avg_shortfall)

}
ORDER BY DESC(?composite_score) ?investorId
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId
           ((?netCashFlowNorm + ?gainNorm + ?riskScoreNorm + (1 - ?avgShortfallNorm)) / 4 * 100 AS ?compositeScore)
    WHERE {
      {
        SELECT ?investorId
               (?netCashFlow - MIN(?netCashFlow) OVER()) / (MAX(?netCashFlow) OVER() - MIN(?netCashFlow) OVER()) AS ?netCashFlowNorm
               (?totalGain - MIN(?totalGain) OVER()) / (MAX(?totalGain) OVER() - MIN(?totalGain) OVER()) AS ?gainNorm
               (?riskScore - MIN(?riskScore) OVER()) / (MAX(?riskScore) OVER() - MIN(?riskScore) OVER()) AS ?riskScoreNorm
               ((?avgShortfall - MIN(?avgShortfall) OVER()) / (MAX(?avgShortfall) OVER() - MIN(?avgShortfall) OVER())) AS ?avgShortfallNorm
        WHERE {
          {
            SELECT ?investorId
                   (SUM(COALESCE(?inflows, 0) - COALESCE(?outflows, 0)) AS ?netCashFlow)
                   (SUM(COALESCE(?gain, 0)) AS ?totalGain)
                   (AVG(?riskScore_) AS ?riskScore)
                   (AVG(?shortfall_) AS ?avgShortfall)
            WHERE {
              BIND(IRI(CONCAT("https://wealth.example.org/investor/", STR(?investorId_))) AS ?investor)
              ?investor wm:investorId ?investorId_ .
              BIND(?investorId_ AS ?investorId)

              OPTIONAL {
                SELECT ?investorId_ (SUM(IF(?amt > 0, ?amt, 0)) AS ?inflows) (SUM(IF(?amt < 0, ABS(?amt), 0)) AS ?outflows)
                WHERE {
                  ?cf wm:cashFlowOfInvestor ?investor .
                  ?cf wm:amount ?amtStr .
                  BIND(xsd:decimal(?amtStr) AS ?amt)
                }
                GROUP BY ?investorId_
              }

              OPTIONAL {
                SELECT ?investorId_ (SUM((xsd:decimal(?cv) - xsd:decimal(?cost))) AS ?gain)
                WHERE {
                  ?ph wm:heldByInvestor ?investor .
                  ?ph wm:currentValue ?cv .
                  ?ph wm:cost ?cost .
                  FILTER(xsd:decimal(?cv) >= 0 && xsd:decimal(?cost) > 0)
                }
                GROUP BY ?investorId_
              }

              OPTIONAL {
                ?ph_ wm:healthOfInvestor ?investor .
                ?ph_ wm:riskScore ?rsStr .
                BIND(xsd:integer(?rsStr) AS ?riskScore_)
              }

              OPTIONAL {
                ?ig wm:belongsToInvestor ?investor .
                ?ig wm:shortfall ?sfStr .
                BIND(xsd:decimal(?sfStr) AS ?shortfall_)
              }
            }
            GROUP BY ?investorId
          }
        }
      }
    }
  }
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
WITH (
  SELECT 
    ?investorId,
    (?netCashFlow - MIN(?netCashFlow) OVER ()) / (MAX(?netCashFlow) OVER () - MIN(?netCashFlow) OVER ()) AS ?normNetCashFlow,
    (?totalRebalanceAmt - MIN(?totalRebalanceAmt) OVER ()) / (MAX(?totalRebalanceAmt) OVER () - MIN(?totalRebalanceAmt) OVER ()) AS ?normRebalanceAmt,
    (?totalSectorInvestment - MIN(?totalSectorInvestment) OVER ()) / (MAX(?totalSectorInvestment) OVER () - MIN(?totalSectorInvestment) OVER ()) AS ?normSectorInvestment,
    (?totalAllocShift - MIN(?totalAllocShift) OVER ()) / (MAX(?totalAllocShift) OVER () - MIN(?totalAllocShift) OVER ()) AS ?normAllocShift
  FROM (
    SELECT 
      ?investorId,
      SUM(COALESCE(?cashFlowVal, 0)) AS ?netCashFlow,
      SUM(COALESCE(?rebalanceAmt, 0)) AS ?totalRebalanceAmt,
      SUM(COALESCE(?sectorInvestment, 0)) AS ?totalSectorInvestment,
      SUM(COALESCE(?allocShift, 0)) AS ?totalAllocShift
    WHERE {
      {
        SELECT ?investorId (SUM(IF(?type IN ("SIP", "Lump Sum", "Deposit"), -?amount, ?amount)) AS ?cashFlowVal)
        WHERE {
          ?cashFlow a wm:CashFlow ;
                    wm:investorId ?investorId ;
                    wm:amount ?amtStr ;
                    wm:type ?typeStr .
          BIND(xsd:decimal(?amtStr) AS ?amount)
          BIND(?typeStr AS ?type)
        }
        GROUP BY ?investorId
      }
      OPTIONAL {
        SELECT ?investorId (SUM(xsd:decimal(?amtStr)) AS ?rebalanceAmt)
        WHERE {
          ?rebalancing a wm:RebalancingAction ;
                      wm:investorId ?investorId ;
                      wm:amount ?amtStr .
        }
        GROUP BY ?investorId
      }
      OPTIONAL {
        SELECT ?investorId (SUM(xsd:decimal(?totalInvStr)) AS ?sectorInvestment)
        WHERE {
          ?sectorAlloc a wm:SectorAllocation ;
                       wm:investorId ?investorId ;
                       wm:totalInvestment ?totalInvStr .
        }
        GROUP BY ?investorId
      }
      OPTIONAL {
        SELECT ?investorId (SUM(xsd:decimal(?newAllocStr) - xsd:decimal(?currAllocStr)) AS ?allocShift)
        WHERE {
          ?scenarioRebal a wm:ScenarioRebalancing ;
                         wm:investorId ?investorId ;
                         wm:currentAllocationPct ?currAllocStr ;
                         wm:newAllocationPct ?newAllocStr .
        }
        GROUP BY ?investorId
      }
    }
    GROUP BY ?investorId
    HAVING (
      bound(?cashFlowVal) &&
      bound(?rebalanceAmt) &&
      bound(?sectorInvestment) &&
      bound(?allocShift)
    )
  )
) AS %NormalizedScores

SELECT ?investorId ((100 * AVG(?compositeScore)) AS ?compositeIndex)
WHERE {
  INCLUDE %NormalizedScores
  BIND((?normNetCashFlow + ?normRebalanceAmt + ?normSectorInvestment + ?normAllocShift) / 4 AS ?compositeScore)
}
GROUP BY ?investorId
ORDER BY DESC(?compositeIndex) ?investorId
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?investorId
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:hasCashFlow ?cashFlow ;
            wm:hasRebalancingAction ?rebalancingAction ;
            wm:hasSectorAllocation ?sectorAllocation ;
            wm:hasInvestmentGoal ?investmentGoal .

  ?cashFlow wm:amount ?cashFlowAmount .
  ?rebalancingAction wm:amount ?rebalanceAmount .
  ?sectorAllocation wm:totalInvestment ?sectorInvestment .
  ?investmentGoal wm:shortfall ?goalShortfall .

  BIND(xsd:decimal(?cashFlowAmount) AS ?netCashFlow)
  BIND(xsd:decimal(?rebalanceAmount) AS ?totalRebalance)
  BIND(xsd:decimal(?sectorInvestment) AS ?totalSectorInvestment)
  BIND(xsd:decimal(?goalShortfall) AS ?avgGoalShortfall)

  BIND((?netCashFlow + ?totalRebalance + ?totalSectorInvestment - ?avgGoalShortfall) AS ?compositeScore)
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId
           ((?netCashFlowNorm + ?rebalanceAmountNorm + ?allocationShiftNorm + ?riskScoreNorm) / 4 * 100 AS ?compositeScore)
    WHERE {
      {
        SELECT ?investorId
               ((?netCashFlow - MIN(?netCashFlow) OVER()) / (MAX(?netCashFlow) OVER() - MIN(?netCashFlow) OVER()) AS ?netCashFlowNorm)
               ((?rebalanceAmount - MIN(?rebalanceAmount) OVER()) / (MAX(?rebalanceAmount) OVER() - MIN(?rebalanceAmount) OVER()) AS ?rebalanceAmountNorm)
               ((?allocationShift - MIN(?allocationShift) OVER()) / (MAX(?allocationShift) OVER() - MIN(?allocationShift) OVER()) AS ?allocationShiftNorm)
               ((?riskScore - MIN(?riskScore) OVER()) / (MAX(?riskScore) OVER() - MIN(?riskScore) OVER()) AS ?riskScoreNorm)
        WHERE {
          {
            SELECT ?investorId
                   (SUM(COALESCE(?cashIn, 0) - COALESCE(?cashOut, 0)) AS ?netCashFlow)
                   (SUM(COALESCE(?rebalanceAmt, 0)) AS ?rebalanceAmount)
                   (SUM(COALESCE(?newAlloc, 0) - COALESCE(?currAlloc, 0)) AS ?allocationShift)
                   (MAX(?riskSc) AS ?riskScore)
            WHERE {
              ?investor a wm:Investor ;
                        wm:investorId ?investorId .

              OPTIONAL {
                ?cf a wm:CashFlow ;
                    wm:cashFlowOfInvestor ?investor ;
                    wm:amount ?amtStr ;
                    wm:type ?cfType .
                BIND(xsd:decimal(?amtStr) AS ?amt)
                FILTER(?cfType IN ("SIP", "Lump Sum", "Deposit"))
                BIND(?amt AS ?cashIn)
              }

              OPTIONAL {
                ?cfRed a wm:CashFlow ;
                       wm:cashFlowOfInvestor ?investor ;
                       wm:amount ?amtRedStr ;
                       wm:type ?cfRedType .
                BIND(xsd:decimal(?amtRedStr) AS ?amtRed)
                FILTER(?cfRedType IN ("Redemption", "Withdrawal"))
                BIND(?amtRed AS ?cashOut)
              }

              OPTIONAL {
                ?ra a wm:RebalancingAction ;
                    wm:rebalancingActionOfInvestor ?investor ;
                    wm:amount ?raAmtStr .
                BIND(xsd:decimal(?raAmtStr) AS ?rebalanceAmt)
              }

              OPTIONAL {
                ?sa a wm:ScenarioRebalancing ;
                    wm:scenarioRebalancingOfInvestor ?investor ;
                    wm:currentAllocationPct ?currAllocStr ;
                    wm:newAllocationPct ?newAllocStr .
                BIND(xsd:decimal(?currAllocStr) AS ?currAllocDec)
                BIND(xsd:decimal(?newAllocStr) AS ?newAllocDec)
                BIND(?newAllocDec - ?currAllocDec AS ?allocDiff)
              }

              OPTIONAL {
                ?ph a wm:PortfolioHealth ;
                    wm:healthOfInvestor ?investor ;
                    wm:riskScore ?rsStr .
                BIND(xsd:decimal(?rsStr) AS ?riskSc)
              }

              BIND(COALESCE(?cashIn, 0) - COALESCE(?cashOut, 0) AS ?netCashFlowTemp)
              BIND(COALESCE(?rebalanceAmt, 0) AS ?rebalanceAmountTemp)
              BIND(COALESCE(?allocDiff, 0) AS ?allocationShiftTemp)
              BIND(COALESCE(?riskSc, 0) AS ?riskScoreTemp)
            }
            GROUP BY ?investorId
            HAVING (
              COUNT(?cashIn) >= 0 &&
              COUNT(?cashOut) >= 0 &&
              COUNT(?rebalanceAmt) >= 0 &&
              COUNT(?allocDiff) >= 0 &&
              COUNT(?riskSc) >= 0
            )
          }
        }
      }
    }
  }
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId
           ((100 * (?normNetCashFlow + ?normTotalRebalanceAmount + ?normTotalScenarioShift + (1 - ?normAvgGoalShortfall)) / 4) AS ?compositeScore)
    WHERE {
      {
        SELECT ?investorId
               ((?netCashFlow - ?minNetCashFlow) / (?maxNetCashFlow - ?minNetCashFlow) AS ?normNetCashFlow)
               ((?totalRebalanceAmount - ?minRebalance) / (?maxRebalance - ?minRebalance) AS ?normTotalRebalanceAmount)
               ((?totalScenarioShift - ?minScenarioShift) / (?maxScenarioShift - ?minScenarioShift) AS ?normTotalScenarioShift)
               ((?avgGoalShortfall - ?minShortfall) / (?maxShortfall - ?minShortfall) AS ?normAvgGoalShortfall)
        WHERE {
          {
            SELECT ?investorId
                   (SUM(xsd:decimal(?cashFlowAmount)) AS ?netCashFlow)
            WHERE {
              ?cashFlow wm:cashFlowOfInvestor ?investor .
              ?investor wm:investorId ?investorId .
              ?cashFlow wm:amount ?cashFlowAmount .
              FILTER (?cashFlowAmount != "")
            }
            GROUP BY ?investorId
          }
          {
            SELECT ?investorId
                   (SUM(xsd:decimal(?rebalanceAmount)) AS ?totalRebalanceAmount)
            WHERE {
              ?rebalancing wm:rebalancingActionOfInvestor ?investor .
              ?investor wm:investorId ?investorId .
              ?rebalancing wm:amount ?rebalanceAmount .
              FILTER (?rebalanceAmount != "")
            }
            GROUP BY ?investorId
          }
          {
            SELECT ?investorId
                   (SUM(xsd:decimal(?newAlloc) - xsd:decimal(?currAlloc)) AS ?totalScenarioShift)
            WHERE {
              ?scenario wm:scenarioRebalancingOfInvestor ?investor .
              ?investor wm:investorId ?investorId .
              ?scenario wm:newAllocationPct ?newAlloc ;
                        wm:currentAllocationPct ?currAlloc .
              FILTER (?newAlloc != "" && ?currAlloc != "")
            }
            GROUP BY ?investorId
          }
          {
            SELECT ?investorId
                   (AVG(xsd:decimal(?shortfall)) AS ?avgGoalShortfall)
            WHERE {
              ?goal wm:belongsToInvestor ?investor .
              ?investor wm:investorId ?investorId .
              ?goal wm:shortfall ?shortfall .
              FILTER (?shortfall != "")
            }
            GROUP BY ?investorId
          }
          BIND (
            MIN(?netCashFlow) OVER () AS ?minNetCashFlow
          )
          BIND (
            MAX(?netCashFlow) OVER () AS ?maxNetCashFlow
          )
          BIND (
            MIN(?totalRebalanceAmount) OVER () AS ?minRebalance
          )
          BIND (
            MAX(?totalRebalanceAmount) OVER () AS ?maxRebalance
          )
          BIND (
            MIN(?totalScenarioShift) OVER () AS ?minScenarioShift
          )
          BIND (
            MAX(?totalScenarioShift) OVER () AS ?maxScenarioShift
          )
          BIND (
            MIN(?avgGoalShortfall) OVER () AS ?minShortfall
          )
          BIND (
            MAX(?avgGoalShortfall) OVER () AS ?maxShortfall
          )
        }
      }
    }
  }
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?riskTolerance
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:riskTolerance ?riskTolerance .
  FILTER (?riskTolerance NOT IN ("Aggressive", "Conservative", "Moderate"))
}

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?timeHorizon
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:timeHorizon ?timeHorizon .
  FILTER (?timeHorizon NOT IN ("Long-term", "Medium-term", "Short-term"))
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId
           (100 * (
              (?netCashFlowNorm) +
              (?totalSectorInvestmentNorm) +
              (?allocationShiftNorm) +
              (?riskScoreNorm)
            ) / 4 AS ?compositeScore)
    WHERE {
      {
        SELECT ?investorId
               ((?netCashFlow - MIN(?netCashFlow) OVER()) / (MAX(?netCashFlow) OVER() - MIN(?netCashFlow) OVER()) AS ?netCashFlowNorm)
               ((?totalSectorInvestment - MIN(?totalSectorInvestment) OVER()) / (MAX(?totalSectorInvestment) OVER() - MIN(?totalSectorInvestment) OVER()) AS ?totalSectorInvestmentNorm)
               ((?allocationShift - MIN(?allocationShift) OVER()) / (MAX(?allocationShift) OVER() - MIN(?allocationShift) OVER()) AS ?allocationShiftNorm)
               ((?riskScore - MIN(?riskScore) OVER()) / (MAX(?riskScore) OVER() - MIN(?riskScore) OVER()) AS ?riskScoreNorm)
        WHERE {
          {
            SELECT ?investorId
                   (SUM(COALESCE(?cashIn, 0) - COALESCE(?cashOut, 0)) AS ?netCashFlow)
                   (SUM(?sectorTotal) AS ?totalSectorInvestment)
                   (SUM(?shift) AS ?allocationShift)
                   (MAX(?riskScoreVal) AS ?riskScore)
            WHERE {
              {
                SELECT ?investorId (SUM(IF(?type IN ("SIP", "Lump Sum", "Deposit"), ?amount, 0)) AS ?cashIn)
                               (SUM(IF(?type IN ("Redemption", "Withdrawal"), ?amount, 0)) AS ?cashOut)
                WHERE {
                  ?cashFlow a wm:CashFlow ;
                            wm:investorId ?investorId ;
                            wm:amount ?amountStr ;
                            wm:type ?type .
                  BIND(xsd:decimal(?amountStr) AS ?amount)
                }
                GROUP BY ?investorId
              }
              OPTIONAL {
                ?sectorAlloc a wm:SectorAllocation ;
                             wm:investorId ?investorId ;
                             wm:totalInvestment ?sectorTotalStr .
                BIND(xsd:decimal(?sectorTotalStr) AS ?sectorTotal)
              }
              OPTIONAL {
                ?scenario a wm:ScenarioRebalancing ;
                          wm:investorId ?investorId ;
                          wm:currentAllocationPct ?currStr ;
                          wm:newAllocationPct ?newStr .
                BIND(xsd:decimal(?currStr) AS ?curr)
                BIND(xsd:decimal(?newStr) AS ?new)
                BIND((?new - ?curr) AS ?shift)
              }
              OPTIONAL {
                ?health a wm:PortfolioHealth ;
                        wm:investorId ?investorId ;
                        wm:riskScore ?riskScoreStr .
                BIND(xsd:decimal(?riskScoreStr) AS ?riskScoreVal)
              }
            }
            GROUP BY ?investorId
            HAVING (BOUND(?cashIn) && BOUND(?cashOut) && BOUND(?sectorTotal) && BOUND(?shift) && BOUND(?riskScoreVal))
          }
        }
      }
    }
  }
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT DISTINCT ?investorId ?category
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:category ?category .
  FILTER (?category NOT IN ("Debt", "Equity", "Gold", "Hybrid", "Real Estate"))
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
