SELECT ?investorId ?segment
WHERE {
  ?investor wm:investorId ?investorId ;
            wm:hasSegment ?segmentEntity .
  ?segmentEntity rdfs:label ?segment .
  FILTER (?segment NOT IN ("Diversified", "Large Cap", "Mid Cap", "Small Cap"))
}

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT DISTINCT ?investorId ?investmentGoal
WHERE {
  ?investor wm:hasInvestmentGoal ?goal .
  ?goal wm:investmentGoal ?investmentGoal .
  FILTER NOT EXISTS {
    VALUES ?allowedGoal { "Child Education" "Emergency Fund" "Growth" "Income Generation" "Retirement Planning" "Wealth Preservation" }
    FILTER (?investmentGoal = ?allowedGoal)
  }
  BIND(STRAFTER(STR(?investor), "#") AS ?investorId)
}

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?holdingId ?investmentType
WHERE {
  ?holding a wm:PortfolioHolding ;
           wm:holdingId ?holdingId ;
           wm:investmentType ?investmentType .
  FILTER(?investmentType NOT IN (
    "Corporate Bond", "ETF", "Equity", "Global Equity", "Gold",
    "Government Bond", "Hedge Fund", "InVIT", "Index Fund",
    "Mutual Fund", "Private Equity", "REIT", "Real Estate", "Venture Capital"
  ))
}

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?holdingId ?sector
WHERE {
  ?holding a wm:PortfolioHolding ;
           wm:holdingId ?holdingId ;
           wm:sector ?sector .
  FILTER NOT EXISTS {
    VALUES ?allowedSector { "Automobile" "Banking" "Consumer Goods" "Corporate" "Financial Services" "Government" "Healthcare" "Infrastructure" "Pharma" "Private Equity" "Real Estate" "Technology" }
    FILTER (?sector = ?allowedSector)
  }
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId
           ((100 * (?normNetCashFlow + ?normTotalRebalance + ?normRiskScore + (1 - ?normAvgShortfall)) / 4) AS ?compositeScore)
    WHERE {
      {
        SELECT ?investorId
               ((?netCashFlow - ?minNetCashFlow) / (?maxNetCashFlow - ?minNetCashFlow) AS ?normNetCashFlow)
               ((?totalRebalance - ?minTotalRebalance) / (?maxTotalRebalance - ?minTotalRebalance) AS ?normTotalRebalance)
               ((?riskScore - ?minRiskScore) / (?maxRiskScore - ?minRiskScore) AS ?normRiskScore)
               ((?avgShortfall - ?minAvgShortfall) / (?maxAvgShortfall - ?minAvgShortfall) AS ?normAvgShortfall)
        WHERE {
          {
            SELECT ?investorId
                   (SUM(xsd:decimal(?cfAmount)) AS ?netCashFlow)
            WHERE {
              ?cashFlow wm:cashFlowOfInvestor ?investor .
              ?investor wm:investorId ?investorId .
              ?cashFlow wm:amount ?cfAmount .
              ?cashFlow wm:type ?cfType .
              FILTER (?cfType IN ("SIP", "Lump Sum", "Deposit", "Redemption", "Withdrawal"))
            }
            GROUP BY ?investorId
          }
          {
            SELECT ?investorId
                   (SUM(xsd:decimal(?raAmount)) AS ?totalRebalance)
            WHERE {
              ?ra wm:rebalancingActionOfInvestor ?investor .
              ?investor wm:investorId ?investorId .
              ?ra wm:amount ?raAmount .
            }
            GROUP BY ?investorId
          }
          {
            SELECT ?investorId
                   (xsd:decimal(?phRiskScore) AS ?riskScore)
            WHERE {
              ?ph wm:healthOfInvestor ?investor .
              ?investor wm:investorId ?investorId .
              ?ph wm:riskScore ?phRiskScore .
            }
            GROUP BY ?investorId ?phRiskScore
          }
          {
            SELECT ?investorId
                   (AVG(xsd:decimal(?igShortfall)) AS ?avgShortfall)
            WHERE {
              ?ig wm:belongsToInvestor ?investor .
              ?investor wm:investorId ?investorId .
              ?ig wm:shortfall ?igShortfall .
            }
            GROUP BY ?investorId
          }

          BIND((SELECT MIN(?ncf) WHERE {
                  SELECT ?investorId (SUM(xsd:decimal(?cfAmount)) AS ?ncf)
                  WHERE {
                    ?cashFlow wm:cashFlowOfInvestor ?investor .
                    ?investor wm:investorId ?investorId .
                    ?cashFlow wm:amount ?cfAmount .
                    ?cashFlow wm:type ?cfType .
                    FILTER (?cfType IN ("SIP", "Lump Sum", "Deposit", "Redemption", "Withdrawal"))
                  }
                  GROUP BY ?investorId
                }) AS ?minNetCashFlow)
          BIND((SELECT MAX(?ncf) WHERE {
                  SELECT ?investorId (SUM(xsd:decimal(?cfAmount)) AS ?ncf)
                  WHERE {
                    ?cashFlow wm:cashFlowOfInvestor ?investor .
                    ?investor wm:investorId ?investorId .
                    ?cashFlow wm:amount ?cfAmount .
                    ?cashFlow wm:type ?cfType .
                    FILTER (?cfType IN ("SIP", "Lump Sum", "Deposit", "Redemption", "Withdrawal"))
                  }
                  GROUP BY ?investorId
                }) AS ?maxNetCashFlow)

          BIND((SELECT MIN(?tr) WHERE {
                  SELECT ?investorId (SUM(xsd:decimal(?raAmount)) AS ?tr)
                  WHERE {
                    ?ra wm:rebalancingActionOfInvestor ?investor .
                    ?investor wm:investorId ?investorId .
                    ?ra wm:amount ?raAmount .
                  }
                  GROUP BY ?investorId
                }) AS ?minTotalRebalance)
          BIND((SELECT MAX(?tr) WHERE {
                  SELECT ?investorId (SUM(xsd:decimal(?raAmount)) AS ?tr)
                  WHERE {
                    ?ra wm:rebalancingActionOfInvestor ?investor .
                    ?investor wm:investorId ?investorId .
                    ?ra wm:amount ?raAmount .
                  }
                  GROUP BY ?investorId
                }) AS ?maxTotalRebalance)

          BIND((SELECT MIN(xsd:decimal(?rs)) WHERE {
                  ?ph wm:healthOfInvestor ?investor .
                  ?investor wm:investorId ?investorId .
                  ?ph wm:riskScore ?rs .
                }) AS ?minRiskScore)
          BIND((SELECT MAX(xsd:decimal(?rs)) WHERE {
                  ?ph wm:healthOfInvestor ?investor .
                  ?investor wm:investorId ?investorId .
                  ?ph wm:riskScore ?rs .
                }) AS ?maxRiskScore)

          BIND((SELECT MIN(AVG(xsd:decimal(?sf))) WHERE {
                  ?ig wm:belongsToInvestor ?investor .
                  ?investor wm:investorId ?investorId .
                  ?ig wm:shortfall ?sf .
                } GROUP BY ?investorId) AS ?minAvgShortfall)
          BIND((SELECT MAX(AVG(xsd:decimal(?sf))) WHERE {
                  ?ig wm:belongsToInvestor ?investor .
                  ?investor wm:investorId ?investorId .
                  ?ig wm:shortfall ?sf .
                } GROUP BY ?investorId) AS ?maxAvgShortfall)
        }
      }
    }
  }
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

