PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?timeHorizon (ROUND(AVG(?sharpeRatio), 2) AS ?avgSharpeRatio)
WHERE {
  ?investor wm:hasPortfolioHealth ?health ;
            wm:hasTimeHorizon ?timeHorizonEntity .

  ?health wm:riskScore ?riskScore ;
          wm:avgSharpeRatio ?sharpeRatio .

  FILTER (?riskScore > 50)

  ?timeHorizonEntity rdfs:label ?timeHorizon .
}
GROUP BY ?timeHorizon
ORDER BY ?timeHorizon

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT DISTINCT ?investor
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?riskTolerance ;
            wm:hasInvestmentGoal ?goal .

  ?riskTolerance rdfs:label "Moderate" .

  ?goal wm:avgAnnualReturnPct ?return .
  FILTER(xsd:decimal(?return) > 35)

  ?health wm:healthOfInvestor ?investor ;
          wm:riskScore ?riskScore .
  FILTER(xsd:integer(?riskScore) > 50)
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?timeHorizonLabel AS ?group_value
  (ROUND(AVG(?annualReturnPct), 2) AS ?avg_annual_return_pct)
  (COUNT(DISTINCT ?investor) AS ?n_investors)
WHERE {
  ?investor a wm:Investor ;
            wm:hasPortfolioHealth ?health ;
            wm:hasTimeHorizon ?timeHorizon .

  ?health wm:riskScore ?riskScore .
  FILTER (?riskScore > 50)

  ?timeHorizon rdfs:label ?timeHorizonLabel .

  OPTIONAL {
    ?goal wm:belongsToInvestor ?investor ;
          wm:avgAnnualReturnPct ?annualReturnPct .
  }
}
GROUP BY ?timeHorizonLabel
ORDER BY ?timeHorizonLabel

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investor
WHERE {
  ?investor a wm:Investor ;
            wm:segment "Diversified" ;
            wm:hasInvestmentGoal ?goal ;
            wm:hasPortfolioHealth ?health .

  ?goal wm:progressPct ?progressPct .
  ?health wm:diversificationScore ?diversificationScore .

  {
    SELECT ?investor (AVG(?progressPct_) AS ?avgProgressPct)
    WHERE {
      ?investor wm:hasInvestmentGoal ?goal_ .
      ?goal_ wm:progressPct ?progressPct_ .
    }
    GROUP BY ?investor
  }

  FILTER (?avgProgressPct < 30 && ?diversificationScore < 50)
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?investorId
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:hasRiskTolerance ?rt ;
            wm:hasInvestmentGoal ?goal ;
            wm:hasHolding ?holding ;
            wm:hasPortfolioHealth ?health .

  ?rt rdfs:label "Aggressive" .

  ?goal wm:progressPct ?progress .
  FILTER(xsd:decimal(?progress) < 30)

  ?holding wm:cost ?cost ;
           wm:currentValue ?currentValue ;
           wm:returnsPct ?returns .
  FILTER(xsd:decimal(?cost) > 0 && xsd:decimal(?currentValue) >= 0)
  FILTER(xsd:decimal(?returns) > 50)

  ?health wm:riskScore ?riskScore .
  FILTER(xsd:decimal(?riskScore) > 50)
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?investorId ?avgSharpeRatio ?avgDividends
WHERE {
  ?investor wm:hasInvestmentGoal ?goal .
  ?goal wm:avgSharpeRatio ?sharpeRatio .

  ?investor wm:hasPortfolioHealth ?health .
  ?health wm:goalMatchPct ?goalMatchPct .

  FILTER(?goalMatchPct > 50)

  OPTIONAL { 
    ?investor wm:hasHolding ?holding .
    ?holding wm:dividends ?dividend .
  }

  BIND(xsd:decimal(?sharpeRatio) AS ?sharpeRatioVal)
  BIND(xsd:decimal(?dividend) AS ?dividendVal)

  {
    SELECT ?investor
           (AVG(?sharpeRatioVal) AS ?avgSharpeRatio)
           (AVG(?dividendVal) AS ?avgDividends)
    WHERE {
      ?investor wm:hasInvestmentGoal ?goal .
      ?goal wm:avgSharpeRatio ?sharpeRatioVal .

      OPTIONAL { 
        ?investor wm:hasHolding ?holding .
        ?holding wm:dividends ?dividendVal .
      }
    }
    GROUP BY ?investor
  }
}
ORDER BY ASC(?avgSharpeRatio)
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskToleranceLabel AS ?risk_tolerance,
  ROUND(AVG(?returnsPct), 2) AS ?avg_return
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?riskTolerance ;
            wm:hasInvestmentGoal ?goal ;
            wm:hasPortfolioHealth ?health ;
            wm:hasHolding ?holding .

  ?riskTolerance rdfs:label ?riskToleranceLabel .

  ?goal wm:progressPct ?progressPct .
  FILTER (?progressPct > 30)

  ?health wm:riskScore ?riskScore .
  FILTER (?riskScore > 50)

  ?holding wm:returnsPct ?returnsPct ;
           wm:cost ?cost ;
           wm:currentValue ?currentValue .
  FILTER (?cost > 0 && ?currentValue >= 0)
}
GROUP BY ?riskToleranceLabel
ORDER BY ?riskToleranceLabel

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?investorId ?avgProgressPct ?avgDividends
WHERE {
  {
    SELECT ?investorId
           (AVG(?progressPct) AS ?avgProgressPct)
           (AVG(?dividends) AS ?avgDividends)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?investor ;
            wm:progressPct ?progressPct .

      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:dividends ?dividends .

      ?health a wm:PortfolioHealth ;
              wm:healthOfInvestor ?investor ;
              wm:goalMatchPct ?goalMatchPct .

      FILTER (?goalMatchPct > 50)
      BIND (STR(?investor) AS ?investorId)
    }
    GROUP BY ?investorId
  }
}
ORDER BY ASC(?avgProgressPct)
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT 
  ?segment 
  (ROUND(AVG(?returnsPct), 2) AS ?avgHoldingReturn)
WHERE {
  ?investor wm:hasSegment ?segment ;
            wm:hasInvestmentGoal ?goal ;
            wm:hasPortfolioHealth ?health ;
            wm:hasHolding ?holding .

  ?goal wm:progressPct ?progressPct .
  ?health wm:riskScore ?riskScore .
  ?holding wm:returnsPct ?returnsPct ;
           wm:cost ?cost ;
           wm:currentValue ?currentValue .

  FILTER (?progressPct > 30 && ?riskScore > 50 && ?cost > 0 && ?currentValue >= 0)
}
GROUP BY ?segment
ORDER BY ?segment

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investor
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?riskTolerance ;
            wm:hasInvestmentGoal ?investmentGoal ;
            wm:hasHolding ?holding ;
            wm:hasPortfolioHealth ?portfolioHealth .

  ?riskTolerance rdfs:label "Aggressive" .

  ?investmentGoal wm:avgSharpeRatio ?sharpeRatio .
  FILTER(xsd:decimal(?sharpeRatio) > 0.0)

  ?holding wm:dividends ?dividends .
  BIND(xsd:decimal(?dividends) AS ?dividendValue)

  ?portfolioHealth wm:goalMatchPct ?goalMatchPct .
  BIND(xsd:decimal(?goalMatchPct) AS ?goalMatchValue)
  FILTER(?goalMatchValue > 50)

  {
    SELECT ?investor (AVG(?sharpeRatioValue) AS ?avgSharpe) (SUM(?dividendValue) AS ?totalDividends)
    WHERE {
      ?investor wm:hasInvestmentGoal ?investmentGoal ;
                wm:hasHolding ?holding .

      ?investmentGoal wm:avgSharpeRatio ?sharpeRatio .
      BIND(xsd:decimal(?sharpeRatio) AS ?sharpeRatioValue)

      ?holding wm:dividends ?dividends .
      BIND(xsd:decimal(?dividends) AS ?dividendValue)
    }
    GROUP BY ?investor
  }

  FILTER(?avgSharpe > 0.0 && ?totalDividends > 14000)
}

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investor
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance wm:Aggressive .

  OPTIONAL {
    ?goal wm:belongsToInvestor ?investor ;
          wm:progressPct ?progressPct .
  }
  BIND(COALESCE(AVG(?progressPct), 0) AS ?avgGoalProgress)

  OPTIONAL {
    ?holding wm:heldByInvestor ?investor ;
             wm:dividends ?dividends .
  }
  BIND(COALESCE(AVG(?dividends), 0) AS ?avgDividends)

  OPTIONAL {
    ?health wm:healthOfInvestor ?investor ;
            wm:liquidityScore ?liquidityScore .
  }

  FILTER(?avgGoalProgress > 30 &&
         ?avgDividends < 14000 &&
         ?liquidityScore < 50)
}
GROUP BY ?investor

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?timeHorizon (ROUND(AVG(?returnsPct), 2) AS ?avgHoldingReturn)
WHERE {
  ?investor wm:hasInvestmentGoal ?goal ;
            wm:hasPortfolioHealth ?health ;
            wm:hasHolding ?holding ;
            wm:hasTimeHorizon ?th .

  ?th rdfs:label ?timeHorizon .

  ?goal wm:progressPct ?progressPct .
  ?health wm:riskScore ?riskScore .

  ?holding wm:returnsPct ?returnsPct ;
           wm:cost ?cost ;
           wm:currentValue ?currentValue .

  FILTER (?progressPct > 30 && ?riskScore > 50 && ?cost > 0 && ?currentValue >= 0)
}
GROUP BY ?timeHorizon
ORDER BY ?timeHorizon

