GROUP BY ?segment

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT 
  ?riskTolerance AS ?group_value
  (ROUND(AVG(?dividends)) AS ?avg_dividends)
  (COUNT(DISTINCT ?investorId) AS ?n_investors)
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:riskTolerance ?riskTolerance ;
            wm:hasInvestmentGoal ?goal ;
            wm:hasHolding ?holding ;
            wm:hasPortfolioHealth ?health .

  ?goal wm:avgSharpeRatio ?sharpe .
  FILTER(xsd:decimal(?sharpe) > 0.0)

  ?health wm:goalMatchPct ?gmp .
  FILTER(xsd:decimal(?gmp) > 50)

  ?holding wm:dividends ?dividends .
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investor
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?riskTolerance ;
            wm:hasInvestmentGoal ?investmentGoal ;
            wm:hasHolding ?holding .

  ?riskTolerance rdfs:label "Conservative" .

  ?investmentGoal wm:avgSharpeRatio ?sharpeRatio ;
                  wm:goalMatchPct ?goalMatchPct .

  ?holding wm:dividends ?dividend .

  FILTER (?sharpeRatio > 0.0)

  {
    SELECT ?investor (AVG(?dividend) AS ?avgDividend) (AVG(?goalMatchPct) AS ?avgGoalMatchPct)
    WHERE {
      ?investor wm:hasInvestmentGoal ?investmentGoal ;
                wm:hasHolding ?holding .

      ?investmentGoal wm:goalMatchPct ?goalMatchPct .
      ?holding wm:dividends ?dividend .
    }
    GROUP BY ?investor
  }

  FILTER (?avgDividend > 14000 && ?avgGoalMatchPct > 50)
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT (SUM(xsd:decimal(?amount)) AS ?totalDepositAmount)
WHERE {
  ?cashFlow a wm:CashFlow ;
            wm:type "Deposit" ;
            wm:amount ?amount .
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT (SUM(xsd:decimal(?amount)) AS ?netCashFlow)
WHERE {
  ?cashFlow a wm:CashFlow ;
            wm:date ?date ;
            wm:amount ?amount .
  FILTER(?date >= "2021-01-01" && ?date <= "2021-12-31")
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?totalNetCashFlow)
WHERE {
  ?cashFlow a wm:CashFlow ;
            wm:investorId ?investorId ;
            wm:amount ?amount ;
            wm:type ?type .
  FILTER(?type IN ("SIP", "Lump Sum", "Deposit", "Redemption", "Withdrawal"))
}
GROUP BY ?investorId
ORDER BY DESC(?totalNetCashFlow)
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?investorId
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:hasRiskTolerance ?riskTolerance ;
            wm:hasInvestmentGoal ?goal ;
            wm:hasHolding ?holding ;
            wm:hasPortfolioHealth ?health .

  ?riskTolerance rdfs:label "Conservative" .

  ?goal wm:progressPct ?progressPct .
  ?holding wm:dividends ?dividends .
  ?health wm:liquidityScore ?liquidityScore .

  BIND(xsd:decimal(?progressPct) AS ?progress)
  BIND(xsd:decimal(?dividends) AS ?dividend)
  BIND(xsd:decimal(?liquidityScore) AS ?liquidity)

  FILTER(?liquidity < 50)

  {
    SELECT ?investor (AVG(?progress) AS ?avgProgress) (AVG(?dividend) AS ?avgDividends)
    WHERE {
      ?investor wm:hasInvestmentGoal ?goal ;
                wm:hasHolding ?holding .

      ?goal wm:progressPct ?progressPct .
      ?holding wm:dividends ?dividends .

      BIND(xsd:decimal(?progressPct) AS ?progress)
      BIND(xsd:decimal(?dividends) AS ?dividend)
    }
    GROUP BY ?investor
  }

  FILTER(?avgProgress > 30)
  FILTER(?avgDividends < 14000)
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT (SUM(xsd:decimal(?amount)) AS ?totalTransactionAmount)
WHERE {
  ?cashFlow a wm:CashFlow ;
            wm:type "Dividend Reinvestment" ;
            wm:amount ?amount .
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT DISTINCT ?investor
WHERE {
  ?cashFlow wm:cashFlowOfInvestor ?investor ;
            wm:date ?date ;
            wm:amount ?amount ;
            wm:type ?type .

  FILTER (
    ?date >= "2024-01-01" &&
    ?date <= "2024-12-31"
  )

  BIND(
    IF(?type IN ("Withdrawal", "Redemption"), xsd:decimal(?amount), 0) AS ?outflow
  )
  BIND(
    IF(?type IN ("SIP", "Lump Sum", "Deposit"), xsd:decimal(?amount), 0) AS ?inflow
  )
}
GROUP BY ?investor
HAVING (
  SUM(?inflow) - SUM(?outflow) < 0
)

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT (SUM(?amount) AS ?netCashFlow)
WHERE {
  ?cashFlow a wm:CashFlow ;
            wm:date ?date ;
            wm:amount ?amount .
  FILTER (?date >= "2022-01-01" && ?date <= "2022-12-31")
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?netCashFlow)
WHERE {
  ?cashFlow a wm:CashFlow ;
            wm:investorId ?investorId ;
            wm:amount ?amount ;
            wm:type ?type .
  FILTER(?type IN ("SIP", "Lump Sum", "Deposit", "Redemption", "Withdrawal"))
}
GROUP BY ?investorId
ORDER BY ASC(?netCashFlow)
LIMIT 10

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
