WHERE {
  ?cashFlow a wm:CashFlow ;
            wm:hasCashFlowType ?cashFlowType ;
            wm:amount ?amount .
  ?cashFlowType rdfs:label "Interest Credit" .
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT (SUM(xsd:decimal(?amount)) AS ?netCashFlow)
WHERE {
  ?cashFlow a wm:CashFlow ;
            wm:date ?date ;
            wm:amount ?amount .
  FILTER(?date >= "2023-01-01" && ?date <= "2023-12-31")
}

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId (COUNT(?cashFlowId) AS ?transactionCount)
WHERE {
  ?cashFlow wm:cashFlowId ?cashFlowId ;
            wm:investorId ?investorId .
}
GROUP BY ?investorId
ORDER BY DESC(?transactionCount) ASC(?investorId)
LIMIT 10

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investor
WHERE {
  ?cashFlow wm:cashFlowOfInvestor ?investor ;
            wm:amount ?amount ;
            wm:hasCashFlowType ?type .
  ?type rdfs:label "Deposit" .
}
GROUP BY ?investor
HAVING (SUM(xsd:decimal(?amount)) > 100000)

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT (SUM(xsd:decimal(?amount)) AS ?totalLumpSumAmount)
WHERE {
  ?cashFlow a wm:CashFlow ;
            wm:type "Lump Sum" ;
            wm:amount ?amount .
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT DISTINCT ?investor
WHERE {
  ?cashFlow wm:cashFlowOfInvestor ?investor ;
            wm:date ?date ;
            wm:amount ?amount ;
            wm:type ?type .

  FILTER (
    ?date >= "2025-01-01" &&
    ?date <= "2025-12-31"
  )

  BIND(
    IF(?type IN ("SIP", "Lump Sum", "Deposit"), -1 * xsd:decimal(?amount),
       IF(?type IN ("Redemption", "Withdrawal"), xsd:decimal(?amount), 0)
    ) AS ?signedAmount
  )

  {
    SELECT ?investor (SUM(?signedAmount) AS ?netCashFlow)
    WHERE {
      ?cashFlow wm:cashFlowOfInvestor ?investor ;
                wm:date ?date ;
                wm:amount ?amount ;
                wm:type ?type .

      FILTER (
        ?date >= "2025-01-01" &&
        ?date <= "2025-12-31"
      )

      BIND(
        IF(?type IN ("SIP", "Lump Sum", "Deposit"), -1 * xsd:decimal(?amount),
           IF(?type IN ("Redemption", "Withdrawal"), xsd:decimal(?amount), 0)
        ) AS ?signedAmount
      )
    }
    GROUP BY ?investor
  }

  FILTER (?netCashFlow < 0)
}

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT (SUM(?amount) AS ?netCashFlow)
