PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT (SUM(xsd:decimal(?amount)) AS ?totalNetCashFlow)
WHERE {
  ?cashFlow a wm:CashFlow ;
            wm:cashFlowOfInvestor ?investor ;
            wm:amount ?amount ;
            wm:type ?type .

  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?riskTolerance .

  ?riskTolerance rdfs:label "Aggressive" .

  BIND(IF(?type IN ("SIP", "Lump Sum", "Deposit"), -xsd:decimal(?amount), xsd:decimal(?amount)) AS ?signedAmount)
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (SUM(?amount) AS ?netCashFlow)
WHERE {
  ?cashFlow a wm:CashFlow ;
            wm:cashFlowOfInvestor ?investor ;
            wm:amount ?amountStr ;
            wm:date ?dateStr ;
            wm:type ?type .

  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?riskTolerance .

  ?riskTolerance rdfs:label "Aggressive" .

  BIND(xsd:decimal(?amountStr) AS ?amount)
  BIND(xsd:date(?dateStr) AS ?date)

  FILTER((?date >= "2024-01-01"^^xsd:date) && (?date <= "2024-12-31"^^xsd:date))

  # Inflows are negative for XIRR; outflows are positive
  BIND(
    IF(?type IN ("SIP", "Lump Sum", "Deposit"),
       -?amount,   # inflow
       ?amount     # outflow (Redemption/Withdrawal)
    ) AS ?signedAmount
  )
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?investorName (SUM(xsd:decimal(?amount)) AS ?netCashFlow)
WHERE {
  ?cashFlow a wm:CashFlow ;
            wm:cashFlowOfInvestor ?investor ;
            wm:amount ?amount ;
            wm:type ?type .

  ?investor wm:investorName ?investorName .

  FILTER (?type IN ("SIP", "Lump Sum", "Deposit", "Redemption", "Withdrawal"))
}
GROUP BY ?investorName
ORDER BY DESC(?netCashFlow)
LIMIT 10

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT SUM(xsd:decimal(?amount)) AS ?totalNetCashFlow
WHERE {
  ?cashFlow a wm:CashFlow ;
            wm:cashFlowOfInvestor ?investor ;
            wm:amount ?amount ;
            wm:type ?type .

  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?riskTolerance .

  ?riskTolerance rdfs:label "Conservative" .

  FILTER (?type IN ("SIP", "Lump Sum", "Deposit", "Redemption", "Withdrawal"))
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT DISTINCT ?investorName
WHERE {
  ?investor a wm:Investor ;
            wm:investorName ?investorName ;
            wm:hasRiskTolerance ?riskTolerance ;
            wm:hasCashFlow ?cashFlow .

  ?riskTolerance rdfs:label "Aggressive" .

  ?cashFlow wm:date ?cashFlowDate ;
            wm:amount ?amount ;
            wm:hasCashFlowType ?cashFlowType .

  ?cashFlowType rdfs:label ?typeLabel .

  BIND(IF(?typeLabel IN ("SIP", "Lump Sum", "Deposit"), -1 * xsd:decimal(?amount), xsd:decimal(?amount)) AS ?netAmount)

  FILTER(?cashFlowDate >= "2025-01-01" && ?cashFlowDate <= "2025-12-31")
}
GROUP BY ?investor ?investorName
HAVING (SUM(?netAmount) < 0)

