  ?cashFlow wm:cashFlowOfInvestor ?investor ;
            wm:amount ?amountStr ;
            wm:date ?dateStr ;
            wm:type ?type .

  ?investor wm:hasRiskTolerance ?riskTolerance .
  ?riskTolerance rdfs:label "Conservative" .

  BIND(xsd:decimal(REPLACE(?amountStr, ",", "")) AS ?amount)
  BIND(xsd:date(?dateStr) AS ?date)

  FILTER((?date >= "2024-01-01"^^xsd:date) && (?date <= "2024-12-31"^^xsd:date))

  BIND(
    IF(?type IN ("SIP", "Lump Sum", "Deposit"), -?amount,
       IF(?type IN ("Redemption", "Withdrawal"), ?amount, 0)
    ) AS ?signedAmount
  )
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wm: <https://wealth.example.org/ontology/>
