WHERE {
  ?investor a wm:Investor ;
            wm:investorName ?investorName ;
            wm:hasRiskTolerance ?riskTolerance .

  ?riskTolerance rdfs:label "Conservative" .

  OPTIONAL {
    ?cashFlow a wm:CashFlow ;
              wm:cashFlowOfInvestor ?investor ;
              wm:date ?date ;
              wm:amount ?amountStr ;
              wm:hasCashFlowType ?cashFlowType .

    BIND(xsd:decimal(?amountStr) AS ?amount)
    BIND(xsd:date(?date) AS ?flowDate)

    FILTER((?flowDate >= "2025-01-01"^^xsd:date) && (?flowDate <= "2025-12-31"^^xsd:date))

    ?cashFlowType rdfs:label ?typeLabel .
  }

  BIND(IF(?typeLabel IN ("SIP", "Lump Sum", "Deposit"), -?amount, ?amount) AS ?signedAmount)

}
GROUP BY ?investor ?investorName
HAVING (SUM(?signedAmount) < 0)

