PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (SUM(?amount) AS ?netCashFlow)
WHERE {
  ?cashFlow a wm:CashFlow ;
            wm:cashFlowOfInvestor ?investor ;
            wm:amount ?amountStr ;
            wm:date ?dateStr ;
            wm:type ?type .

  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?riskTolerance .

  ?riskTolerance rdfs:label "Moderate" .

  BIND(xsd:decimal(?amountStr) AS ?amount)
  BIND(xsd:date(?dateStr) AS ?date)

  FILTER((?date >= "2024-01-01"^^xsd:date) && (?date <= "2024-12-31"^^xsd:date))

  # Inflows are negative for XIRR; outflows are positive
  BIND(
    IF(?type IN ("SIP", "Lump Sum", "Deposit"),
       -?amount,   # inflow
       ?amount     # outflow (Redemption/Withdrawal)
    ) AS ?signedAmount
  )
}

