    BIND(IF(?cashFlow wm:type "SIP" || ?cashFlow wm:type "Lump Sum" || ?cashFlow wm:type "Deposit", -1 * xsd:decimal(?amount), xsd:decimal(?amount)) AS ?signedAmount)
  }
