    FILTER (?date >= "2024-01-01" && ?date <= "2024-12-31")
    BIND(IF(?cashFlowTypeLabel IN ("SIP", "Lump Sum", "Deposit"), -xsd:decimal(?amount), xsd:decimal(?amount)) AS ?signedAmount)
  }

  BIND(SUM(?signedAmount) AS ?netCashFlow)

