PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT SUM(xsd:decimal(?amount)) AS ?totalNetCashFlow
WHERE {
  ?investor wm:hasHolding ?holding .
  ?holding wm:hasInvestmentType ?invType .
  ?invType rdfs:label "Equity" .

  ?investor wm:hasCashFlow ?cashFlow .
  ?cashFlow wm:date ?date ;
            wm:amount ?amount ;
            wm:hasCashFlowType ?cfType .

  BIND(xsd:integer(SUBSTR(?date, 1, 4)) AS ?year)
  FILTER(?year = 2024)

  OPTIONAL {
    ?cfType rdfs:label ?typeLabel .
  }

  BIND(IF(?typeLabel IN ("SIP", "Lump Sum", "Deposit"), -xsd:decimal(?amount), xsd:decimal(?amount)) AS ?signedAmount)
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT 
  AVG(?netCashFlow) AS ?averageNetCashFlow
WHERE {
  {
    SELECT 
      ?investorId 
      (SUM(IF(?cashFlowType = "Inflow", -?amount, ?amount)) AS ?netCashFlow)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?amountStr ;
                wm:hasCashFlowType ?cashFlowTypeNode .

      BIND(xsd:decimal(?amountStr) AS ?amount)
      BIND(REPLACE(STRAFTER(STR(?cashFlowTypeNode), "#"), "CashFlowType-", "") AS ?cashFlowTypeLabel)
      BIND(IF(?cashFlowTypeLabel = "SIP" || ?cashFlowTypeLabel = "LumpSum" || ?cashFlowTypeLabel = "Deposit", "Inflow", "Outflow") AS ?cashFlowType)

      ?investor wm:investorId ?investorId .

      ?sectorAllocation a wm:SectorAllocation ;
                        wm:allocationOfInvestor ?investor ;
                        wm:sector "Automobile" ;
                        wm:allocationPct ?allocationPctStr .

      BIND(xsd:decimal(?allocationPctStr) AS ?allocationPct)
      FILTER(?allocationPct > 0)
    }
    GROUP BY ?investorId
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT DISTINCT ?investor
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance/wm:label "Aggressive" ;
            wm:hasInvestmentGoal ?goal ;
            wm:hasCashFlow ?cashFlow .

  ?goal wm:shortfall ?shortfall .
  FILTER(xsd:decimal(?shortfall) > 0)

  ?cashFlow wm:date ?date ;
             wm:amount ?amount ;
             wm:type ?type .

  BIND(IF(?type IN ("SIP", "Lump Sum", "Deposit"), -xsd:decimal(?amount), xsd:decimal(?amount)) AS ?signedAmount)
  BIND(STRBEFORE(?date, "-") AS ?year)
  FILTER(?year = "2025")

  {
    SELECT ?investor (SUM(?signedAmount) AS ?netCashFlow)
    WHERE {
      ?investor wm:hasCashFlow ?cashFlow .
      ?cashFlow wm:date ?date ;
                 wm:amount ?amount ;
                 wm:type ?type .

      BIND(IF(?type IN ("SIP", "Lump Sum", "Deposit"), -xsd:decimal(?amount), xsd:decimal(?amount)) AS ?signedAmount)
      BIND(STRBEFORE(?date, "-") AS ?year)
      FILTER(?year = "2025")
    }
    GROUP BY ?investor
  }

  FILTER(?netCashFlow < 0)
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?netCashFlow)
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:hasInvestmentGoal ?goal ;
            wm:hasCashFlow ?cashFlow .

  ?goal wm:shortfall ?shortfall .
  FILTER(xsd:decimal(?shortfall) > 0)

  ?investor wm:hasRiskTolerance ?riskTolerance .
  ?riskTolerance rdfs:label "Aggressive" .

  ?cashFlow wm:amount ?amount ;
             wm:hasCashFlowType ?type .

  ?type rdfs:label ?typeName .
  VALUES (?typeName) { ("SIP") ("Lump Sum") ("Deposit") ("Redemption") ("Withdrawal") }

  BIND(IF(?typeName IN ("SIP", "Lump Sum", "Deposit"), -xsd:decimal(?amount), xsd:decimal(?amount)) AS ?signedAmount)
}
GROUP BY ?investorId
HAVING (SUM(xsd:decimal(?signedAmount)) != 0)
ORDER BY DESC(?netCashFlow)
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT (SUM(xsd:decimal(?amount)) AS ?totalNetCashFlow)
WHERE {
  ?investor wm:hasHolding ?holding .
  ?holding wm:investmentType "Gold" .

  ?investor wm:hasCashFlow ?cashFlow .
  ?cashFlow wm:date ?date ;
            wm:amount ?amount ;
            wm:type ?type .

  FILTER(?date >= "2024-01-01" && ?date <= "2024-12-31")

  BIND(
    IF(?type IN ("SIP", "Lump Sum", "Deposit"), -xsd:decimal(?amount), xsd:decimal(?amount))
    AS ?signedAmount
  )
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT DISTINCT ?investor
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance ?riskTolerance .
  ?riskTolerance rdfs:label "Conservative" .

  ?investor wm:hasInvestmentGoal ?goal .
  ?goal wm:shortfall ?shortfall .
  FILTER(xsd:decimal(?shortfall) > 0)

  OPTIONAL {
    ?cashFlow wm:cashFlowOfInvestor ?investor ;
              wm:date ?date ;
              wm:amount ?amount ;
              wm:hasCashFlowType ?type .
    ?type rdfs:label ?typeLabel .
    BIND(IF(?typeLabel IN ("SIP", "Lump Sum", "Deposit"), -xsd:decimal(?amount), xsd:decimal(?amount)) AS ?signedAmount)
    BIND(IF(?date >= "2025-01-01" && ?date <= "2025-12-31", ?signedAmount, 0) AS ?cy2025Flow)
  }

  BIND(COALESCE(SUM(?cy2025Flow), 0) AS ?netCashFlow2025)
  FILTER(?netCashFlow2025 < 0)
}
GROUP BY ?investor

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT AVG(?netCashFlow) AS ?averageNetCashFlow
WHERE {
  {
    SELECT ?investor (SUM(IF(?type = "Inflow", -?amount, ?amount)) AS ?netCashFlow)
    WHERE {
      ?cashFlow wm:cashFlowOfInvestor ?investor ;
                wm:amount ?amountStr ;
                wm:type ?typeStr .
      BIND(xsd:decimal(?amountStr) AS ?amount)
      BIND(IF(CONTAINS(LCASE(?typeStr), "sip") || CONTAINS(LCASE(?typeStr), "lump sum") || CONTAINS(LCASE(?typeStr), "deposit"), "Inflow", "Outflow") AS ?type)
    }
    GROUP BY ?investor
  }
  ?sectorAllocation wm:allocationOfInvestor ?investor ;
                    wm:sector "Banking" ;
                    wm:allocationPct ?allocationPctStr .
  BIND(xsd:decimal(?allocationPctStr) AS ?allocationPct)
  FILTER(?allocationPct > 0)
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?investorId ?netCashFlow
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:hasRiskTolerance ?riskTolerance ;
            wm:hasInvestmentGoal ?goal ;
            wm:hasCashFlow ?cashFlow .

  ?riskTolerance rdfs:label "Conservative" .

  ?goal wm:shortfall ?shortfall .
  FILTER(xsd:decimal(?shortfall) > 0)

  {
    SELECT ?investorId (SUM(COALESCE(xsd:decimal(?amount), 0)) AS ?netCashFlow)
    WHERE {
      ?investor wm:investorId ?investorId ;
                wm:hasCashFlow ?cashFlow .
      ?cashFlow wm:amount ?amount ;
                wm:type ?type .
      BIND(IF(?type IN ("SIP", "Lump Sum", "Deposit"), -xsd:decimal(?amount), xsd:decimal(?amount)) AS ?signedAmount)
    }
    GROUP BY ?investorId
  }
}
ORDER BY DESC(?netCashFlow)
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT AVG(?netCashFlow) AS ?averageNetCashFlow
WHERE {
  {
    SELECT ?investorId (SUM(IF(?type IN ("SIP", "Lump Sum", "Deposit"), -?amount, ?amount)) AS ?netCashFlow)
    WHERE {
      ?cashFlow wm:cashFlowOfInvestor ?investor .
      ?investor wm:investorId ?investorId .
      ?cashFlow wm:amount ?amountStr .
      ?cashFlow wm:type ?type .
      BIND(xsd:decimal(?amountStr) AS ?amount)
    }
    GROUP BY ?investorId
  }
  {
    SELECT DISTINCT ?investorId
    WHERE {
      ?sectorAlloc wm:allocationOfInvestor ?investor .
      ?investor wm:investorId ?investorId .
      ?sectorAlloc wm:sector "Consumer Goods" .
      ?sectorAlloc wm:allocationPct ?allocPctStr .
      BIND(xsd:decimal(?allocPctStr) AS ?allocPct)
      FILTER(?allocPct > 0)
    }
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT DISTINCT ?investor
WHERE {
  ?investor a wm:Investor ;
            wm:hasRiskTolerance/wm:riskTolerance "Moderate" ;
            wm:hasInvestmentGoal ?goal ;
            wm:hasCashFlow ?cashFlow .

  ?goal wm:shortfall ?shortfall .
  FILTER(xsd:decimal(?shortfall) > 0)

  ?cashFlow wm:date ?date ;
             wm:amount ?amount ;
             wm:type ?type .

  BIND(IF(?type IN ("SIP", "Lump Sum", "Deposit"), -xsd:decimal(?amount), xsd:decimal(?amount)) AS ?signedAmount)
  BIND(STRBEFORE(?date, "-") AS ?year)
  FILTER(?year = "2025")

  {
    SELECT ?investor (SUM(?signedAmount) AS ?netCashFlow)
    WHERE {
      ?investor wm:hasCashFlow ?cashFlow .
      ?cashFlow wm:date ?date ;
                 wm:amount ?amount ;
                 wm:type ?type .

      BIND(IF(?type IN ("SIP", "Lump Sum", "Deposit"), -xsd:decimal(?amount), xsd:decimal(?amount)) AS ?signedAmount)
      BIND(STRBEFORE(?date, "-") AS ?year)
      FILTER(?year = "2025")
    }
    GROUP BY ?investor
  }

  FILTER(?netCashFlow < 0)
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?investorId ?netCashFlow
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:hasSegment ?segment ;
            wm:hasInvestmentGoal ?goal ;
            wm:hasCashFlow ?cashFlow .

  ?segment rdfs:label "Moderate" .

  ?goal wm:shortfall ?shortfall .
  FILTER(xsd:decimal(?shortfall) > 0)

  {
    SELECT ?investorId (SUM(COALESCE(xsd:decimal(?amount), 0)) AS ?netCashFlow)
    WHERE {
      ?cashFlow wm:cashFlowOfInvestor ?investor ;
                wm:amount ?amount ;
                wm:type ?type .

      BIND(IF(?type IN ("SIP", "Lump Sum", "Deposit"), -xsd:decimal(?amount), xsd:decimal(?amount)) AS ?signedAmount)
    }
    GROUP BY ?investorId
  }
}
ORDER BY DESC(?netCashFlow)
LIMIT 10

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT DISTINCT ?investor
WHERE {
  ?investor a wm:Investor ;
            wm:hasHolding ?holding .
  ?holding wm:hasCategory ?category .
  ?category rdfs:label "Equity" .

  OPTIONAL {
    ?cashFlow wm:cashFlowOfInvestor ?investor ;
              wm:amount ?amount ;
              wm:date ?date ;
              wm:hasCashFlowType ?type .
    FILTER (YEAR(xsd:date(?date)) = 2025)
  }

  BIND(IF(BOUND(?amount), IF(?type rdfs:label "Redemption" || ?type rdfs:label "Withdrawal", ?amount, -?amount), 0) AS ?netCashFlow)

  GROUP BY ?investor
  HAVING (SUM(?netCashFlow) < 0)
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT AVG(?netCashFlow) AS ?averageNetCashFlow
WHERE {
  {
    SELECT ?investor (SUM(IF(?type = "Inflow", -?amount, ?amount)) AS ?netCashFlow)
    WHERE {
      ?cashFlow wm:cashFlowOfInvestor ?investor ;
                wm:amount ?amount ;
                wm:type ?type .
      FILTER(?type IN ("Inflow", "Outflow"))
    }
    GROUP BY ?investor
  }
  {
    SELECT DISTINCT ?investor
    WHERE {
      ?sectorAllocation wm:allocationOfInvestor ?investor ;
                        wm:sector "Corporate" ;
                        wm:allocationPct ?allocation .
      FILTER(xsd:decimal(?allocation) > 0)
    }
  }
}
